// Helper function to get time period content (icon or text)
@Composable
fun TimePeriodContent(
    period: String,
    useSymbols: Boolean,
    fontColor: Color,
    useEmojiSymbols: Boolean = true,
    modifier: Modifier = Modifier
) {
    if (useSymbols) {
        if (useEmojiSymbols) {
            val emoji = when (period.lowercase()) {
                "morning", "morgen", "mañana" -> "☀️"
                "afternoon", "mittag", "mediodía" -> "🌤️"
                "evening", "abend", "tarde" -> "🌅"
                "night", "nacht", "noche" -> "🌙"
                else -> "☀️"
            }
            Text(
                text = emoji,
                fontSize = 16.sp,
                textAlign = TextAlign.Center,
                modifier = modifier
                    .size(20.dp)
                    .wrapContentSize(Alignment.Center)
            )
        } else {
            val icon = when (period.lowercase()) {
                "morning", "morgen", "mañana" -> TimeIcons.Morning
                "afternoon", "mittag", "mediodía" -> TimeIcons.Afternoon
                "evening", "abend", "tarde" -> TimeIcons.Evening
                "night", "nacht", "noche" -> TimeIcons.Night
                else -> TimeIcons.Morning
            }
            Icon(
                imageVector = icon,
                contentDescription = period,
                tint = fontColor,
                modifier = modifier.size(20.dp)
            )
        }
    } else {
        Text(
            text = period,
            color = fontColor,
            fontSize = 10.sp,
            textAlign = TextAlign.Center,
            modifier = modifier
        )
    }
}

@Serializable
data class AppSettings(
    @Serializable(with = ColorSerializer::class)
