    val portraitHeightScale: Float = 1f, // Portrait orientation height scale
    val landscapeScale: Float = 1f, // Landscape orientation scale
    val landscapeWidthScale: Float = 2.2f, // Landscape orientation width scale
    val landscapeHeightScale: Float = 1f, // Landscape orientation height scale
    val heightScale: Float = 1f, // Current height scale
    val proportionalZoom: Boolean = false, // Whether zoom controls affect both dimensions proportionally
    val showArchivedEntries: Boolean = true, // Archive/hide view state persistence
    val showChartStatistics: Boolean = true, // Show/hide chart statistics section
    val usePaginationMode: Boolean = true, // Use pagination (true) or continuous scroll (false)
    val useButtonPaging: Boolean = false // Use button-based paging (true) or scroll-based paging (false) - only applies when usePaginationMode is true
)

@Serializable
data class Marker(
    val id: String = "",
    val type: String, // "feel_bad", "custom"
    val startTime: String, // "morning", "afternoon", "evening", "night", "all_day", or "cell_specific"
    val reasons: List<String> = emptyList(), // "headache", "nausea", "high_blood_sugar", "low_energy"
    val customNote: String = "",
    val timestamp: Long = 0L,
    val customMarkerTypeId: String? = null, // Links to CustomMarkerType.id when type is "custom"
    val cellId: String? = null // For cell-specific markers (date, remark, custom columns) - stores column ID or "date"
)

@Serializable
data class DiabetesEntry(
    val id: String = UUID.randomUUID().toString(),
    var date: String = "",
    var morningBloodSugarLevel: String = "",
    var afternoonBloodSugarLevel: String = "",
    var eveningBloodSugarLevel: String = "",
    var nightBloodSugarLevel: String = "",
    var morningInsulin: String = "",
    var afternoonInsulin: String = "",
    var eveningInsulin: String = "",
    var remarks: String = "",
    var foodEntriesByColumn: Map<String, List<FoodPreset>> = emptyMap(),
    var customColumnData: Map<String, String> = emptyMap(), // columnId -> value
    var markers: List<Marker> = emptyList(), // Markers for this date
    var isTestData: Boolean = false // Flag to identify test data entries
)

@Serializable
enum class BackupType {
    SETTINGS_ONLY,
    DATA_ONLY,
    ALL
}

@Serializable
data class BackupData(
    val appVersion: String = "1.0.0",
    val exportDate: String,
    val exportType: BackupType,
    val settings: AppSettings? = null,
    val entries: List<DiabetesEntry>? = null,
    val foodPresets: List<FoodPreset>? = null,
    val colorPresets: List<ColorPreset>? = null,
    val colorSchemes: List<ColorScheme>? = null,
    val viewPresets: List<ViewPreset>? = null,
    val securedEntryIds: Set<String>? = null,
    val customColumns: List<CustomColumn>? = null
)

@Serializable
data class BackupMetadata(
    val settingsCount: Int = 0,
    val entriesCount: Int = 0,
    val foodPresetsCount: Int = 0,
    val colorPresetsCount: Int = 0,
    val colorSchemesCount: Int = 0,
    val viewPresetsCount: Int = 0,
    val customColumnsCount: Int = 0,
    val hasSecuredEntries: Boolean = false
)

object SettingsManager {
    private const val SETTINGS_NAME = "app_settings"
    private const val SETTINGS_KEY = "settings"
    private const val COLOR_SCHEMES_KEY = "color_schemes"
    private const val FOOD_PRESETS_KEY = "food_presets"
    private const val VIEW_PRESETS_KEY = "view_presets"
    private const val SECURED_ENTRY_IDS_KEY = "secured_entry_ids"
    
    // Cache values in memory to avoid frequent disk reads
    private var cachedSettings: AppSettings? = null
    private var cachedColorSchemes: List<ColorScheme>? = null
    private var cachedViewPresets: List<ViewPreset>? = null
    private var cachedFoodPresets: List<FoodPreset>? = null

    fun getDefaultColors(isDarkMode: Boolean): Quartet<Color, Color, Color, Color> {
        return if (isDarkMode) {
            Quartet(Color.White, Color.DarkGray, Color.Black, Color(0xFF7986CB).copy(alpha = 0.3f)) // Lighter indigo for dark mode
        } else {
            Quartet(Color.Black, Color.LightGray, Color.Black, Color(0xFF3F51B5).copy(alpha = 0.3f)) // Standard indigo for light mode
        }
    }
    
    // Helper class for returning 4 values
    data class Quartet<A, B, C, D>(val first: A, val second: B, val third: C, val fourth: D)

    fun loadSettings(context: Context): AppSettings {
        // Return cached settings if available
        cachedSettings?.let { return it }
        
        val sharedPrefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        val json = sharedPrefs.getString(SETTINGS_KEY, null)
        val settings = if (json != null) {
            try {
                Json.decodeFromString<AppSettings>(json)
            } catch (e: Exception) {
                createDefaultSettings(context)
            }
        } else {
            createDefaultSettings(context)
        }
        
        // Cache the result
        cachedSettings = settings
        return settings
    }
    
    private fun createDefaultSettings(context: Context): AppSettings {
        val isDarkMode = context.resources.configuration.uiMode and 
            Configuration.UI_MODE_NIGHT_MASK == Configuration.UI_MODE_NIGHT_YES
        val (fontColor, backgroundColor, gridColor) = getDefaultColors(isDarkMode)
        return AppSettings(
            fontColor = fontColor,
            backgroundColor = backgroundColor,
            gridColor = gridColor,
            isDarkMode = isDarkMode
        )
    }

    fun saveSettings(context: Context, settings: AppSettings) {
        // Update cache immediately
        cachedSettings = settings
        
        // Save to disk in background
        CoroutineScope(Dispatchers.IO).launch {
            val sharedPrefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
            val json = Json.encodeToString(settings)
            sharedPrefs.edit().putString(SETTINGS_KEY, json).apply()
        }
    }

    fun saveColorScheme(context: Context, scheme: ColorScheme) {
        // Update cache first
        val currentSchemes = cachedColorSchemes ?: getColorSchemes(context)
        val updatedSchemes = currentSchemes + scheme
        cachedColorSchemes = updatedSchemes
        
        // Save to disk in background
        CoroutineScope(Dispatchers.IO).launch {
            val sharedPrefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
            sharedPrefs.edit().putString(COLOR_SCHEMES_KEY, Json.encodeToString(updatedSchemes)).apply()
        }
    }

    fun getColorSchemes(context: Context): List<ColorScheme> {
        // Return cached schemes if available
        cachedColorSchemes?.let { return it }
        
        val sharedPrefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        val json = sharedPrefs.getString(COLOR_SCHEMES_KEY, "[]") ?: "[]"
        return try {
            Json.decodeFromString<List<ColorScheme>>(json).also { cachedColorSchemes = it }
        } catch (e: Exception) {
            emptyList<ColorScheme>().also { cachedColorSchemes = it }
        }
    }

    fun deleteColorScheme(context: Context, schemeId: String) {
        // Update cache first
        val currentSchemes = cachedColorSchemes ?: getColorSchemes(context)
        val updatedSchemes = currentSchemes.filter { it.id != schemeId }
        cachedColorSchemes = updatedSchemes
        
        // Save to disk in background
        CoroutineScope(Dispatchers.IO).launch {
            val sharedPrefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
            sharedPrefs.edit().putString(COLOR_SCHEMES_KEY, Json.encodeToString(updatedSchemes)).apply()
        }
    }

    fun clearColorSchemes(context: Context) {
        // Clear cache
        cachedColorSchemes = emptyList()
        
        // Clear from disk
        CoroutineScope(Dispatchers.IO).launch {
            val sharedPrefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
            sharedPrefs.edit().putString(COLOR_SCHEMES_KEY, "[]").apply()
        }
    }

    // ---- VIEW PRESET FUNCTIONS ----
    fun getViewPresets(context: Context): List<ViewPreset> {
        // Return cached presets if available
        cachedViewPresets?.let { return it }
        
        val sharedPrefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        val json = sharedPrefs.getString(VIEW_PRESETS_KEY, "[]") ?: "[]"
        return try { 
            Json.decodeFromString<List<ViewPreset>>(json).also { cachedViewPresets = it } 
        } catch (e: Exception) { 
            emptyList<ViewPreset>().also { cachedViewPresets = it } 
        }
    }

    fun saveViewPresets(context: Context, presets: List<ViewPreset>) {
        // Update cache first
        cachedViewPresets = presets
        
        // Save to disk in background
        CoroutineScope(Dispatchers.IO).launch {
            val sharedPrefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
            sharedPrefs.edit().putString(VIEW_PRESETS_KEY, Json.encodeToString(presets)).apply()
        }
    }

    fun saveFoodPreset(context: Context, preset: FoodPreset) {
        val sharedPrefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        val existingJson = sharedPrefs.getString(FOOD_PRESETS_KEY, "[]") ?: "[]"
        val presets = Json.decodeFromString<List<FoodPreset>>(existingJson)
        val updatedPresets = presets + preset
        sharedPrefs.edit().putString(FOOD_PRESETS_KEY, Json.encodeToString(updatedPresets)).apply()
    }

    fun getFoodPresets(context: Context): List<FoodPreset> {
        val sharedPrefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        val json = sharedPrefs.getString(FOOD_PRESETS_KEY, "[]") ?: "[]"
        return Json.decodeFromString(json)
    }

    fun deleteFoodPreset(context: Context, presetId: String) {
        val sharedPrefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        val existingJson = sharedPrefs.getString(FOOD_PRESETS_KEY, "[]") ?: "[]"
        val presets = Json.decodeFromString<List<FoodPreset>>(existingJson)
        val updatedPresets = presets.filter { it.id != presetId }
        sharedPrefs.edit().putString(FOOD_PRESETS_KEY, Json.encodeToString(updatedPresets)).apply()
    }

    // Secure mode persistence methods
    fun saveSecuredEntryIds(context: Context, securedIds: Set<String>) {
        val sharedPrefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        val idsJson = Json.encodeToString(securedIds.toList())
        sharedPrefs.edit().putString(SECURED_ENTRY_IDS_KEY, idsJson).apply()
    }

    fun loadSecuredEntryIds(context: Context): Set<String> {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        val json = prefs.getString("secured_entry_ids", null) ?: return emptySet()
        return try {
            Json.decodeFromString<Set<String>>(json)
        } catch (e: Exception) {
            emptySet()
        }
    }
    
    // Filter persistence methods
    fun saveLastDateFilter(context: Context, dateFilter: DateFilter, customStartDate: LocalDate? = null, customEndDate: LocalDate? = null, showEmptyDates: Boolean = true, flexibleNumber: Int = 1, flexibleUnit: TimeUnit = TimeUnit.DAY) {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        prefs.edit()
            .putString("last_date_filter", dateFilter.name)
            .putString("custom_start_date", customStartDate?.toString())
            .putString("custom_end_date", customEndDate?.toString())
            .putBoolean("show_empty_dates_in_filter", showEmptyDates)
            .putInt("flexible_number", flexibleNumber)
            .putString("flexible_unit", flexibleUnit.name)
            .apply()
    }
    
    fun loadLastDateFilter(context: Context): Tuple5<DateFilter, Pair<LocalDate?, LocalDate?>, Boolean, Int, TimeUnit> {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        val filterName = prefs.getString("last_date_filter", DateFilter.ALL.name) ?: DateFilter.ALL.name
        val startDateStr = prefs.getString("custom_start_date", null)
        val endDateStr = prefs.getString("custom_end_date", null)
        val showEmptyDates = prefs.getBoolean("show_empty_dates_in_filter", true)
        val flexibleNumber = prefs.getInt("flexible_number", 1)
        val flexibleUnitStr = prefs.getString("flexible_unit", TimeUnit.DAY.name) ?: TimeUnit.DAY.name
        
        val dateFilter = try {
            DateFilter.valueOf(filterName)
        } catch (e: Exception) {
            DateFilter.ALL
        }
        
        val startDate = try {
            startDateStr?.let { LocalDate.parse(it) }
        } catch (e: Exception) {
            null
        }
        
        val endDate = try {
            endDateStr?.let { LocalDate.parse(it) }
        } catch (e: Exception) {
            null
        }
        
        val flexibleUnit = try {
            TimeUnit.valueOf(flexibleUnitStr)
        } catch (e: Exception) {
            TimeUnit.DAY
        }
        
        return Tuple5(dateFilter, Pair(startDate, endDate), showEmptyDates, flexibleNumber, flexibleUnit)
    }
    
    // Auto-save on exit setting methods
    fun saveAutoSaveOnExit(context: Context, autoSave: Boolean) {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        prefs.edit().putBoolean("auto_save_on_exit", autoSave).apply()
    }
    
    fun loadAutoSaveOnExit(context: Context): Boolean {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        return prefs.getBoolean("auto_save_on_exit", true) // Default to true (enabled)
    }
    
    // Auto-backup on exit setting methods
    fun saveAutoBackupOnExit(context: Context, autoBackup: Boolean) {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        prefs.edit().putBoolean("auto_backup_on_exit", autoBackup).apply()
    }
    
    fun loadAutoBackupOnExit(context: Context): Boolean {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        return prefs.getBoolean("auto_backup_on_exit", true) // Default to true (activated)
    }
    
    // Advanced auto-backup settings
    fun saveAutoBackupMaxCount(context: Context, maxCount: Int) {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        prefs.edit().putInt("auto_backup_max_count", maxCount).apply()
    }
    
    fun loadAutoBackupMaxCount(context: Context): Int {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        return prefs.getInt("auto_backup_max_count", 5) // Default: 5 backups
    }
    
    fun saveAutoBackupFrequency(context: Context, frequency: String) {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        prefs.edit().putString("auto_backup_frequency", frequency).apply()
    }
    
    fun loadAutoBackupFrequency(context: Context): String {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        return prefs.getString("auto_backup_frequency", "Daily") ?: "Daily"
    }
    
    fun saveAutoBackupPath(context: Context, path: String) {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        prefs.edit().putString("auto_backup_path", path).apply()
    }
    
    fun loadAutoBackupPath(context: Context): String {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        val defaultPath = android.os.Environment.getExternalStoragePublicDirectory(
            android.os.Environment.DIRECTORY_DOWNLOADS
        ).absolutePath
        return prefs.getString("auto_backup_path", defaultPath) ?: defaultPath
    }
    
    fun saveLastAutoBackupDate(context: Context, date: String) {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        prefs.edit().putString("last_auto_backup_date", date).apply()
    }
    
    fun loadLastAutoBackupDate(context: Context): String {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        return prefs.getString("last_auto_backup_date", "") ?: ""
    }
    
    // Test data enabled setting methods
    fun saveTestDataEnabled(context: Context, enabled: Boolean) {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        prefs.edit().putBoolean("test_data_enabled", enabled).apply()
    }
    
    fun loadTestDataEnabled(context: Context): Boolean {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        return prefs.getBoolean("test_data_enabled", false) // Default to false (disabled)
    }
    
    // Custom header text persistence methods
    fun saveCustomHeaderText(context: Context, headerKey: String, customText: String) {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        prefs.edit().putString("custom_header_$headerKey", customText).apply()
    }
    
    fun loadCustomHeaderText(context: Context, headerKey: String, defaultText: String): String {
        val prefs = context.getSharedPreferences(SETTINGS_NAME, Context.MODE_PRIVATE)
        return prefs.getString("custom_header_$headerKey", defaultText) ?: defaultText
    }
}

object BackupManager {
    
    /**
     * Creates a backup based on the specified type
     */
    fun createBackup(context: Context, backupType: BackupType): BackupData {
        val currentDate = java.time.LocalDateTime.now().toString()
        
        return when (backupType) {
            BackupType.SETTINGS_ONLY -> BackupData(
                exportDate = currentDate,
                exportType = backupType,
                settings = SettingsManager.loadSettings(context),
                colorPresets = PresetManager.getPresets(context),
                colorSchemes = SettingsManager.getColorSchemes(context),
                viewPresets = SettingsManager.getViewPresets(context),
                customColumns = CustomColumnManager.getCustomColumns(context)
            )
            
            BackupType.DATA_ONLY -> BackupData(
                exportDate = currentDate,
                exportType = backupType,
                entries = DataManager.getEntries(context),
                foodPresets = PresetManager.getFoodPresets(context),
                colorPresets = PresetManager.getPresets(context),
                securedEntryIds = SettingsManager.loadSecuredEntryIds(context),
                customColumns = CustomColumnManager.getCustomColumns(context)
            )
            
            BackupType.ALL -> BackupData(
                exportDate = currentDate,
                exportType = backupType,
                settings = SettingsManager.loadSettings(context),
                entries = DataManager.getEntries(context),
                foodPresets = PresetManager.getFoodPresets(context),
                colorPresets = PresetManager.getPresets(context),
                colorSchemes = SettingsManager.getColorSchemes(context),
                viewPresets = SettingsManager.getViewPresets(context),
                securedEntryIds = SettingsManager.loadSecuredEntryIds(context),
                customColumns = CustomColumnManager.getCustomColumns(context)
            )
        }
    }
    
    /**
     * Exports backup data to a file URI
     */
    fun exportBackupToFile(context: Context, backupData: BackupData, fileUri: Uri) {
        try {
            // Debug: Log custom column data before export
            backupData.entries?.forEach { entry ->
                if (entry.customColumnData.isNotEmpty()) {
                    println("DEBUG EXPORT: Entry ${entry.date} has customColumnData: ${entry.customColumnData}")
                }
            }
            
            context.contentResolver.openOutputStream(fileUri)?.use { outputStream ->
                outputStream.bufferedWriter().use { writer ->
                    val backupJson = Json.encodeToString(backupData)
                    writer.write(backupJson)
                    
                    // Debug: Verify JSON contains customColumnData
                    if (backupJson.contains("customColumnData")) {
                        println("DEBUG EXPORT: JSON contains customColumnData field")
                    } else {
                        println("DEBUG EXPORT: WARNING - JSON does NOT contain customColumnData field!")
                    }
                }
            }
            
            val typeText = when (backupData.exportType) {
                BackupType.SETTINGS_ONLY -> context.getString(R.string.settings)
                BackupType.DATA_ONLY -> "Data"
                BackupType.ALL -> "Complete"
            }
            
            Toast.makeText(context, "$typeText backup exported successfully", Toast.LENGTH_LONG).show()
        } catch (e: Exception) {
            Toast.makeText(context, "Failed to export backup: ${e.message}", Toast.LENGTH_SHORT).show()
        }
    }
    
    /**
     * Reads and validates backup data from a file URI
     */
    fun readBackupFromFile(context: Context, fileUri: Uri): BackupData? {
        return try {
            context.contentResolver.openInputStream(fileUri)?.use { inputStream ->
                inputStream.bufferedReader().use { reader ->
                    val backupJson = reader.readText()
                    Json.decodeFromString<BackupData>(backupJson)
                }
            }
        } catch (e: Exception) {
            Toast.makeText(context, "Failed to read backup file: ${e.message}", Toast.LENGTH_SHORT).show()
            null
        }
    }
    
    /**
     * Gets metadata about backup contents for preview
     */
    fun getBackupMetadata(backupData: BackupData): BackupMetadata {
        return BackupMetadata(
            settingsCount = if (backupData.settings != null) 1 else 0,
            entriesCount = backupData.entries?.size ?: 0,
            foodPresetsCount = backupData.foodPresets?.size ?: 0,
            colorSchemesCount = backupData.colorSchemes?.size ?: 0,
            viewPresetsCount = backupData.viewPresets?.size ?: 0,
            customColumnsCount = backupData.customColumns?.size ?: 0,
            hasSecuredEntries = !backupData.securedEntryIds.isNullOrEmpty()
        )
    }
    
    /**
     * Imports backup data with merge/replace options
     */
    fun importBackup(context: Context, backupData: BackupData, mergeWithExisting: Boolean = true) {
        try {
            // Track column ID mapping for remapping entry data
            var columnIdMapping: Map<String, String>? = null
            
            // Import settings
            backupData.settings?.let { settings ->
                SettingsManager.saveSettings(context, settings)
            }
            
            // Import custom columns first (before entries, so we have the mapping)
            backupData.customColumns?.let { columns ->
                if (mergeWithExisting) {
                    val existingColumns = CustomColumnManager.getCustomColumns(context)
                    val (mergedColumns, idMapping) = mergeCustomColumnsWithMapping(existingColumns, columns)
                    columnIdMapping = idMapping
                    CustomColumnManager.saveCustomColumns(context, mergedColumns)
                } else {
                    CustomColumnManager.saveCustomColumns(context, columns)
                }
            }
            
            // Import entries
            backupData.entries?.let { entries ->
                // Remap column IDs in entry data if needed
                val mapping = columnIdMapping
                val remappedEntries = if (mapping != null && mapping.isNotEmpty()) {
                    entries.map { entry ->
                        if (entry.customColumnData.isEmpty()) {
                            entry
                        } else {
                            val remappedData = entry.customColumnData.mapKeys { (oldId, _) ->
                                mapping[oldId] ?: oldId
                            }
                            entry.copy(customColumnData = remappedData)
                        }
                    }
                } else {
                    entries
                }
                
                if (mergeWithExisting) {
                    val existingEntries = DataManager.getEntries(context)
                    val mergedEntries = mergeEntries(existingEntries, remappedEntries)
                    DataManager.saveEntries(context, mergedEntries)
                } else {
                    DataManager.saveEntries(context, remappedEntries)
                }
            }
            
            // Import food presets
            backupData.foodPresets?.let { presets ->
                if (mergeWithExisting) {
                    val existingPresets = PresetManager.getFoodPresets(context)
                    val mergedPresets = mergeFoodPresets(existingPresets, presets)
                    PresetManager.saveFoodPresets(context, mergedPresets)
                } else {
                    PresetManager.saveFoodPresets(context, presets)
                }
            }
            
            // Import color schemes
            backupData.colorSchemes?.let { schemes ->
                if (mergeWithExisting) {
                    schemes.forEach { scheme ->
                        SettingsManager.saveColorScheme(context, scheme)
                    }
                } else {
                    SettingsManager.clearColorSchemes(context)
                    schemes.forEach { scheme ->
                        SettingsManager.saveColorScheme(context, scheme)
                    }
                }
            }
            
            // Import color presets
            backupData.colorPresets?.let { presets ->
                if (mergeWithExisting) {
                    val existingPresets = PresetManager.getPresets(context)
                    val mergedPresets = mergeColorPresets(existingPresets, presets)
                    // Clear existing and save merged presets
                    clearColorPresets(context)
                    mergedPresets.forEach { preset ->
                        PresetManager.savePreset(context, preset)
                    }
                } else {
                    clearColorPresets(context)
                    presets.forEach { preset ->
                        PresetManager.savePreset(context, preset)
                    }
                }
            }
            
            // Import view presets
            backupData.viewPresets?.let { presets ->
                if (mergeWithExisting) {
                    val existingPresets = SettingsManager.getViewPresets(context)
                    val mergedPresets = mergeViewPresets(existingPresets, presets)
                    SettingsManager.saveViewPresets(context, mergedPresets)
                } else {
                    SettingsManager.saveViewPresets(context, presets)
                }
            }
            
            // Import secured entry IDs
            backupData.securedEntryIds?.let { securedIds ->
                if (mergeWithExisting) {
                    val existingIds = SettingsManager.loadSecuredEntryIds(context)
                    SettingsManager.saveSecuredEntryIds(context, existingIds + securedIds)
                } else {
                    SettingsManager.saveSecuredEntryIds(context, securedIds)
                }
            }
            
            val actionText = if (mergeWithExisting) "merged" else "restored"
            Toast.makeText(context, "Backup $actionText successfully", Toast.LENGTH_LONG).show()
            
        } catch (e: Exception) {
            Toast.makeText(context, "Failed to import backup: ${e.message}", Toast.LENGTH_SHORT).show()
        }
    }
    
    /**
     * Merges existing entries with backup entries, updating existing ones and adding new ones
     */
    private fun mergeEntries(existing: List<DiabetesEntry>, backup: List<DiabetesEntry>): List<DiabetesEntry> {
        val backupMap = backup.associateBy { it.id }
        val existingIds = existing.map { it.id }.toSet()
        
        // Update existing entries with backup data (preserves all fields including customColumnData)
        val updatedExisting = existing.map { entry ->
            backupMap[entry.id] ?: entry
        }
        
        // Add new entries that don't exist
        val newEntries = backup.filter { it.id !in existingIds }
        
        return updatedExisting + newEntries
    }
    
    /**
     * Merges existing food presets with backup presets, avoiding duplicates
     */
    private fun mergeFoodPresets(existing: List<FoodPreset>, backup: List<FoodPreset>): List<FoodPreset> {
        val existingNames = existing.map { "${it.name}_${it.emoji}" }.toSet()
        val newPresets = backup.filter { "${it.name}_${it.emoji}" !in existingNames }
        return existing + newPresets
    }
    
    /**
     * Merges existing color presets with backup presets, avoiding duplicates by color and category
     */
    private fun mergeColorPresets(existing: List<ColorPreset>, new: List<ColorPreset>): List<ColorPreset> {
        val existingKeys = existing.map { "${it.color.value}-${it.category}" }.toSet()
        val uniqueNew = new.filter { "${it.color.value}-${it.category}" !in existingKeys }
        return existing + uniqueNew
    }
    
    /**
     * Clears all color presets
     */
    private fun clearColorPresets(context: Context) {
        val prefs = context.getSharedPreferences("color_presets", Context.MODE_PRIVATE)
        prefs.edit().remove("saved_presets").apply()
    }

    /**
     * Merges existing view presets with backup presets, avoiding duplicates by name
     */
    private fun mergeViewPresets(existing: List<ViewPreset>, new: List<ViewPreset>): List<ViewPreset> {
        val existingNames = existing.map { it.name }.toSet()
        val uniqueNew = new.filter { it.name !in existingNames }
        return existing + uniqueNew
    }
    
    /**
     * Merges existing custom columns with backup custom columns, avoiding duplicates by ID
     */
    private fun mergeCustomColumns(existing: List<CustomColumn>, new: List<CustomColumn>): List<CustomColumn> {
        val existingIds = existing.map { it.id }.toSet()
        val uniqueNew = new.filter { it.id !in existingIds }
        return existing + uniqueNew
    }
    
    /**
     * Merges custom columns with duplicate name detection and returns ID mapping
     * Returns: Pair(merged columns, Map of old ID -> new ID for remapping entry data)
     * 
     * Strategy:
     * - Keep all existing columns as-is
     * - Add backup columns, but rename them with " (Backup)" suffix if name conflicts exist
     * - No ID mapping needed since we preserve all columns with their original IDs
     */
    private fun mergeCustomColumnsWithMapping(existing: List<CustomColumn>, new: List<CustomColumn>): Pair<List<CustomColumn>, Map<String, String>> {
        val finalColumns = mutableListOf<CustomColumn>()
        val existingNames = existing.map { it.name.lowercase() }.toSet()
        val existingIds = existing.map { it.id }.toSet()
        
        // Add all existing columns first
        finalColumns.addAll(existing)
        
        // Add backup columns, renaming if name conflicts exist
        new.forEach { backupCol ->
            when {
                // Same ID already exists - skip it (already in existing)
                backupCol.id in existingIds -> {
                    println("DEBUG MERGE: Column '${backupCol.name}' (${backupCol.id}) already exists, skipping")
                }
                
                // Name conflict - rename backup column with (Backup) suffix
                backupCol.name.lowercase() in existingNames -> {
                    val renamedColumn = backupCol.copy(name = "${backupCol.name} (Backup)")
                    finalColumns.add(renamedColumn)
                    println("DEBUG MERGE: Column '${backupCol.name}' name conflicts, renamed to '${renamedColumn.name}'")
                }
                
                // No conflict - add as-is
                else -> {
                    finalColumns.add(backupCol)
                    println("DEBUG MERGE: Adding new column '${backupCol.name}' (${backupCol.id})")
                }
            }
        }

        // No ID mapping needed - all columns keep their original IDs
        return Pair(finalColumns, emptyMap())
    }
}

object PresetManager {
    private const val PREFS_NAME = "color_presets"
    private const val KEY_PRESETS = "saved_presets"
    private const val FOOD_PRESETS_KEY = "food_presets"
    private const val COMMON_FOODS_KEY = "common_foods"
    
    private fun getPreferences(context: Context): SharedPreferences {
        return context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
    }
    
    fun savePreset(context: Context, preset: ColorPreset) {
        val prefs = getPreferences(context)
        val existingPresets = getPresets(context).toMutableList()
        existingPresets.add(preset)
        val presetsJson = Json.encodeToString(existingPresets)
        prefs.edit().putString(KEY_PRESETS, presetsJson).apply()
    }
    
    fun getPresets(context: Context): List<ColorPreset> {
        val prefs = getPreferences(context)
        val presetsJson = prefs.getString(KEY_PRESETS, "[]")
        return try {
            Json.decodeFromString(presetsJson ?: "[]")
        } catch (e: Exception) {
            emptyList()
        }
    }
    
    fun getPresetsByCategory(context: Context, category: String): List<ColorPreset> {
        return getPresets(context).filter { it.category == category }
    }
    
    fun deletePreset(context: Context, presetId: String) {
        val prefs = getPreferences(context)
        val existingPresets = getPresets(context).toMutableList()
        existingPresets.removeAll { it.id == presetId }
        val presetsJson = Json.encodeToString(existingPresets)
        prefs.edit().putString(KEY_PRESETS, presetsJson).apply()
    }

    fun getFoodPresets(context: Context): List<FoodPreset> {
        val sharedPreferences = context.getSharedPreferences("presets", Context.MODE_PRIVATE)
        val json = sharedPreferences.getString(FOOD_PRESETS_KEY, null)
        
        return if (json != null) {
            try {
                Json.decodeFromString<List<FoodPreset>>(json)
            } catch (e: Exception) {
                initializeDefaultFoodPresets(context)
            }
        } else {
            // First time - initialize with default foods
            initializeDefaultFoodPresets(context)
        }
    }
    
    private fun initializeDefaultFoodPresets(context: Context): List<FoodPreset> {
        val defaultFoods = getDefaultCommonFoods().map { (emoji, name) ->
            FoodPreset(name = name, emoji = emoji)
        }
        saveFoodPresets(context, defaultFoods)
        return defaultFoods
    }

    fun saveFoodPresets(context: Context, presets: List<FoodPreset>) {
        val sharedPreferences = context.getSharedPreferences("presets", Context.MODE_PRIVATE)
        val json = Json.encodeToString(presets)
        sharedPreferences.edit().putString(FOOD_PRESETS_KEY, json).apply()
    }

    fun addFoodPreset(context: Context, preset: FoodPreset) {
        val presets = getFoodPresets(context).toMutableList()
        presets.add(preset)
        saveFoodPresets(context, presets)
    }

    fun removeFoodPreset(context: Context, presetId: String) {
        val presets = getFoodPresets(context).toMutableList()
        presets.removeAll { it.id == presetId }
        saveFoodPresets(context, presets)
    }
    
    // Common foods persistence
    fun getCommonFoods(context: Context): List<Pair<String, String>> {
        val sharedPreferences = context.getSharedPreferences("presets", Context.MODE_PRIVATE)
        val json = sharedPreferences.getString(COMMON_FOODS_KEY, null)
        return if (json != null) {
            try {
                Json.decodeFromString<List<Pair<String, String>>>(json)
            } catch (e: Exception) {
                getDefaultCommonFoods()
            }
        } else {
            getDefaultCommonFoods()
        }
    }
    
    fun saveCommonFoods(context: Context, commonFoods: List<Pair<String, String>>) {
        val sharedPreferences = context.getSharedPreferences("presets", Context.MODE_PRIVATE)
        val json = Json.encodeToString(commonFoods)
        sharedPreferences.edit().putString(COMMON_FOODS_KEY, json).apply()
    }
    
    private fun getDefaultCommonFoods(): List<Pair<String, String>> {
        return listOf(
            "🍎" to "Apple",
            "🍌" to "Banana", 
            "🥖" to "Bread",
            "🥩" to "Meat",
            "🥗" to "Salad",
            "🥛" to "Milk",
            "🍚" to "Rice",
            "🥚" to "Egg",
            "🐟" to "Fish",
            "🥔" to "Potato",
            "🥕" to "Carrot",
            "🍝" to "Pasta"
        )
    }
}

object FoodWarningChecker {
    /**
     * Check if a food is linked to any markers with high confidence
     * Returns warning message if food is suspicious, null otherwise
     * Also triggers push notification if notifications are enabled
     */
    fun checkFoodWarning(
        context: Context,
        foodName: String,
        language: String = "English"
    ): String? {
        val patterns = PatternStorageManager.getActivePatterns(context)
        if (FoodWarningHelper.isFoodContradicted(foodName, context, patterns)) {
            return null
        }
        
        // Find patterns where this food is correlated with markers
        val suspiciousPatterns = patterns.filter { pattern ->
            pattern.patternType == PatternType.FOOD_MARKER_CORRELATION &&
            pattern.correlatedItem.equals(foodName, ignoreCase = true) &&
            pattern.confidenceScore >= 0.5f // Show warning for moderate+ confidence
        }
        
        if (suspiciousPatterns.isEmpty()) return null
        
        // Get the highest confidence pattern
        val topPattern = suspiciousPatterns.maxByOrNull { it.confidenceScore }!!
        val confidence = (topPattern.confidenceScore * 100).toInt()
        
        // Food warnings are shown as in-app dialogs only (not push notifications)
        // Push notifications are only for time-based reminders when app is closed
        
        return when (language) {
            "German" -> "⚠️ Warnung: '$foodName' wurde ${topPattern.occurrences} Mal mit '${topPattern.markerName}' in Verbindung gebracht (${confidence}% Konfidenz)."
            "Spanish" -> "⚠️ Advertencia: '$foodName' se ha vinculado ${topPattern.occurrences} veces con '${topPattern.markerName}' (${confidence}% confianza)."
            else -> "⚠️ Warning: '$foodName' has been linked to '${topPattern.markerName}' ${topPattern.occurrences} times (${confidence}% confidence)."
        }
    }
    
    /**
     * Get all suspicious foods with their associated markers
     */
    fun getSuspiciousFoods(context: Context): Map<String, List<DetectedPattern>> {
        val patterns = PatternStorageManager.getActivePatterns(context)
        
        return patterns
            .filter {
                it.patternType == PatternType.FOOD_MARKER_CORRELATION &&
                    it.confidenceScore >= 0.5f &&
                    !FoodWarningHelper.isFoodContradicted(it.correlatedItem, context, patterns)
            }
            .groupBy { it.correlatedItem }
    }
}

object DataManager {
    private const val PREFS_NAME = "diabetes_data"
    private const val KEY_ENTRIES = "entries"
    
    // Cache entries in memory to avoid frequent disk reads
    private var cachedEntries: List<DiabetesEntry>? = null
    
    // Add mutex for thread safety when accessing cached entries
    private val mutex = Mutex()
    
    // JSON parser with backward compatibility settings
    private val jsonParser = Json { 
        ignoreUnknownKeys = true
        coerceInputValues = true
        isLenient = true
    }

    private fun getPreferences(context: Context): SharedPreferences {
        return context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
    }
    
    // Validate and clean markers to remove any corrupted/invalid entries
    private fun validateMarkers(markers: List<Marker>): List<Marker> {
        return markers.filter { marker ->
            // Valid marker must have a proper type
            val validType = marker.type == "feel_bad" || marker.type == "custom"
            // Valid marker must have a proper startTime
            val validStartTime = marker.startTime in listOf("morning", "afternoon", "evening", "night", "all_day", "cell_specific")
            // Marker must have a non-empty id (if empty, it's likely corrupted data)
            val hasValidId = marker.id.isNotEmpty()
            
            validType && validStartTime && hasValidId
        }
    }
    
    // Clean entries by validating their markers
    private fun cleanEntries(entries: List<DiabetesEntry>): List<DiabetesEntry> {
        return entries.map { entry ->
            val cleanedMarkers = validateMarkers(entry.markers)
            if (cleanedMarkers.size != entry.markers.size) {
                // Some invalid markers were removed
                entry.copy(markers = cleanedMarkers)
            } else {
                entry
            }
        }
    }

    fun saveEntries(context: Context, entries: List<DiabetesEntry>) {
        // Update cache immediately
        CoroutineScope(Dispatchers.Default).launch {
            mutex.withLock {
                cachedEntries = entries
            }
        }
        
        // Save to disk in background
        CoroutineScope(Dispatchers.IO).launch {
            val json = jsonParser.encodeToString(entries)
            getPreferences(context).edit().putString(KEY_ENTRIES, json).apply()
        }
    }

    fun getEntries(context: Context): List<DiabetesEntry> {
        // Return cached entries if available
        cachedEntries?.let { return it }
        
        val prefs = getPreferences(context)
        val json = prefs.getString(KEY_ENTRIES, null)
        val result = if (json != null) {
            try {
                // Use lenient parser for backward compatibility
                val entries = jsonParser.decodeFromString<List<DiabetesEntry>>(json)
                // Clean any corrupted markers from old data
                cleanEntries(entries)
            } catch (e: Exception) {
                emptyList()
            }
        } else {
            emptyList()
        }
        
        // Cache the result
        CoroutineScope(Dispatchers.Default).launch {
            mutex.withLock {
                cachedEntries = result
            }
        }
        
        return result
    }
}

object CustomColumnManager {
    private const val PREFS_NAME = "custom_columns"
    private const val KEY_COLUMNS = "columns"
    private const val KEY_REMARKS_INITIALIZED = "remarks_initialized"
    
    // Special ID for the built-in Remarks column
    const val REMARKS_COLUMN_ID = "builtin_remarks"
    
    /**
     * Initializes the built-in Remarks column if it doesn't exist yet
     */
    fun initializeRemarksColumn(context: Context) {
        val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        val isInitialized = prefs.getBoolean(KEY_REMARKS_INITIALIZED, false)
        
        if (!isInitialized) {
            val currentColumns = getCustomColumns(context).toMutableList()
            
            // Check if Remarks column already exists
            if (currentColumns.none { it.id == REMARKS_COLUMN_ID }) {
                // Get the default Remarks title from settings or use default
                val defaultRemarksTitle = SettingsManager.loadCustomHeaderText(context, "remarks", "Remarks")
                
                val remarksColumn = CustomColumn(
                    id = REMARKS_COLUMN_ID,
                    name = defaultRemarksTitle,
                    order = 0, // Place it first
                    dataType = "text",
                    unit = "",
                    includeInStatistics = false,
                    isNumeric = false,
                    keyboardType = "text",
                    showExpandedTextArea = true // Enable expanded text area for remarks
                )
                
                // Add Remarks column and reorder others
                currentColumns.add(0, remarksColumn)
                currentColumns.forEachIndexed { index, column ->
                    currentColumns[index] = column.copy(order = index)
                }
                
                saveCustomColumns(context, currentColumns)
            }
            
            prefs.edit().putBoolean(KEY_REMARKS_INITIALIZED, true).apply()
        }
    }
    
    fun getCustomColumns(context: Context): List<CustomColumn> {
        val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        val json = prefs.getString(KEY_COLUMNS, null) ?: return emptyList()
        
        return try {
            Json.decodeFromString<List<CustomColumn>>(json).sortedBy { it.order }
        } catch (e: Exception) {
            emptyList()
        }
    }
    
    fun saveCustomColumns(context: Context, columns: List<CustomColumn>) {
        val prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        val json = Json.encodeToString(columns)
        prefs.edit().putString(KEY_COLUMNS, json).apply()
    }
    
    fun addCustomColumn(context: Context, column: CustomColumn) {
        val currentColumns = getCustomColumns(context).toMutableList()
        val newColumn = column.copy(order = currentColumns.size)
        currentColumns.add(newColumn)
        saveCustomColumns(context, currentColumns)
    }
    
    fun updateCustomColumn(context: Context, columnId: String, updatedColumn: CustomColumn) {
        val currentColumns = getCustomColumns(context).toMutableList()
        val index = currentColumns.indexOfFirst { it.id == columnId }
        if (index != -1) {
            currentColumns[index] = updatedColumn
            saveCustomColumns(context, currentColumns)
        }
    }
    
    fun deleteCustomColumn(context: Context, columnId: String) {
        val currentColumns = getCustomColumns(context).toMutableList()
        currentColumns.removeAll { it.id == columnId }
        // Reorder remaining columns
        currentColumns.forEachIndexed { index, column ->
            currentColumns[index] = column.copy(order = index)
        }
        saveCustomColumns(context, currentColumns)
    }
    
    fun reorderColumns(context: Context, columns: List<CustomColumn>) {
        val reorderedColumns = columns.mapIndexed { index, column ->
            column.copy(order = index)
        }
        saveCustomColumns(context, reorderedColumns)
    }
    
    /**
     * Analyzes the data in a custom column to determine if it's mostly numeric
     * Returns true if at least 70% of non-empty values are valid numbers
     */
    fun isColumnDataNumeric(context: Context, columnId: String): Boolean {
        val entries = DataManager.getEntries(context)
        val values = entries.mapNotNull { entry ->
            entry.customColumnData[columnId]?.takeIf { it.isNotBlank() }
        }
        
        if (values.isEmpty()) return false
        
        val numericCount = values.count { value ->
            value.replace(",", ".").toDoubleOrNull() != null
        }
        
        return numericCount.toDouble() / values.size >= 0.7
    }
    
    /**
     * Suggests whether a column should be included in statistics based on its data
     */
    fun shouldSuggestStatistics(context: Context, column: CustomColumn): Boolean {
        return when {
            column.unit.isNotEmpty() -> true // Has unit, likely numeric
            column.name.lowercase().contains(Regex("weight|kg|lb|pressure|mmhg|temp|°c|°f|bpm|heart|pulse|sugar|glucose|level")) -> true
            isColumnDataNumeric(context, column.id) -> true
            else -> false
        }
    }
}

