    // Helper functions for undo/redo
    fun saveToUndoStack(currentEntries: List<DiabetesEntry>, description: String) {
        // Create defensive copy of entries to prevent reference issues
        val entriesCopy = currentEntries.map { entry ->
            entry.copy(
                id = entry.id,
                date = entry.date,
                morningBloodSugarLevel = entry.morningBloodSugarLevel,
                afternoonBloodSugarLevel = entry.afternoonBloodSugarLevel,
                eveningBloodSugarLevel = entry.eveningBloodSugarLevel,
                nightBloodSugarLevel = entry.nightBloodSugarLevel,
                morningInsulin = entry.morningInsulin,
                afternoonInsulin = entry.afternoonInsulin,
                eveningInsulin = entry.eveningInsulin,
                remarks = entry.remarks,
                foodEntriesByColumn = entry.foodEntriesByColumn.toMap(),
                customColumnData = entry.customColumnData.toMap()
            )
        }
        undoStack = (undoStack + listOf(ActionState(entriesCopy, description))).takeLast(20) // Keep last 20 states
        redoStack = emptyList() // Clear redo stack when new action is performed
    }
    
    fun performUndo(steps: Int = 1) {
        repeat(steps) {
            if (undoStack.isNotEmpty()) {
                val previousState = undoStack.last()
                undoStack = undoStack.dropLast(1)
                
                // Create a redo state with the current entries BEFORE restoring
                val redoDescription = context.getString(R.string.redo_prefix, previousState.description)
                val currentEntriesCopy = entries.map { entry ->
                    entry.copy(
                        id = entry.id,
                        date = entry.date,
                        morningBloodSugarLevel = entry.morningBloodSugarLevel,
                        afternoonBloodSugarLevel = entry.afternoonBloodSugarLevel,
                        eveningBloodSugarLevel = entry.eveningBloodSugarLevel,
                        nightBloodSugarLevel = entry.nightBloodSugarLevel,
                        morningInsulin = entry.morningInsulin,
                        afternoonInsulin = entry.afternoonInsulin,
                        eveningInsulin = entry.eveningInsulin,
                        remarks = entry.remarks,
                        foodEntriesByColumn = entry.foodEntriesByColumn.toMap()
                    )
                }
                val currentState = ActionState(currentEntriesCopy, redoDescription)
                redoStack = listOf(currentState) + redoStack.take(19) // Keep last 20 redo states
                
                // Restore the exact previous state
                entries = previousState.entries.map { entry ->
                    entry.copy(
                        id = entry.id,
                        date = entry.date,
                        morningBloodSugarLevel = entry.morningBloodSugarLevel,
                        afternoonBloodSugarLevel = entry.afternoonBloodSugarLevel,
                        eveningBloodSugarLevel = entry.eveningBloodSugarLevel,
                        nightBloodSugarLevel = entry.nightBloodSugarLevel,
                        morningInsulin = entry.morningInsulin,
                        afternoonInsulin = entry.afternoonInsulin,
                        eveningInsulin = entry.eveningInsulin,
                        remarks = entry.remarks,
                        foodEntriesByColumn = entry.foodEntriesByColumn.toMap(),
                        customColumnData = entry.customColumnData.toMap()
                    )
                }
                
                
                hasUnsavedChanges = true
            }
        }
    }
    
    fun performRedo(steps: Int = 1) {
        repeat(steps) {
            if (redoStack.isNotEmpty()) {
                val nextState = redoStack.first()
                redoStack = redoStack.drop(1)
                
                // Create an undo state with the current entries BEFORE restoring
                val redoPrefix = context.getString(R.string.redo_prefix, "")
                val undoDescription = nextState.description.removePrefix(redoPrefix.substringBefore("%1\$s"))
                val currentEntriesCopy = entries.map { entry ->
                    entry.copy(
                        id = entry.id,
                        date = entry.date,
                        morningBloodSugarLevel = entry.morningBloodSugarLevel,
                        afternoonBloodSugarLevel = entry.afternoonBloodSugarLevel,
                        eveningBloodSugarLevel = entry.eveningBloodSugarLevel,
                        nightBloodSugarLevel = entry.nightBloodSugarLevel,
                        morningInsulin = entry.morningInsulin,
                        afternoonInsulin = entry.afternoonInsulin,
                        eveningInsulin = entry.eveningInsulin,
                        remarks = entry.remarks,
                        foodEntriesByColumn = entry.foodEntriesByColumn.toMap(),
                        customColumnData = entry.customColumnData.toMap()
                    )
                }
                val currentState = ActionState(currentEntriesCopy, undoDescription)
                undoStack = (undoStack + listOf(currentState)).takeLast(20)
                
                // Restore the exact next state
                entries = nextState.entries.map { entry ->
                    entry.copy(
                        id = entry.id,
                        date = entry.date,
                        morningBloodSugarLevel = entry.morningBloodSugarLevel,
                        afternoonBloodSugarLevel = entry.afternoonBloodSugarLevel,
                        eveningBloodSugarLevel = entry.eveningBloodSugarLevel,
                        nightBloodSugarLevel = entry.nightBloodSugarLevel,
                        morningInsulin = entry.morningInsulin,
                        afternoonInsulin = entry.afternoonInsulin,
                        eveningInsulin = entry.eveningInsulin,
                        remarks = entry.remarks,
                        foodEntriesByColumn = entry.foodEntriesByColumn.toMap(),
                        customColumnData = entry.customColumnData.toMap()
                    )
                }
                
                
                hasUnsavedChanges = true
            }
        }
    }
    
    fun generateActionDescription(oldEntries: List<DiabetesEntry>, newEntries: List<DiabetesEntry>): String {
        when {
            newEntries.size > oldEntries.size -> {
                return context.getString(R.string.action_add_new_entry)
            }
            newEntries.size < oldEntries.size -> {
                return context.getString(R.string.action_delete_entry)
            }
            else -> {
                // Find what changed
                for (i in oldEntries.indices) {
                    val oldEntry = oldEntries[i]
                    val newEntry = newEntries[i]
                    
                    when {
                        oldEntry.morningBloodSugarLevel != newEntry.morningBloodSugarLevel -> return context.getString(R.string.action_edit_morning_blood_sugar)
                        oldEntry.afternoonBloodSugarLevel != newEntry.afternoonBloodSugarLevel -> return context.getString(R.string.action_edit_afternoon_blood_sugar)
                        oldEntry.eveningBloodSugarLevel != newEntry.eveningBloodSugarLevel -> return context.getString(R.string.action_edit_evening_blood_sugar)
                        oldEntry.nightBloodSugarLevel != newEntry.nightBloodSugarLevel -> return context.getString(R.string.action_edit_night_blood_sugar)
                        oldEntry.morningInsulin != newEntry.morningInsulin -> return context.getString(R.string.action_edit_morning_insulin)
                        oldEntry.afternoonInsulin != newEntry.afternoonInsulin -> return context.getString(R.string.action_edit_afternoon_insulin)
                        oldEntry.eveningInsulin != newEntry.eveningInsulin -> return context.getString(R.string.action_edit_evening_insulin)
                        oldEntry.remarks != newEntry.remarks -> return context.getString(R.string.action_edit_remarks)
                        oldEntry.foodEntriesByColumn != newEntry.foodEntriesByColumn -> {
                            // Check for food changes
                            val oldFoodCount = oldEntry.foodEntriesByColumn.values.flatten().size
                            val newFoodCount = newEntry.foodEntriesByColumn.values.flatten().size
                            return when {
                                newFoodCount > oldFoodCount -> context.getString(R.string.action_add_food_item)
                                newFoodCount < oldFoodCount -> context.getString(R.string.action_remove_food_item)
                                else -> context.getString(R.string.action_edit_food_item)
                            }
                        }
                    }
                }
                return context.getString(R.string.action_edit_entry)
            }
        }
    }
    
    // Handle back button press - enhanced exit logic with auto-save and double-tap
    BackHandler(enabled = true) {
        if (autoSaveOnExit) {
            // Auto-save enabled: always show snackbar for double-tap confirmation (regardless of unsaved changes)
            if (backPressedOnce) {
                // Second press: save (if needed) and exit
                if (hasUnsavedChanges) {
                    DataManager.saveEntries(context, entries)
                }
                
                // Auto-backup on exit if enabled
                if (autoBackupOnExit) {
                    try {
                        // Check if backup is needed based on frequency
                        val frequency = SettingsManager.loadAutoBackupFrequency(context)
                        val lastBackupDate = SettingsManager.loadLastAutoBackupDate(context)
                        val currentDate = java.time.LocalDate.now().toString()
                        
                        val shouldBackup = when (frequency) {
                            "Every Exit" -> true // Always backup on every exit
                            "Daily" -> lastBackupDate != currentDate
                            "Weekly" -> {
                                if (lastBackupDate.isBlank()) true
                                else {
                                    val lastDate = java.time.LocalDate.parse(lastBackupDate)
                                    val daysBetween = java.time.temporal.ChronoUnit.DAYS.between(lastDate, java.time.LocalDate.now())
                                    daysBetween >= 7
                                }
                            }
                            "Monthly" -> {
                                if (lastBackupDate.isBlank()) true
                                else {
                                    val lastDate = java.time.LocalDate.parse(lastBackupDate)
                                    val daysBetween = java.time.temporal.ChronoUnit.DAYS.between(lastDate, java.time.LocalDate.now())
                                    daysBetween >= 30
                                }
                            }
                            else -> true // Default: always backup
                        }
                        
                        if (shouldBackup) {
                            val backupData = BackupManager.createBackup(context, BackupType.ALL)
                            val timestamp = java.time.LocalDateTime.now().format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd_HH-mm-ss"))
                            val backupFileName = "auto-backup_DiabetesTracker_$timestamp.json"
                            
                            // Get backup path and max count
                            val backupPath = SettingsManager.loadAutoBackupPath(context)
                            val maxBackupCount = SettingsManager.loadAutoBackupMaxCount(context)
                            
                            // Create backup directory
                            val backupDir = java.io.File(backupPath)
                            if (!backupDir.exists()) {
                                backupDir.mkdirs()
                            }
                            
                            // Get existing auto-backup files and sort by date (oldest first)
                            val existingBackups = backupDir.listFiles { _, name -> 
                                name.startsWith("auto-backup_DiabetesTracker_") && name.endsWith(".json")
                            }?.sortedBy { it.lastModified() } ?: emptyList()
                            
                            // Delete oldest backup if we've reached the limit (unless unlimited)
                            if (maxBackupCount > 0 && existingBackups.size >= maxBackupCount) {
                                val toDelete = existingBackups.take(existingBackups.size - maxBackupCount + 1)
                                toDelete.forEach { it.delete() }
                            }
                            // If maxBackupCount is 0 (unlimited), don't delete any backups
                            
                            // Save new backup
                            val backupFile = java.io.File(backupDir, backupFileName)
                            val backupUri = android.net.Uri.fromFile(backupFile)
                            BackupManager.exportBackupToFile(context, backupData, backupUri)
                            
                            // Update last backup date
                            SettingsManager.saveLastAutoBackupDate(context, currentDate)
                        }
                    } catch (e: Exception) {
                        // Silent fail - don't interrupt app exit (stealth mode)
                    }
                }
                
                if (hasUnsavedChanges) {
                    val tempExisting = SettingsManager.loadSettings(context); SettingsManager.saveSettings(context, tempExisting.copy(
                        fontColor = fontColor,
                        backgroundColor = backgroundColor,
                        gridColor = gridColor,
                        insulinColumnColor = insulinColumnColor,
                        isDarkMode = isDarkMode,
                        language = selectedLanguage,
                        colorsModifiedByUser = true,
                        scale = scale,
                        widthScale = widthScale,
                        zoomPercentage = zoomPercentage
                    ))
                    
                    // Mark entries with data as secured
                    val entriesWithData = entries.filter { entry ->
                        entry.date.isNotBlank() && (
                            entry.morningBloodSugarLevel.isNotBlank() ||
                            entry.afternoonBloodSugarLevel.isNotBlank() ||
                            entry.eveningBloodSugarLevel.isNotBlank() ||
                            entry.nightBloodSugarLevel.isNotBlank() ||
                            entry.morningInsulin.isNotBlank() ||
                            entry.afternoonInsulin.isNotBlank() ||
                            entry.eveningInsulin.isNotBlank() ||
                            entry.remarks.isNotBlank() ||
                            entry.foodEntriesByColumn.values.any { it.isNotEmpty() }
                        )
                    }
                    securedEntryIds = entriesWithData.map { it.id }.toSet()
                    SettingsManager.saveSecuredEntryIds(context, securedEntryIds)
                    
                    hasUnsavedChanges = false
                    confirmedEditingSessions = emptySet()
                }
                (context as? Activity)?.finish()
            } else {
                // First press: show snackbar (regardless of unsaved changes)
                backPressedOnce = true
                showExitSnackbar = true
                
                // Reset after 2 seconds
                kotlinx.coroutines.CoroutineScope(kotlinx.coroutines.Dispatchers.Main).launch {
                    kotlinx.coroutines.delay(2000)
                    backPressedOnce = false
                    showExitSnackbar = false
                }
            }
        } else {
            // Auto-save disabled: check for unsaved changes
            if (hasUnsavedChanges) {
                // Show exit confirmation dialog (save or discard changes)
                showExitConfirmDialog = true
            } else {
                // No unsaved changes: show snackbar for double-tap confirmation
                if (backPressedOnce) {
                    // Second press: exit
                    (context as? Activity)?.finish()
                } else {
                    // First press: show snackbar
                    backPressedOnce = true
                    showExitSnackbar = true
                    
                    // Reset after 2 seconds
                    kotlinx.coroutines.CoroutineScope(kotlinx.coroutines.Dispatchers.Main).launch {
                        kotlinx.coroutines.delay(2000)
                        backPressedOnce = false
                        showExitSnackbar = false
                    }
                }
            }
        }
    }
    
