        // Also auto-lock any entries with data at startup
        val autoLockableIds = EntryLockingHelper.getAutoLockableEntryIds(loadedEntries)
        securedEntryIds = loadedSecuredIds + autoLockableIds
        
        // Save merged secured IDs
        if (securedEntryIds.isNotEmpty()) {
            SettingsManager.saveSecuredEntryIds(context, securedEntryIds)
        }
        
        println("DEBUG STARTUP: Loaded ${loadedEntries.size} entries, ${securedEntryIds.size} secured IDs")
    }
    
    // Automatic locking effect - locks filled cells when entries change
    LaunchedEffect(entries) {
        if (entries.isNotEmpty()) {
            val autoLockableIds = EntryLockingHelper.getAutoLockableEntryIds(entries)
            // Merge persisted secured entries with auto-lockable entries instead of replacing
            val mergedSecuredIds = securedEntryIds + autoLockableIds
            if (mergedSecuredIds != securedEntryIds) {
                securedEntryIds = mergedSecuredIds
                SettingsManager.saveSecuredEntryIds(context, securedEntryIds)
                println("DEBUG: Auto-locked ${autoLockableIds.size} entries, total secured: ${securedEntryIds.size}")
            }
        }
    }
    
