    fun saveUserView() {
        val currentSettings = SettingsManager.loadSettings(context)
        val newSettings = currentSettings.copy(
            savedUserScale = scale,
            savedUserWidthScale = widthScale
        )
        SettingsManager.saveSettings(context, newSettings)
        Toast.makeText(context, context.getString(R.string.current_view_saved), Toast.LENGTH_SHORT).show()
    }

    fun loadUserView() {
        val settings = SettingsManager.loadSettings(context)
        settings.savedUserScale?.let { savedScale ->
            settings.savedUserWidthScale?.let { savedWidthScale ->
                scale = savedScale
                widthScale = savedWidthScale
                zoomPercentage = (savedScale * 100).toInt()

                val updatedSettings = settings.copy(
                    scale = savedScale,
                    widthScale = savedWidthScale,
                    zoomPercentage = (savedScale * 100).toInt()
                )
                SettingsManager.saveSettings(context, updatedSettings)
                Toast.makeText(context, context.getString(R.string.saved_view_loaded), Toast.LENGTH_SHORT).show()
                return
            }
        }
        Toast.makeText(context, context.getString(R.string.no_saved_view_found), Toast.LENGTH_SHORT).show()
    }

    fun saveCurrentViewAsPreset(name: String) {
        val newPreset = ViewPreset(name = name, scale = scale, widthScale = widthScale)
        val updated = viewPresets + newPreset
        SettingsManager.saveViewPresets(context, updated)
        viewPresets = updated
        Toast.makeText(context, context.getString(R.string.preset_saved), Toast.LENGTH_SHORT).show()
    }

    fun loadPreset(preset: ViewPreset) {
        scale = preset.scale
        widthScale = preset.widthScale
        zoomPercentage = (preset.scale * 100).toInt()
        val existing = SettingsManager.loadSettings(context)
        SettingsManager.saveSettings(context, existing.copy(
            scale = scale,
            widthScale = widthScale,
            zoomPercentage = zoomPercentage
        ))
        Toast.makeText(context, context.getString(R.string.preset_loaded), Toast.LENGTH_SHORT).show()
    }

    fun deletePreset(preset: ViewPreset) {
        val updated = viewPresets.filter { it.id != preset.id }
        SettingsManager.saveViewPresets(context, updated)
        viewPresets = updated
        Toast.makeText(context, context.getString(R.string.preset_deleted), Toast.LENGTH_SHORT).show()
    }

    fun updateAppUiScale(newScale: Float) {
        val clampedScale = newScale.coerceIn(0.7f, 1.3f)
        if (clampedScale == appUiScale) return

        appUiScale = clampedScale
        val existing = SettingsManager.loadSettings(context)
        SettingsManager.saveSettings(context, existing.copy(appUiScale = clampedScale))
    }


