    LaunchedEffect(isDarkMode) {
        val settings = SettingsManager.loadSettings(context)
        val (newFontColor, newBackgroundColor, newGridColor, newInsulinColumnColor) = SettingsManager.getDefaultColors(isDarkMode)
        
        // Update colors based on individual customization flags
        if (!settings.fontColorCustomized) {
            fontColor = newFontColor
        }
        if (!settings.backgroundColorCustomized) {
            backgroundColor = newBackgroundColor
        }
        if (!settings.gridColorCustomized) {
            gridColor = newGridColor
        }
        if (!settings.insulinColumnColorCustomized) {
            insulinColumnColor = newInsulinColumnColor
        }
        
        // Save updated settings with new theme defaults for non-customized colors
        SettingsManager.saveSettings(context, settings.copy(
            fontColor = if (settings.fontColorCustomized) settings.fontColor else newFontColor,
            backgroundColor = if (settings.backgroundColorCustomized) settings.backgroundColor else newBackgroundColor,
            gridColor = if (settings.gridColorCustomized) settings.gridColor else newGridColor,
            insulinColumnColor = if (settings.insulinColumnColorCustomized) settings.insulinColumnColor else newInsulinColumnColor,
            isDarkMode = isDarkMode
        ))
    }

