                usePaginationMode = usePaginationMode,
                onPaginationModeChanged = { newValue ->
                    usePaginationMode = newValue
                },
                useButtonPaging = useButtonPaging,
                onButtonPagingChanged = { newValue ->
                    useButtonPaging = newValue
                },
                onReloadEntries = {
                    entries = DataManager.getEntries(context)
                }
            )
        }
    }

    LaunchedEffect(Unit) {
        SettingsManager.saveSettings(context, SettingsManager.loadSettings(context))
    }

    // Auto-save orientation-specific zoom settings when they change
    LaunchedEffect(scale, widthScale, heightScale, isLandscape) {
        val existing = SettingsManager.loadSettings(context)
        val updated = if (isLandscape) {
            existing.copy(
                landscapeScale = scale,
                landscapeWidthScale = widthScale,
                landscapeHeightScale = heightScale,
                scale = scale,
                widthScale = widthScale,
                heightScale = heightScale,
                zoomPercentage = (scale * 100).toInt()
            )
        } else {
            existing.copy(
                portraitScale = scale,
                portraitWidthScale = widthScale,
                portraitHeightScale = heightScale,
                scale = scale,
                widthScale = widthScale,
                heightScale = heightScale,
                zoomPercentage = (scale * 100).toInt()
            )
        }
        SettingsManager.saveSettings(context, updated)
    }

    // Auto-restore orientation-specific zoom settings when orientation changes
    LaunchedEffect(isLandscape) {
        val currentSettings = SettingsManager.loadSettings(context)
        if (isLandscape) {
            scale = currentSettings.landscapeScale
            widthScale = currentSettings.landscapeWidthScale
            heightScale = currentSettings.landscapeHeightScale
        } else {
            scale = currentSettings.portraitScale
            widthScale = currentSettings.portraitWidthScale
            heightScale = currentSettings.portraitHeightScale
        }
        zoomPercentage = (scale * 100).toInt()
    }

    LaunchedEffect(isDarkMode, fontColor, backgroundColor, gridColor, insulinColumnColor, selectedLanguage, scale, widthScale, zoomPercentage) {
        val existing = SettingsManager.loadSettings(context)
        val merged = existing.copy(
            fontColor = fontColor,
            backgroundColor = backgroundColor,
            gridColor = gridColor,
            insulinColumnColor = insulinColumnColor,
            isDarkMode = isDarkMode,
            language = selectedLanguage,
            colorsModifiedByUser = true,
            fontColorCustomized = existing.fontColorCustomized,
            backgroundColorCustomized = existing.backgroundColorCustomized,
            gridColorCustomized = existing.gridColorCustomized,
            insulinColumnColorCustomized = existing.insulinColumnColorCustomized,
            scale = scale,
            widthScale = widthScale,
            zoomPercentage = zoomPercentage
        )
        SettingsManager.saveSettings(context, merged)
    }
    
    // Auto-run pattern detection once per day
    LaunchedEffect(entries.size) {
        val previousPatterns = PatternStorageManager.getActivePatterns(context)
        
        if (PatternStorageManager.shouldReanalyze(context) && entries.isNotEmpty()) {
            detectedPatterns = PatternDetectionEngine.detectPatterns(
                entries = entries,
                customMarkers = customMarkers,
                daysToAnalyze = 30,
                context = context
            )
            PatternStorageManager.savePatterns(context, detectedPatterns)
            
            // Check for new high-confidence patterns
            val previousPatternIds = previousPatterns.map { it.id }.toSet()
            val newPatterns = detectedPatterns.filter { 
                !previousPatternIds.contains(it.id) && it.confidenceScore >= 0.7f 
            }
            
            if (newPatterns.isNotEmpty()) {
                PatternNotificationHelper.showPatternSummaryNotification(
                    context = context,
                    patterns = newPatterns,
                    periodType = "New"
                )
            }
            
            // Check for weekly/monthly summaries
            if (PatternNotificationHelper.shouldShowWeeklySummary(context)) {
                PatternNotificationHelper.generateWeeklySummary(context, entries, customMarkers)
                PatternNotificationHelper.markWeeklySummaryShown(context)
            }
            
            if (PatternNotificationHelper.shouldShowMonthlySummary(context)) {
                PatternNotificationHelper.generateMonthlySummary(context, entries, customMarkers)
                PatternNotificationHelper.markMonthlySummaryShown(context)
            }
        } else {
            // Load existing patterns
            detectedPatterns = PatternStorageManager.getActivePatterns(context)
        }
    }

