                                                onClick = {
                                                    val newScale = (scale - 0.1f).coerceIn(0.5f, 3f)
                                                    if (newScale != scale) {
                                                        if (proportionalZoom) {
                                                            // Scale both width and height proportionally to maintain aspect ratio
                                                            widthScale = (widthScale * (newScale / scale)).coerceIn(1f, 3f)
                                                            heightScale = (heightScale * (newScale / scale)).coerceIn(0.5f, 3f)
                                                        }
                                                        scale = newScale
                                                        zoomPercentage = (scale * 100).toInt()
                                                    }
                                                }
                                            ) {
                                                Icon(Icons.Filled.Remove, stringResource(R.string.zoom_out))
                                            }
                                            IconButton(
                                                onClick = {
                                                    val newScale = (scale + 0.1f).coerceIn(0.5f, 3f)
                                                    if (newScale != scale) {
                                                        if (proportionalZoom) {
                                                            // Scale both width and height proportionally to maintain aspect ratio
                                                            widthScale = (widthScale * (newScale / scale)).coerceIn(1f, 3f)
                                                            heightScale = (heightScale * (newScale / scale)).coerceIn(0.5f, 3f)
                                                        }
                                                        scale = newScale
                                                        zoomPercentage = (scale * 100).toInt()
                                                    }
                                                }
                                            ) {
                                                Icon(Icons.Filled.Add, stringResource(R.string.zoom_in))
                                            }
                                        }
                                        Spacer(modifier = Modifier.height(8.dp))
                                        Text(
                                            text = context.getString(R.string.width_format, (widthScale * 100).toInt()),
                                            modifier = Modifier.align(Alignment.CenterHorizontally).clickable {
                                                widthScale = 2.2f
                                            }
                                        )
                                        Row(
                                            modifier = Modifier.align(Alignment.CenterHorizontally),
                                            horizontalArrangement = Arrangement.spacedBy(4.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            IconButton(
                                                onClick = {
                                                    widthScale = (widthScale - 0.1f).coerceIn(1f, 3f)
                                                }
                                            ) {
                                                Icon(Icons.Filled.Remove, stringResource(R.string.decrease_width))
                                            }
                                            IconButton(
                                                onClick = {
                                                    widthScale = (widthScale + 0.1f).coerceIn(1f, 3f)
                                                }
                                            ) {
                                                Icon(Icons.Filled.Add, stringResource(R.string.increase_width))
                                            }
                                        }
                                        
                                        Spacer(modifier = Modifier.height(8.dp))
                                        Text(
                                            text = "Height: ${(heightScale * 100).toInt()}%",
                                            modifier = Modifier.align(Alignment.CenterHorizontally).clickable {
                                                heightScale = 1f
                                            }
                                        )
                                        Row(
                                            modifier = Modifier.align(Alignment.CenterHorizontally),
                                            horizontalArrangement = Arrangement.spacedBy(4.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            IconButton(
                                                onClick = {
                                                    heightScale = (heightScale - 0.1f).coerceIn(0.5f, 3f)
                                                    println("DEBUG: Height decreased to $heightScale")
                                                }
                                            ) {
                                                Icon(Icons.Filled.Remove, "Decrease height")
                                            }
                                            IconButton(
                                                onClick = {
                                                    heightScale = (heightScale + 0.1f).coerceIn(0.5f, 3f)
                                                    println("DEBUG: Height increased to $heightScale")
                                                }
                                            ) {
                                                Icon(Icons.Filled.Add, "Increase height")
                                            }
                                        }
                                    }
                                }
                            }
                            // Bell icon for confirmations
                            Box(contentAlignment = Alignment.Center) {
                                val bellCount = pendingConfirmations.size + activeAlerts.size
                                val hasPending = bellCount > 0
                                // Pulsing glow ring behind bell when pending
                                if (hasPending) {
                                    val pulseTransition = rememberInfiniteTransition(label = "bellPulse")
                                    val pulseAlpha by pulseTransition.animateFloat(
                                        initialValue = 0.15f,
                                        targetValue = 0.45f,
                                        animationSpec = infiniteRepeatable(
                                            animation = tween(1200, easing = FastOutSlowInEasing),
                                            repeatMode = RepeatMode.Reverse
                                        ),
                                        label = "pulseAlpha"
                                    )
                                    val pulseScale by pulseTransition.animateFloat(
                                        initialValue = 0.85f,
                                        targetValue = 1.1f,
                                        animationSpec = infiniteRepeatable(
                                            animation = tween(1200, easing = FastOutSlowInEasing),
                                            repeatMode = RepeatMode.Reverse
                                        ),
                                        label = "pulseScale"
                                    )
                                    Box(
                                        modifier = Modifier
                                            .size(36.dp)
                                            .graphicsLayer { scaleX = pulseScale; scaleY = pulseScale }
                                            .background(
                                                color = MaterialTheme.colorScheme.primary.copy(alpha = pulseAlpha),
                                                shape = CircleShape
                                            )
                                    )
                                }
                                IconButton(onClick = {
                                    val willOpenBellPopup = !showBellPopup
                                    showBellPopup = willOpenBellPopup
                                    if (willOpenBellPopup) {
                                        bellPopupPreferredSection = null
                                        bellPopupFocusReminderId = null
                                    }
                                }) {
                                    Icon(
                                        if (hasPending) Icons.Default.Notifications else Icons.Default.Notifications,
                                        contentDescription = "Confirmations",
                                        tint = if (hasPending) MaterialTheme.colorScheme.primary
                                               else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                                        modifier = Modifier.size(22.dp)
                                    )
                                }
                                if (hasPending) {
                                    val badgeBounce = rememberInfiniteTransition(label = "badgeBounce")
                                    val badgeOffset by badgeBounce.animateFloat(
                                        initialValue = 0f,
                                        targetValue = -2f,
                                        animationSpec = infiniteRepeatable(
                                            animation = tween(600, easing = FastOutSlowInEasing),
                                            repeatMode = RepeatMode.Reverse
                                        ),
                                        label = "badgeY"
                                    )
                                    Box(
                                        modifier = Modifier
                                            .align(Alignment.TopEnd)
                                            .offset(x = (-2).dp, y = (4 + badgeOffset).dp)
                                            .size(20.dp)
                                            .background(
                                                color = MaterialTheme.colorScheme.error,
                                                shape = CircleShape
                                            )
                                            .border(
                                                width = 1.5.dp,
                                                color = MaterialTheme.colorScheme.surface,
                                                shape = CircleShape
                                            ),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text(
                                            text = "$bellCount",
                                            fontSize = 10.sp,
                                            fontWeight = FontWeight.ExtraBold,
                                            color = MaterialTheme.colorScheme.onError,
                                            lineHeight = 10.sp
                                        )
                                    }
                                }
                                if (showBellPopup) {
                                    androidx.compose.ui.window.Popup(
                                        alignment = Alignment.TopEnd,
                                        onDismissRequest = {
                                            showBellPopup = false
                                            bellPopupPreferredSection = null
                                            bellPopupFocusReminderId = null
                                        },
                                        offset = androidx.compose.ui.unit.IntOffset(0, 140)
                                    ) {
                                        BellPopupContent(
                                            pendingConfirmations = pendingConfirmations,
                                            history = confirmationHistory,
                                            alerts = activeAlerts,
                                            selectedLanguage = selectedLanguage,
                                            preferredSection = bellPopupPreferredSection,
                                            focusReminderId = bellPopupFocusReminderId,
                                            onRespond = { id, status, comment ->
                                                ReminderConfirmationStorage.respondToConfirmation(context, id, status, comment)
                                                // Check streak-based alert rules
                                                val respondedConf = ReminderConfirmationStorage.loadConfirmations(context).find { it.id == id }
                                                if (respondedConf != null) {
                                                    val allReminders = CustomReminderStorage.loadReminders(context)
                                                    val alertReminder = allReminders.find { it.id == respondedConf.reminderId }
                                                    if (alertReminder != null && alertReminder.requiresConfirmation) {
                                                        ReminderConfirmationStorage.checkAndTriggerAlerts(context, respondedConf.reminderId, alertReminder.confirmationAlertSettings)
                                                    }
                                                }
                                                pendingConfirmations = ReminderConfirmationStorage.getPendingConfirmations(context)
                                                confirmationHistory = ReminderConfirmationStorage.getHistory(context)
                                                activeAlerts = ReminderConfirmationStorage.getActiveAlerts(context)
                                            },
                                            onDismissAlert = { alertId ->
                                                ReminderConfirmationStorage.dismissAlert(context, alertId)
                                                activeAlerts = ReminderConfirmationStorage.getActiveAlerts(context)
                                            },
                                            onOpenSmartAlertsSettings = { reminderId ->
                                                showBellPopup = false
                                                bellPopupPreferredSection = null
                                                bellPopupFocusReminderId = null
                                                notificationSettingsSmartAlertsReminderId = reminderId
                                                showNotificationSettingsDialog = true
                                            },
                                            onHistoryItemClick = { reminderId ->
                                                showBellPopup = false
                                                bellPopupPreferredSection = null
                                                bellPopupFocusReminderId = null
                                                historyDialogReminderId = reminderId
                                            },
                                            onDismiss = {
                                                showBellPopup = false
                                                bellPopupPreferredSection = null
                                                bellPopupFocusReminderId = null
                                            }
                                        )
                                    }
                                }
                            }
                            // Reminder History Dialog
                            if (historyDialogReminderId != null) {
                                ReminderHistoryDialog(
                                    reminderId = historyDialogReminderId!!,
                                    history = confirmationHistory,
                                    selectedLanguage = selectedLanguage,
                                    onUpdateConfirmation = { confId, newStatus, newComment ->
                                        ReminderConfirmationStorage.updateConfirmation(context, confId, newStatus, newComment)
                                        confirmationHistory = ReminderConfirmationStorage.getHistory(context)
                                    },
                                    onNavigateToNotifications = { reminderId ->
                                        historyDialogReminderId = null
                                        showNotificationSettingsDialog = false
                                        bellPopupFocusReminderId = reminderId
                                        bellPopupPreferredSection = when {
                                            activeAlerts.any { it.reminderId == reminderId } -> "alerts"
                                            pendingConfirmations.any { it.reminderId == reminderId } -> "pending"
                                            else -> null
                                        }
                                        showBellPopup = true
                                        scope.launch { drawerState.close() }
                                    },
                                    onDismiss = { historyDialogReminderId = null }
                                )
                            }
                            IconButton(onClick = { showChart = true }) {
                                Icon(
                                    Icons.Default.Timeline, 
                                    contentDescription = stringResource(R.string.show_chart),
                                    tint = MaterialTheme.colorScheme.onSurface
                                )
                            }
                        }
                    }
                }
                }
            ) { paddingValues ->
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(paddingValues)
                ) {
                    val configuration = LocalConfiguration.current
                    val baseWidth = configuration.screenWidthDp.dp
                    val scrollState = rememberScrollState()
                    
                    // Calculate actual table width (width button affects base width)
                    val actualTableWidth = baseWidth
                    val screenWidth = configuration.screenWidthDp.dp
                    // Calculate minimum zoom level for future use
                    // val minZoomLevel = (screenWidth / actualTableWidth).coerceAtMost(1f)
                    
                    // State for tracking total pages (accessible from gesture handler)
                    var totalPagesForGesture by remember { mutableStateOf(1) }
                    
                    // State for tracking current page date range (accessible from scrollbar)
                    var currentPageDateRange by remember { mutableStateOf("") }

                    // Table date sort direction: false = oldest to newest, true = newest to oldest
                    var isDateSortDescending by remember { mutableStateOf(false) }
                    
                    // State for scrollbar visibility (only in pagination mode)
                    var showScrollbar by remember { mutableStateOf(true) }
                    val scrollbarAlpha by animateFloatAsState(
                        targetValue = if (showScrollbar && usePaginationMode) 1f else 0f,
                        animationSpec = tween(durationMillis = 300)
                    )
                    
                    Box(
                        modifier = Modifier
                            .fillMaxSize()
                            .background(backgroundColor)
                    ) {
                        Column(modifier = Modifier.fillMaxSize()) {
                            OccurrenceBackNavigationBanner(
                                isVisible = isViewingOccurrence,
                                selectedLanguage = selectedLanguage,
                                onRestore = {
                                    previousFilterState?.let { prevFilter ->
                                        selectedDateFilter = prevFilter
                                        customStartDate = previousCustomStartDate
                                        customEndDate = previousCustomEndDate
                                        specificDate = previousSpecificDate
                                        flexibleNumber = previousFlexibleNumber
                                        flexibleUnit = previousFlexibleUnit
                                        currentPage = previousPage
                                        isViewingOccurrence = false

                                        when (navigationSource) {
                                            "food_warning" -> {
                                                showPatternDetailsPopup = true
                                                showFoodWarning = true
                                            }
                                            "analysis_screen" -> {
                                                showAnalysisScreen = true
                                            }
                                            "chart_dialog" -> {
                                                showChart = true
                                            }
                                        }
                                        navigationSource = null
                                    }
                                }
                            )

                            val tableGestureModifier = rememberTableGestureModifier(
                                totalPagesForGesture = totalPagesForGesture,
                                usePaginationMode = usePaginationMode,
                                useButtonPaging = useButtonPaging,
                                currentPage = currentPage,
                                onCurrentPageChange = { currentPage = it },
                                onScrollbarVisibilityChange = { showScrollbar = it }
                            )
                            
                            Box(
                                modifier = Modifier
                                    .width((actualTableWidth * widthScale * scale).coerceAtLeast(screenWidth))
                                    .fillMaxHeight()
                                    .horizontalScroll(scrollState)
                                    .then(tableGestureModifier)
                        ) {
                            val labels = tableLabelsForLanguage(selectedLanguage)
                        Column(
                            modifier = Modifier
                                .width(actualTableWidth * widthScale * scale)
                                .fillMaxHeight()
                        ) {
                            TableHeader(
                                labels = labels,
                                fontColor = fontColor,
                                gridColor = gridColor,
                                insulinColumnColor = insulinColumnColor,
                                scale = scale,
                                heightScale = heightScale,
                                useSymbolsInCharts = useSymbolsInCharts,
                                useEmojiSymbols = useEmojiSymbols,
                                customColumns = customColumns,
                                isDateSortDescending = isDateSortDescending,
                                onDateSortToggle = {
                                    isDateSortDescending = !isDateSortDescending
                                    currentPage = 0
                                }
                            )
                            
                            // Use a stable key for filtered entries and remember the filtered entries
                            // Note: entries reference changes when any entry is updated, triggering recomputation
                            val entriesWithIndex = remember(entries, selectedDateFilter, customStartDate, customEndDate, securedEntryIds, showEmptyDatesInFilter, specificDate, flexibleNumber, flexibleUnit, isDateSortDescending) {
                                // PROPER DATE FILTERING: Parse DD.MM.YYYY format and use real date comparison
                                val filteredEntriesWithOriginalIndex = if (selectedDateFilter != DateFilter.ALL) {
                                    // Use DateFilterHelper for consistent filtering logic
                                    val filteredEntries = DateFilterHelper.filterEntriesByDate(
                                        entries = entries,
                                        dateFilter = selectedDateFilter,
                                        customStartDate = customStartDate,
                                        customEndDate = customEndDate,
                                        specificDate = specificDate,
                                        flexibleNumber = flexibleNumber,
                                        flexibleUnit = flexibleUnit
                                    )
                                    val filteredEntryIds = filteredEntries.asSequence().map { it.id }.toHashSet()
                                    
                                    // Filter entries but keep track of original indices and handle empty dates
                                    entries.mapIndexedNotNull { originalIndex, entry ->
                                        if (entry.date.isBlank()) {
                                            return@mapIndexedNotNull if (showEmptyDatesInFilter) originalIndex to entry else null
                                        }
                                        
                                        // Check if this entry is in the filtered results
                                        val isIncluded = filteredEntryIds.contains(entry.id)
                                        
                                        if (isIncluded) {
                                            originalIndex to entry
                                        } else {
                                            null
                                        }
                                    }
                                } else {
                                    entries.mapIndexed { index, entry -> index to entry } // Show all with original indices
                                }
                                
                                // Sort by parsed date so pagination is chronologically continuous.
                                // Keep originalIndex so edits/deletes still target the correct underlying entry.
                                val formatter = DateTimeFormatter.ofPattern("dd.MM.yyyy")
                                val sortable = filteredEntriesWithOriginalIndex.map { (originalIndex, entry) ->
                                    val parsedDate = entry.date
                                        .takeIf { it.isNotBlank() }
                                        ?.let {
                                            runCatching { LocalDate.parse(it, formatter) }.getOrNull()
                                        }
                                    Triple(originalIndex, entry, parsedDate)
                                }
                                
                                val sorted = if (isDateSortDescending) {
                                    sortable.sortedWith(
                                        compareByDescending<Triple<Int, DiabetesEntry, LocalDate?>> { it.third != null }
                                            .thenByDescending { it.third }
                                            .thenBy { it.first }
                                    )
                                } else {
                                    sortable.sortedWith(
                                        compareByDescending<Triple<Int, DiabetesEntry, LocalDate?>> { it.third != null }
                                            .thenBy { it.third }
                                            .thenBy { it.first }
                                    )
                                }

                                // Return entries with their original indices preserved
                                sorted.map { (originalIndex, entry, _) -> originalIndex to entry }
                            }
                            
                            // Conditional rendering based on pagination mode
                            if (usePaginationMode) {
                                // PAGINATION MODE: Swipe-based navigation with full-screen table
                                var rowsViewportHeightPx by remember { mutableStateOf<Int?>(null) }
                                var measuredRowHeightPx by remember { mutableStateOf<Int?>(null) }
                                val density = LocalDensity.current
                                val paginationControlsReservedHeightDp = if (useButtonPaging) 64.dp else 0.dp
                                val paginationControlsReservedHeightPx = with(density) {
                                    paginationControlsReservedHeightDp.roundToPx()
                                }
                                
                                // Calculate dynamic entries per page based on screen height and row height
                                val screenHeightDp = configuration.screenHeightDp.dp
                                val topPadding = paddingValues.calculateTopPadding()
                                val bottomPadding = if (useButtonPaging) 80.dp else 20.dp // Space for buttons or padding
                                val headerHeight = 50.dp // Approximate header height
                                val availableHeightDp = screenHeightDp - topPadding - bottomPadding - headerHeight
                                
                                val baseRowHeightDp = 50.dp // Base row content height
                                // Scale all components proportionally with heightScale
                                val rowPaddingDp = 4.dp * heightScale // TableRow Card has 2dp vertical padding (top + bottom)
                                val spacingBufferDp = 1.5.dp * heightScale // Minimal buffer for layout spacing
                                val actualRowHeightDp = (baseRowHeightDp * heightScale) + rowPaddingDp + spacingBufferDp
                                // Round down to only show rows that fully fit on screen (e.g., 18.45 rows -> 18 rows)
                                // This prevents the last row from being compressed/cut off
                                val exactFit = availableHeightDp / actualRowHeightDp
                                val (calculatedEntriesPerPage, usedMeasuredHeight) = run {
                                    val viewportPx = rowsViewportHeightPx
                                    val rowPx = measuredRowHeightPx
                                    if (viewportPx != null && rowPx != null && rowPx > 0) {
                                        val effectiveViewportPx = if (useButtonPaging) {
                                            (viewportPx - paginationControlsReservedHeightPx).coerceAtLeast(rowPx)
                                        } else {
                                            viewportPx
                                        }
                                        maxOf(1, effectiveViewportPx / rowPx) to true
                                    } else {
                                        maxOf(1, kotlin.math.floor(exactFit).toInt()) to false
                                    }
                                }
                                
                                android.util.Log.d(
                                    "PAGINATION_CALC",
                                    "heightScale=$heightScale, availableHeight=${availableHeightDp.value}dp, actualRowHeight=${actualRowHeightDp.value}dp, exactFit=$exactFit, viewportPx=${rowsViewportHeightPx ?: -1}, reservedPx=$paginationControlsReservedHeightPx, rowPx=${measuredRowHeightPx ?: -1}, usedMeasured=$usedMeasuredHeight, calculatedEntries=$calculatedEntriesPerPage"
                                )
                                
                                // Remember entriesPerPage to track changes
                                var entriesPerPage by remember { mutableStateOf(calculatedEntriesPerPage) }
                                var previousEntriesPerPage by remember { mutableStateOf(calculatedEntriesPerPage) }
                                
                                // Adjust currentPage when entriesPerPage changes due to zoom
                                LaunchedEffect(heightScale, calculatedEntriesPerPage, entriesWithIndex.size) {
                                    if (calculatedEntriesPerPage != entriesPerPage) {
                                        // Calculate the first visible entry index on current page using OLD entriesPerPage
                                        val firstVisibleIndex = currentPage * entriesPerPage
                                        
                                        android.util.Log.d("PAGINATION_EFFECT", "EntriesPerPage changed: old=$entriesPerPage, new=$calculatedEntriesPerPage, currentPage=$currentPage, firstVisibleIndex=$firstVisibleIndex")
                                        
                                        // Update entriesPerPage
                                        previousEntriesPerPage = entriesPerPage
                                        entriesPerPage = calculatedEntriesPerPage
                                        
                                        // Adjust to new page number that shows the same first entry using NEW entriesPerPage
                                        // Use floor division to ensure we show the page containing firstVisibleIndex
                                        if (entriesWithIndex.isNotEmpty()) {
                                            val newPage = (firstVisibleIndex / calculatedEntriesPerPage).coerceIn(0, maxOf(0, ((entriesWithIndex.size + calculatedEntriesPerPage - 1) / calculatedEntriesPerPage) - 1))
                                            val newStartIndex = newPage * calculatedEntriesPerPage
                                            val newEndIndex = minOf(newStartIndex + calculatedEntriesPerPage, entriesWithIndex.size)
                                            
                                            android.util.Log.d("PAGINATION_EFFECT", "Adjusting page: newPage=$newPage, newStartIndex=$newStartIndex, newEndIndex=$newEndIndex, totalEntries=${entriesWithIndex.size}")
                                            
                                            // Validate that we're showing sequential entries
                                            if (newStartIndex < entriesWithIndex.size) {
                                                val firstEntry = entriesWithIndex[newStartIndex].second.date
                                                val lastEntry = if (newEndIndex > 0 && newEndIndex <= entriesWithIndex.size) {
                                                    entriesWithIndex[newEndIndex - 1].second.date
                                                } else ""
                                                android.util.Log.d("PAGINATION_EFFECT", "New page will show: $firstEntry to $lastEntry")
                                            }
                                            
                                            currentPage = newPage
                                        }
                                    } else if (currentPage * entriesPerPage >= entriesWithIndex.size && entriesWithIndex.isNotEmpty()) {
                                        // Reset to last valid page if current page is out of bounds
                                        val lastValidPage = maxOf(0, ((entriesWithIndex.size + entriesPerPage - 1) / entriesPerPage) - 1)
                                        android.util.Log.d("PAGINATION_EFFECT", "Page out of bounds: currentPage=$currentPage, resetting to=$lastValidPage")
                                        currentPage = lastValidPage
                                    }
                                }
                                
                                // Calculate pagination
                                val totalPages = if (entriesWithIndex.isEmpty()) 1 else ((entriesWithIndex.size + entriesPerPage - 1) / entriesPerPage)
                                val startIndex = currentPage * entriesPerPage
                                val endIndex = minOf(startIndex + entriesPerPage, entriesWithIndex.size)
                                val currentPageEntries = if (entriesWithIndex.isNotEmpty()) {
                                    entriesWithIndex.subList(startIndex, endIndex)
                                } else {
                                    emptyList()
                                }
                                
                                // Validate entry continuity
                                android.util.Log.d("PAGINATION_DISPLAY", "Page ${currentPage + 1}/$totalPages: Showing entries $startIndex-${endIndex - 1} (${currentPageEntries.size} entries, entriesPerPage=$entriesPerPage)")
                                if (currentPageEntries.isNotEmpty()) {
                                    val firstDate = currentPageEntries.first().second.date
                                    val lastDate = currentPageEntries.last().second.date
                                    android.util.Log.d("PAGINATION_DISPLAY", "Date range: $firstDate to $lastDate")
                                    
                                    // Check if we're showing the expected number of entries
                                    val expectedEntries = minOf(entriesPerPage, entriesWithIndex.size - startIndex)
                                    if (currentPageEntries.size != expectedEntries) {
                                        android.util.Log.w("PAGINATION_DISPLAY", "WARNING: Showing ${currentPageEntries.size} entries but expected $expectedEntries")
                                    }
                                    
                                    // Validate sequential dates (entries should be continuous)
                                    if (currentPage > 0 && startIndex > 0) {
                                        val previousPageLastIndex = startIndex - 1
                                        if (previousPageLastIndex < entriesWithIndex.size) {
                                            val previousPageLastDate = entriesWithIndex[previousPageLastIndex].second.date
                                            android.util.Log.d("PAGINATION_DISPLAY", "Previous page ended at: $previousPageLastDate, current page starts at: $firstDate")
                                        }
                                    }
                                }
                                
                                // Update total pages for gesture handler
                                totalPagesForGesture = totalPages
                                
                                // Calculate date range for current page
                                currentPageDateRange = if (currentPageEntries.isNotEmpty()) {
                                    val dates = currentPageEntries.mapNotNull { (_, entry) -> 
                                        if (entry.date.isNotBlank()) entry.date else null 
                                    }
                                    if (dates.isNotEmpty()) {
                                        // Parse first date to get month/year
                                        val firstDate = dates.firstOrNull() ?: ""
                                        try {
                                            // Date format is DD.MM.YYYY
                                            val parts = firstDate.split(".")
                                            if (parts.size == 3) {
                                                val month = parts[1].toIntOrNull() ?: 1
                                                val year = parts[2]
                                                val monthNames = when (selectedLanguage) {
                                                    "German" -> listOf("Jan", "Feb", "Mär", "Apr", "Mai", "Jun", "Jul", "Aug", "Sep", "Okt", "Nov", "Dez")
                                                    "Spanish" -> listOf("Ene", "Feb", "Mar", "Abr", "May", "Jun", "Jul", "Ago", "Sep", "Oct", "Nov", "Dic")
                                                    else -> listOf("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")
                                                }
                                                val result = "${monthNames.getOrNull(month - 1) ?: "?"} $year"
                                                android.util.Log.d("DateNavigator", "Calculated date range: '$result' from date: '$firstDate'")
                                                result
                                            } else {
                                                android.util.Log.d("DateNavigator", "Date parts size != 3: ${parts.size}")
                                                ""
                                            }
                                        } catch (e: Exception) {
                                            android.util.Log.e("DateNavigator", "Error parsing date", e)
                                            ""
                                        }
                                    } else {
                                        android.util.Log.d("DateNavigator", "No dates found in entries")
                                        ""
                                    }
                                } else {
                                    android.util.Log.d("DateNavigator", "No current page entries")
                                    ""
                                }
                                
                                Column(
                                    modifier = Modifier.fillMaxSize()
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .weight(1f)
                                            .fillMaxWidth()
                                            .onGloballyPositioned { coordinates ->
                                                val h = coordinates.size.height
                                                if (h > 0 && rowsViewportHeightPx != h) {
                                                    rowsViewportHeightPx = h
                                                }
                                            }
                                    ) {
                                        Column(modifier = Modifier.fillMaxSize()) {
                                            currentPageEntries.forEachIndexed { indexInPage, (originalIndex, entry) ->
                                                TableRow(
                                                    entry = entry,
                                                    entryIndex = originalIndex,
                                                    labels = labels,
                                                    isSecured = securedEntryIds.contains(entry.id),
                                                    confirmedEditingSessions = confirmedEditingSessions,
                                                    onShowEditConfirmDialog = { cellKey, action ->
                                                        pendingEditAction = {
                                                            action()
                                                            confirmedEditingSessions = confirmedEditingSessions + cellKey
                                                        }
                                                        showEditConfirmDialog = true
                                                    },
                                                    onEntryChanged = { index, updatedEntry ->
                                                        saveToUndoStack(entries, context.getString(R.string.action_edit_entry))
                                                        val updatedEntries = entries.toMutableList()
                                                        if (index < updatedEntries.size) {
                                                            updatedEntries[index] = updatedEntry
                                                            entries = updatedEntries
                                                            hasUnsavedChanges = true
                                                            if (autoSaveOnExit) {
                                                                DataManager.saveEntries(context, updatedEntries)
                                                            }
                                                        }
                                                    },
                                                    onDeleteEntry = { index ->
                                                        saveToUndoStack(entries, context.getString(R.string.action_delete_entry))
                                                        val updatedEntries = entries.toMutableList()
                                                        if (index in 0 until updatedEntries.size) {
                                                            updatedEntries.removeAt(index)
                                                            entries = updatedEntries
                                                            hasUnsavedChanges = true
                                                            if (autoSaveOnExit) {
                                                                DataManager.saveEntries(context, updatedEntries)
                                                            }
                                                            cellTextFieldValues.keys.removeAll { (entryIndex, _) -> entryIndex >= index }
                                                            val keysToUpdate = cellTextFieldValues.keys.filter { (entryIndex, _) -> entryIndex > index }
                                                            keysToUpdate.forEach { (entryIndex, columnName) ->
                                                                val value = cellTextFieldValues.remove(entryIndex to columnName)
                                                                val updatedValue = value?.copy(text = value.text)
                                                                if (updatedValue != null) {
                                                                    cellTextFieldValues[entryIndex - 1 to columnName] = updatedValue
                                                                }
                                                            }
                                                        }
                                                    },
                                                    fontColor = fontColor,
                                                    backgroundColor = backgroundColor,
                                                    gridColor = gridColor,
                                                    insulinColumnColor = insulinColumnColor,
                                                    focusedCell = focusedCell,
                                                    focusRequesters = focusRequesters,
                                                    onRequestFocus = { cellKey -> focusedCell = cellKey },
                                                    cellTextFieldValues = cellTextFieldValues,
                                                    foodPresets = foodPresets,
                                                    setFoodPresets = { foodPresets = it },
                                                    scale = scale,
                                                    heightScale = heightScale,
                                                    selectedLanguage = selectedLanguage,
                                                    customColumns = customColumns,
                                                    customMarkers = customMarkers,
                                                    onCustomMarkersUpdate = { updated ->
                                                        CustomMarkerManager.saveCustomMarkers(context, updated)
                                                        customMarkers = updated
                                                    },
                                                    foodWarningMessage = foodWarningMessage,
                                                    onFoodWarningMessageChange = { foodWarningMessage = it },
                                                    pendingFoodAction = pendingFoodAction,
                                                    onPendingFoodActionChange = { pendingFoodAction = it },
                                                    showFoodWarning = showFoodWarning,
                                                    onFoodWarningChange = { showFoodWarning = it },
                                                    onWarningFoodNameChange = { warningFoodName = it },
                                                    highlightedOccurrenceDate = highlightedOccurrenceDate,
                                                    highlightedOccurrenceTimeOfDay = highlightedOccurrenceTimeOfDay,
                                                    occurrenceHighlightToken = occurrenceHighlightToken,
                                                    context = context,
                                                    onMeasuredHeightPx = if (indexInPage == 0) {
                                                        { heightPx -> measuredRowHeightPx = heightPx }
                                                    } else {
                                                        null
                                                    }
                                                )
                                            }
                                        }
                                    }

                                    // Keep pagination controls outside the zoomed/horizontal table container.
                                    // Fixed controls are rendered below in the root Box so they stay stable.
                                }
                    
                    // Timeline-style scrollbar for pagination mode - OUTSIDE horizontal scroll container
                    // OLD SCROLL-BASED PAGING - Preserved but inactive (useButtonPaging is always true)
                    if (usePaginationMode && !useButtonPaging && totalPagesForGesture > 1 && scrollbarAlpha > 0f) {
                        Box(
                            modifier = Modifier
                                .fillMaxHeight(0.7f)
                                .width(56.dp)
                                .padding(start = 8.dp, top = 60.dp, bottom = 100.dp)
                                .alpha(scrollbarAlpha)
                                .pointerInput(totalPagesForGesture) {
                                    awaitPointerEventScope {
                                        while (true) {
                                            val event = awaitPointerEvent()
                                            when (event.type) {
                                                androidx.compose.ui.input.pointer.PointerEventType.Press,
                                                androidx.compose.ui.input.pointer.PointerEventType.Move -> {
                                                    val change = event.changes.firstOrNull()
                                                    if (change != null) {
                                                        // Calculate which page based on Y position
                                                        val yPosition = change.position.y
                                                        val scrollbarHeight = size.height
                                                        
                                                        // Map Y position to page number
                                                        val targetPage = ((yPosition / scrollbarHeight) * totalPagesForGesture)
                                                            .toInt()
                                                            .coerceIn(0, totalPagesForGesture - 1)
                                                        
                                                        currentPage = targetPage
                                                        change.consume()
                                                    }
                                                }
                                                androidx.compose.ui.input.pointer.PointerEventType.Release -> {
                                                    // Consume release event to prevent tap-to-hide
                                                    event.changes.forEach { it.consume() }
                                                }
                                            }
                                        }
                                    }
                                }
                        ) {
                                // Scrollbar track
                                Box(
                                    modifier = Modifier
                                        .fillMaxHeight()
                                        .width(4.dp)
                                        .align(Alignment.Center)
                                        .background(
                                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.2f),
                                            shape = RoundedCornerShape(2.dp)
                                        )
                                )
                                
                                // Page indicators
                                Column(
                                    modifier = Modifier
                                        .fillMaxHeight()
                                        .align(Alignment.Center),
                                    verticalArrangement = Arrangement.SpaceBetween
                                ) {
                                    for (page in 0 until totalPagesForGesture) {
                                        Box(
                                            modifier = Modifier
                                                .size(if (page == currentPage) 20.dp else 16.dp)
                                                .pointerInput(page) {
                                                    detectTapGestures(
                                                        onTap = {
                                                            currentPage = page
                                                        }
                                                    )
                                                }
                                                .background(
                                                    color = if (page == currentPage) {
                                                        MaterialTheme.colorScheme.primary
                                                    } else {
                                                        MaterialTheme.colorScheme.onSurface.copy(alpha = 0.4f)
                                                    },
                                                    shape = CircleShape
                                                )
                                        )
                                    }
                                }
                                
                                // Enhanced aesthetic calendar navigator with color-changing gradients
                                if (currentPageDateRange.isNotBlank()) {
                                    // Extract month number for color selection
                                    val monthNumber = remember(currentPageDateRange) {
                                        try {
                                            val monthName = currentPageDateRange.split(" ").firstOrNull() ?: ""
                                            val monthNames = when (selectedLanguage) {
                                                "German" -> listOf("Jan", "Feb", "Mär", "Apr", "Mai", "Jun", "Jul", "Aug", "Sep", "Okt", "Nov", "Dez")
                                                "Spanish" -> listOf("Ene", "Feb", "Mar", "Abr", "May", "Jun", "Jul", "Ago", "Sep", "Oct", "Nov", "Dic")
                                                else -> listOf("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")
                                            }
                                            monthNames.indexOf(monthName) + 1
                                        } catch (e: Exception) {
                                            1
                                        }
                                    }
                                    
                                    // Color palette that changes based on month (seasonal colors)
                                    val gradientColors = remember(monthNumber) {
                                        when (monthNumber) {
                                            1 -> listOf(Color(0xFF1E3A8A), Color(0xFF3B82F6)) // January - Deep Blue
                                            2 -> listOf(Color(0xFF7C3AED), Color(0xFFA78BFA)) // February - Purple
                                            3 -> listOf(Color(0xFF059669), Color(0xFF34D399)) // March - Spring Green
                                            4 -> listOf(Color(0xFFDB2777), Color(0xFFF472B6)) // April - Pink
                                            5 -> listOf(Color(0xFFEA580C), Color(0xFFFB923C)) // May - Orange
                                            6 -> listOf(Color(0xFFDC2626), Color(0xFFF87171)) // June - Red
                                            7 -> listOf(Color(0xFFCA8A04), Color(0xFFFBBF24)) // July - Gold
                                            8 -> listOf(Color(0xFF0891B2), Color(0xFF22D3EE)) // August - Cyan
                                            9 -> listOf(Color(0xFF7C2D12), Color(0xFFFB923C)) // September - Autumn
                                            10 -> listOf(Color(0xFF9333EA), Color(0xFFD946EF)) // October - Magenta
                                            11 -> listOf(Color(0xFF475569), Color(0xFF94A3B8)) // November - Gray
                                            12 -> listOf(Color(0xFF0C4A6E), Color(0xFF0EA5E9)) // December - Winter Blue
                                            else -> listOf(Color(0xFF3B82F6), Color(0xFF60A5FA))
                                        }
                                    }
                                    
                                    // Calendar date navigator - elegant minimalist design
                                    val displayText = if (currentPageDateRange.isNotBlank()) {
                                        currentPageDateRange
                                    } else {
                                        "---"
                                    }
                                    
                                    Column(
                                        modifier = Modifier
                                            .align(Alignment.TopCenter)
                                            .offset(y = (-40).dp)
                                            .wrapContentSize(),
                                        horizontalAlignment = Alignment.CenterHorizontally
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.DateRange,
                                            contentDescription = "Calendar",
                                            tint = Color.White.copy(alpha = 0.9f),
                                            modifier = Modifier.size(24.dp)
                                        )
                                        Spacer(modifier = Modifier.height(4.dp))
                                        Text(
                                            text = displayText.also { 
                                                android.util.Log.d("DateNavigator", "Rendering: '$it' (original: '$currentPageDateRange', length: ${it.length})")
                                            },
                                            color = Color.White,
                                            fontSize = 14.sp,
                                            fontWeight = FontWeight.Bold,
                                            letterSpacing = 0.5.sp,
                                            maxLines = 1,
                                            softWrap = false,
                                            modifier = Modifier
                                                .background(
                                                    color = Color.White.copy(alpha = 0.15f),
                                                    shape = RoundedCornerShape(12.dp)
                                                )
                                                .border(
                                                    width = 1.dp,
                                                    color = Color.White.copy(alpha = 0.3f),
                                                    shape = RoundedCornerShape(12.dp)
                                                )
                                                .padding(horizontal = 12.dp, vertical = 6.dp),
                                            style = androidx.compose.ui.text.TextStyle(
                                                shadow = androidx.compose.ui.graphics.Shadow(
                                                    color = Color.Black.copy(alpha = 0.3f),
                                                    offset = Offset(1f, 1f),
                                                    blurRadius = 2f
                                                )
                                            )
                                        )
                                    }
                                }
                            }
                        }
                    }
                    
                    // Fixed floating action buttons outside scrollable area
                    
                    // Button-based paging controls (only shown when button paging is enabled)
                    Box(modifier = Modifier.fillMaxSize()) {
                        val isKeyboardVisible = WindowInsets.ime.getBottom(LocalDensity.current) > 0
                        val showTableControls = usePaginationMode &&
                            useButtonPaging &&
                            !showAnalysisScreen &&
                            !isKeyboardVisible &&
                            drawerState.currentValue == DrawerValue.Closed &&
                            drawerState.targetValue == DrawerValue.Closed

                        if (showTableControls) {
                            androidx.compose.ui.window.Popup(
                                alignment = Alignment.BottomCenter,
                                offset = androidx.compose.ui.unit.IntOffset(0, 0)
                            ) {
                                Row(
                                    modifier = Modifier
                                        .width(screenWidth)
                                        .padding(horizontal = 12.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        FloatingActionButton(
                                            onClick = { if (currentPage > 0) currentPage-- },
                                            modifier = Modifier.size(40.dp),
                                            containerColor = MaterialTheme.colorScheme.tertiary.copy(alpha = 0.9f),
                                            contentColor = MaterialTheme.colorScheme.onTertiary
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.KeyboardArrowUp,
                                                contentDescription = "Previous Page",
                                                modifier = Modifier.size(20.dp)
                                            )
                                        }

                                        FloatingActionButton(
                                            onClick = { if (currentPage < totalPagesForGesture - 1) currentPage++ },
                                            modifier = Modifier.size(40.dp),
                                            containerColor = MaterialTheme.colorScheme.tertiary.copy(alpha = 0.9f),
                                            contentColor = MaterialTheme.colorScheme.onTertiary
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.KeyboardArrowDown,
                                                contentDescription = "Next Page",
                                                modifier = Modifier.size(20.dp)
                                            )
                                        }
                                    }

                                    Surface(
                                        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.9f),
                                        shape = RoundedCornerShape(20.dp)
                                    ) {
                                        Text(
                                            text = "${currentPage + 1}/${maxOf(1, totalPagesForGesture)}",
                                            modifier = Modifier.padding(horizontal = 24.dp, vertical = 12.dp),
                                            style = MaterialTheme.typography.titleLarge,
                                            color = MaterialTheme.colorScheme.onSurfaceVariant,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }

                                    Row(
                                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        FloatingActionButton(
                                            onClick = { showDateFilterDialog = true },
                                            modifier = Modifier.size(40.dp),
                                            containerColor = MaterialTheme.colorScheme.secondary.copy(alpha = 0.9f),
                                            contentColor = MaterialTheme.colorScheme.onSecondary
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.DateRange,
                                                contentDescription = stringResource(R.string.filter_entries_by_date),
                                                modifier = Modifier.size(20.dp)
                                            )
                                        }

                                        FloatingActionButton(
                                            onClick = {
                                                saveToUndoStack(entries, context.getString(R.string.action_add_new_entry))
                                                val today = java.time.LocalDate.now()
                                                val formattedDate = "${today.dayOfMonth.toString().padStart(2, '0')}.${today.monthValue.toString().padStart(2, '0')}.${today.year}"
                                                entries = entries + DiabetesEntry(date = formattedDate)
                                                hasUnsavedChanges = true
                                                if (autoSaveOnExit) {
                                                    DataManager.saveEntries(context, entries)
                                                }
                                            },
                                            modifier = Modifier.size(40.dp)
                                        ) {
                                            Icon(
                                                imageVector = Icons.Filled.Add,
                                                contentDescription = "Add Entry",
                                                modifier = Modifier.size(20.dp)
                                            )
                                        }
                                    }
                                }
                            }
                        } else {
                            FloatingActionButton(
                                onClick = {
                                    showDateFilterDialog = true
                                },
                                modifier = Modifier
                                    .align(Alignment.BottomEnd)
                                    .padding(end = 88.dp, bottom = 8.dp),
                                containerColor = MaterialTheme.colorScheme.secondary.copy(alpha = 0.9f),
                                contentColor = MaterialTheme.colorScheme.onSecondary
                            ) {
                                Icon(
                                    imageVector = Icons.Default.DateRange,
                                    contentDescription = stringResource(R.string.filter_entries_by_date),
                                    modifier = Modifier.size(24.dp)
                                )
                            }

                            FloatingActionButton(
                                onClick = {
                                    saveToUndoStack(entries, context.getString(R.string.action_add_new_entry))
                                    val today = java.time.LocalDate.now()
                                    val formattedDate = "${today.dayOfMonth.toString().padStart(2, '0')}.${today.monthValue.toString().padStart(2, '0')}.${today.year}"
                                    entries = entries + DiabetesEntry(date = formattedDate)
                                    hasUnsavedChanges = true
                                    if (autoSaveOnExit) {
                                        DataManager.saveEntries(context, entries)
                                    }
                                },
                                modifier = Modifier
                                    .align(Alignment.BottomEnd)
                                    .padding(end = 16.dp, bottom = 8.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.Add,
                                    contentDescription = "Add Entry",
                                    modifier = Modifier.size(24.dp)
                                )
                            }
                        }
                    }
                }
            }
        }
        
        // Confirmation dialog for editing secured data
        if (showEditConfirmDialog) {
            androidx.compose.material3.AlertDialog(
                onDismissRequest = {
                    showEditConfirmDialog = false
                    pendingEditAction = null
                },
                properties = DialogProperties(
                    dismissOnBackPress = true,
                    dismissOnClickOutside = false
                ),
                title = {
                    Text(
                        text = stringResource(R.string.edit_saved_data_title)
                    )
                },
                text = {
                    Text(
                        text = stringResource(R.string.edit_saved_data_message)
                    )
                },
                confirmButton = {
                    TextButton(
                        onClick = {
                            pendingEditAction?.invoke()
                            showEditConfirmDialog = false
                            pendingEditAction = null
                        }
                    ) {
                        Text(
                            text = stringResource(R.string.yes_edit)
                        )
                    }
                },
                dismissButton = {
                    TextButton(
                        onClick = {
                            showEditConfirmDialog = false
                            pendingEditAction = null
                            // Clear focus when canceling to prevent cursor remaining active
                            focusManager.clearFocus()
                        }
                    ) {
                        Text(
                            text = stringResource(R.string.cancel)
                        )
                    }
                }
            )
        }
        
        // Exit confirmation dialog when user has unsaved changes - Modern styled
        if (showExitConfirmDialog) {
            Dialog(
                onDismissRequest = { showExitConfirmDialog = false }
            ) {
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(16.dp),
                    shape = RoundedCornerShape(24.dp),
                    colors = CardDefaults.cardColors(
                        containerColor = MaterialTheme.colorScheme.surface
                    ),
                    elevation = CardDefaults.cardElevation(defaultElevation = 8.dp)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(24.dp),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        // Warning icon
                        Icon(
                            imageVector = Icons.Outlined.Warning,
                            contentDescription = null,
                            modifier = Modifier.size(48.dp),
                            tint = MaterialTheme.colorScheme.error.copy(alpha = 0.8f)
                        )
                        
                        Spacer(modifier = Modifier.height(16.dp))
                        
                        // Title
                        Text(
                            text = stringResource(R.string.unsaved_changes_title),
                            style = MaterialTheme.typography.headlineSmall,
                            fontWeight = FontWeight.Bold,
                            textAlign = TextAlign.Center
                        )
                        
                        Spacer(modifier = Modifier.height(12.dp))
                        
                        // Message
                        Text(
                            text = stringResource(R.string.unsaved_changes_message),
                            style = MaterialTheme.typography.bodyMedium,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f),
                            textAlign = TextAlign.Center
                        )
                        
                        Spacer(modifier = Modifier.height(8.dp))
                        
                        // Tip
                        Text(
                            text = stringResource(R.string.auto_save_tip),
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                            textAlign = TextAlign.Center
                        )
                        
                        Spacer(modifier = Modifier.height(24.dp))
                        
                        // Buttons - stacked vertically for better visibility
                        Column(
                            modifier = Modifier.fillMaxWidth(),
                            verticalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            // Save & Close button - Primary action (most prominent)
                            Button(
                                onClick = {
                                    // Save all changes
                                    DataManager.saveEntries(context, entries)
                                    val tempExisting = SettingsManager.loadSettings(context)
                                    SettingsManager.saveSettings(context, tempExisting.copy(
                                        fontColor = fontColor,
                                        backgroundColor = backgroundColor,
                                        gridColor = gridColor,
                                        insulinColumnColor = insulinColumnColor,
                                        isDarkMode = isDarkMode,
                                        language = selectedLanguage,
                                        colorsModifiedByUser = true,
                                        scale = scale,
                                        widthScale = widthScale,
                                        zoomPercentage = zoomPercentage
                                    ))
                                    
                                    // Mark entries with data as secured
                                    val entriesWithData = entries.filter { entry ->
                                        entry.date.isNotBlank() && (
                                            entry.morningBloodSugarLevel.isNotBlank() ||
                                            entry.afternoonBloodSugarLevel.isNotBlank() ||
                                            entry.eveningBloodSugarLevel.isNotBlank() ||
                                            entry.nightBloodSugarLevel.isNotBlank() ||
                                            entry.morningInsulin.isNotBlank() ||
                                            entry.afternoonInsulin.isNotBlank() ||
                                            entry.eveningInsulin.isNotBlank() ||
                                            entry.remarks.isNotBlank() ||
                                            entry.foodEntriesByColumn.values.any { it.isNotEmpty() }
                                        )
                                    }
                                    securedEntryIds = entriesWithData.map { it.id }.toSet()
                                    SettingsManager.saveSecuredEntryIds(context, securedEntryIds)
                                    
                                    hasUnsavedChanges = false
                                    confirmedEditingSessions = emptySet()
                                    showExitConfirmDialog = false
                                    
                                    Toast.makeText(context, context.getString(R.string.all_changes_saved), Toast.LENGTH_SHORT).show()
                                    (context as? Activity)?.finish()
                                },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(50.dp),
                                shape = RoundedCornerShape(12.dp),
                                colors = ButtonDefaults.buttonColors(
                                    containerColor = MaterialTheme.colorScheme.primary
                                )
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.Check,
                                    contentDescription = null,
                                    modifier = Modifier.size(20.dp)
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(
                                    text = stringResource(R.string.save_and_close),
                                    style = MaterialTheme.typography.labelLarge,
                                    fontWeight = FontWeight.SemiBold
                                )
                            }
                            
                            // Discard button - Destructive action (outlined, red)
                            OutlinedButton(
                                onClick = {
                                    // Revert entries to session start state
                                    if (sessionStartEntries.isNotEmpty()) {
                                        entries = sessionStartEntries
                                        DataManager.saveEntries(context, sessionStartEntries)
                                    }
                                    hasUnsavedChanges = false
                                    confirmedEditingSessions = emptySet()
                                    showExitConfirmDialog = false
                                    (context as? Activity)?.finish()
                                },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(50.dp),
                                shape = RoundedCornerShape(12.dp),
                                border = BorderStroke(1.5.dp, MaterialTheme.colorScheme.error.copy(alpha = 0.7f)),
                                colors = ButtonDefaults.outlinedButtonColors(
                                    contentColor = MaterialTheme.colorScheme.error
                                )
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.Delete,
                                    contentDescription = null,
                                    modifier = Modifier.size(20.dp)
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(
                                    text = stringResource(R.string.close_without_saving),
                                    style = MaterialTheme.typography.labelLarge,
                                    fontWeight = FontWeight.Medium
                                )
                            }
                            
                            // Cancel button - Neutral action (text only)
                            TextButton(
                                onClick = { showExitConfirmDialog = false },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(44.dp)
                            ) {
                                Text(
                                    text = stringResource(R.string.cancel),
                                    style = MaterialTheme.typography.labelLarge,
                                    color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
                                )
                            }
                        }
                    }
                }
            }
        }
        
        // Exit snackbar for double-tap confirmation when auto-save is enabled
        if (showExitSnackbar) {
            LaunchedEffect(showExitSnackbar) {
                // Position snackbar at bottom of screen
            }
            
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(16.dp),
                contentAlignment = Alignment.BottomCenter
            ) {
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp),
                    colors = CardDefaults.cardColors(
                        containerColor = MaterialTheme.colorScheme.inverseSurface.copy(alpha = 0.9f)
                    ),
                    elevation = CardDefaults.cardElevation(defaultElevation = 8.dp)
                ) {
                    Text(
                        text = stringResource(R.string.press_back_again_to_exit),
                        modifier = Modifier.padding(16.dp),
                        color = MaterialTheme.colorScheme.inverseOnSurface,
                        style = MaterialTheme.typography.bodyMedium,
                        textAlign = TextAlign.Center
                    )
                }
            }
        }
        
        // Backup Export Dialog
        if (showBackupExportDialog) {
            AlertDialog(
                onDismissRequest = { showBackupExportDialog = false },
                title = {
                    Text(
                        text = when (selectedLanguage) {
                            "German" -> "Backup exportieren"
                            "Spanish" -> "Exportar copia de seguridad"
                            else -> "Export Backup"
                        }
                    )
                },
                text = {
                    Column {
                        Text(
                            text = when (selectedLanguage) {
                                "German" -> "Was möchten Sie exportieren?"
                                "Spanish" -> "¿Qué desea exportar?"
                                else -> "What would you like to export?"
                            },
                            style = MaterialTheme.typography.bodyMedium,
                            modifier = Modifier.padding(bottom = 16.dp)
                        )
                        
                        // Backup type selection
                        Column {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { selectedBackupType = BackupType.ALL }
                                    .padding(vertical = 4.dp)
                            ) {
                                RadioButton(
                                    selected = selectedBackupType == BackupType.ALL,
                                    onClick = { selectedBackupType = BackupType.ALL }
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Column {
                                    Text(
                                        text = when (selectedLanguage) {
                                            "German" -> "Alles (Empfohlen)"
                                            "Spanish" -> "Todo (Recomendado)"
                                            else -> "Everything (Recommended)"
                                        },
                                        style = MaterialTheme.typography.bodyMedium
                                    )
                                    Text(
                                        text = when (selectedLanguage) {
                                            "German" -> "Einstellungen, Daten & Presets"
                                            "Spanish" -> "Configuración, datos y presets"
                                            else -> "Settings, data & presets"
                                        },
                                        style = MaterialTheme.typography.bodySmall,
                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f)
