                var showExpandedTextArea by remember {
                    mutableStateOf(editingColumn?.showExpandedTextArea ?: false)
                }
                var showDuplicateNameError by remember { mutableStateOf(false) }
                
                // Check for duplicate names
                val isDuplicateName = remember(newColumnName, customColumns, editingColumn) {
                    val trimmedName = newColumnName.trim()
                    if (trimmedName.isBlank()) return@remember false
                    
                    customColumns.any { column ->
                        column.name.equals(trimmedName, ignoreCase = true) && 
                        column.id != editingColumn?.id
                    }
                }
                
                // Auto-suggest statistics based on name and unit
                LaunchedEffect(newColumnName, newColumnUnit) {
                    if (editingColumn == null && newColumnName.isNotBlank()) {
                        val tempColumn = CustomColumn(
                            name = newColumnName,
                            unit = newColumnUnit
                        )
                        includeInStatistics = CustomColumnManager.shouldSuggestStatistics(context, tempColumn)
                    }
                }
                
                AlertDialog(
