        // Marker History Dialog
        if (showMarkerHistoryDialog) {
            // Collect all markers from all entries with their context
            data class MarkerInstance(
                val marker: Marker,
                val entry: DiabetesEntry,
                val markerType: String, // "I feel bad" or custom marker name
                val markerColor: Color,
                val markerIcon: String
            )
            
            val allMarkerInstances = remember(entries, customMarkers) {
                entries.flatMap { entry ->
                    entry.markers.map { marker ->
                        val customMarkerType = if (marker.customMarkerTypeId != null) {
                            customMarkers.find { it.id == marker.customMarkerTypeId }
                        } else null
                        
                        MarkerInstance(
                            marker = marker,
                            entry = entry,
                            markerType = when {
                                marker.type == "I feel bad" -> when (selectedLanguage) {
                                    "German" -> "Ich fühle mich schlecht"
                                    "Spanish" -> "Me siento mal"
                                    else -> "I feel bad"
                                }
                                customMarkerType != null -> customMarkerType.name
                                else -> marker.type
                            },
                            markerColor = customMarkerType?.color ?: Color(0xFFFF9800),
                            markerIcon = customMarkerType?.icon ?: "😞"
                        )
                    }
                }.sortedByDescending { it.entry.date }
            }
            
            var searchQuery by remember { mutableStateOf("") }
            var selectedMarkerTypeFilter by remember { mutableStateOf<String?>(null) }
            var showFilterMenu by remember { mutableStateOf(false) }
            var showCategoryList by remember { mutableStateOf(true) } // Start with category list
            var selectedCategoryForDetails by remember { mutableStateOf<String?>(null) } // Selected category for details view
            var showTimelineFromDetails by remember { mutableStateOf(false) } // Show timeline after details
            var sortDescending by remember { mutableStateOf(true) }
            var expandedTimelineEntry by remember { mutableStateOf<String?>(null) } // Track expanded entry by unique ID
            
            var showExportMenu by remember { mutableStateOf(false) }
            
            // Filter and sort marker instances
            val filteredMarkers = remember(allMarkerInstances, searchQuery, selectedMarkerTypeFilter, sortDescending) {
                val filtered = allMarkerInstances.filter { instance ->
                    val matchesSearch = searchQuery.isEmpty() || 
                        instance.markerType.contains(searchQuery, ignoreCase = true) ||
                        instance.marker.customNote.contains(searchQuery, ignoreCase = true) ||
                        instance.entry.date.contains(searchQuery, ignoreCase = true)
                    
                    val matchesFilter = selectedMarkerTypeFilter == null || 
                        instance.markerType == selectedMarkerTypeFilter
                    
                    matchesSearch && matchesFilter
                }
                
                if (sortDescending) {
                    filtered.sortedByDescending { it.entry.date }
                } else {
                    filtered.sortedBy { it.entry.date }
                }
            }
            
            // Calculate statistics
            val markerStats = remember(allMarkerInstances) {
                allMarkerInstances.groupBy { it.markerType }
                    .mapValues { it.value.size }
                    .toList()
                    .sortedByDescending { it.second }
            }
            
            // Helper function to generate TXT export content
            fun generateMarkerHistoryTxt(): String {
                val sb = StringBuilder()
                
                // Header
                sb.appendLine("=" .repeat(50))
                sb.appendLine(when (selectedLanguage) {
                    "German" -> "MARKER-VERLAUF EXPORT"
                    "Spanish" -> "EXPORTACIÓN DE HISTORIAL DE MARCADORES"
                    else -> "MARKER HISTORY EXPORT"
                })
                sb.appendLine("=" .repeat(50))
                sb.appendLine()
                
                // Summary statistics
                sb.appendLine(when (selectedLanguage) {
                    "German" -> "ZUSAMMENFASSUNG"
                    "Spanish" -> "RESUMEN"
                    else -> "SUMMARY"
                })
                sb.appendLine("-" .repeat(50))
                sb.appendLine(when (selectedLanguage) {
                    "German" -> "Gesamt: ${allMarkerInstances.size} Marker"
                    "Spanish" -> "Total: ${allMarkerInstances.size} marcadores"
                    else -> "Total: ${allMarkerInstances.size} markers"
                })
                sb.appendLine()
                
                // Category breakdown
                for ((markerType, count) in markerStats) {
                    val categoryMarkers = allMarkerInstances.filter { it.markerType == markerType }
                    val uniqueDates = mutableSetOf<String>()
                    for (marker in categoryMarkers) {
                        uniqueDates.add(marker.entry.date)
                    }
                    val uniqueDays = uniqueDates.size
                    
                    val timeMap = mutableMapOf<String, Int>()
                    for (marker in categoryMarkers) {
                        val time = marker.marker.startTime
                        timeMap[time] = (timeMap[time] ?: 0) + 1
                    }
                    val timeDistribution = timeMap.toList().sortedByDescending { (_, count) -> count }
                    val mostCommonTime = timeDistribution.firstOrNull()
                    
                    sb.appendLine("• $markerType: $count ${when (selectedLanguage) {
                        "German" -> "mal"
                        "Spanish" -> "veces"
                        else -> "times"
                    }}")
                    sb.appendLine("  ${when (selectedLanguage) {
                        "German" -> "An $uniqueDays verschiedenen Tagen"
                        "Spanish" -> "En $uniqueDays días diferentes"
                        else -> "On $uniqueDays different days"
                    }}")
                    
                    if (mostCommonTime != null) {
                        sb.appendLine("  ${when (selectedLanguage) {
                            "German" -> "Häufigste Zeit: ${mostCommonTime.first} (${mostCommonTime.second} mal)"
                            "Spanish" -> "Hora más común: ${mostCommonTime.first} (${mostCommonTime.second} veces)"
                            else -> "Most common time: ${mostCommonTime.first} (${mostCommonTime.second} times)"
                        }}")
                    }
                    
                    val reasonMap = mutableMapOf<String, Int>()
                    for (marker in categoryMarkers) {
                        for (reason in marker.marker.reasons) {
                            reasonMap[reason] = (reasonMap[reason] ?: 0) + 1
                        }
                    }
                    val reasonCounts = reasonMap.toList().sortedByDescending { (_, count) -> count }
                    
                    if (reasonCounts.isNotEmpty()) {
                        sb.appendLine("  ${when (selectedLanguage) {
                            "German" -> "Häufigste Gründe:"
                            "Spanish" -> "Razones más comunes:"
                            else -> "Most common reasons:"
                        }}")
                        for ((reason, reasonCount) in reasonCounts.take(5)) {
                            sb.appendLine("    - $reason ($reasonCount)")
                        }
                    }
                    sb.appendLine()
                }
                
                sb.appendLine()
                sb.appendLine("=" .repeat(50))
                sb.appendLine(when (selectedLanguage) {
                    "German" -> "DETAILLIERTE ZEITLEISTE"
                    "Spanish" -> "CRONOLOGÍA DETALLADA"
                    else -> "DETAILED TIMELINE"
                })
                sb.appendLine("=" .repeat(50))
                sb.appendLine()
                
                // Timeline entries sorted by date (descending)
                val sortedMarkers = allMarkerInstances.sortedWith(compareByDescending { it.entry.date })
                for (instance in sortedMarkers) {
                    sb.appendLine("${instance.entry.date} - ${instance.marker.startTime}")
                    sb.appendLine("  ${when (selectedLanguage) {
                        "German" -> "Typ:"
                        "Spanish" -> "Tipo:"
                        else -> "Type:"
                    }} ${instance.markerType}")
                    
                    // Blood sugar and insulin from the cell
                    val cellValue = when (instance.marker.cellId) {
                        "morning" -> instance.entry.morningBloodSugarLevel
                        "afternoon" -> instance.entry.afternoonBloodSugarLevel
                        "evening" -> instance.entry.eveningBloodSugarLevel
                        "night" -> instance.entry.nightBloodSugarLevel
                        else -> ""
                    }
                    val insulinValue = when (instance.marker.cellId) {
                        "morning" -> instance.entry.morningInsulin
                        "afternoon" -> instance.entry.afternoonInsulin
                        "evening" -> instance.entry.eveningInsulin
                        else -> ""
                    }
                    
                    if (cellValue.isNotEmpty()) {
                        sb.appendLine("  ${when (selectedLanguage) {
                            "German" -> "Blutzucker:"
                            "Spanish" -> "Azúcar en sangre:"
                            else -> "Blood Sugar:"
                        }} $cellValue")
                    }
                    if (insulinValue.isNotEmpty()) {
                        sb.appendLine("  ${when (selectedLanguage) {
                            "German" -> "Insulin:"
                            "Spanish" -> "Insulina:"
                            else -> "Insulin:"
                        }} $insulinValue")
                    }
                    
                    if (instance.marker.reasons.isNotEmpty()) {
                        sb.appendLine("  ${when (selectedLanguage) {
                            "German" -> "Gründe:"
                            "Spanish" -> "Razones:"
                            else -> "Reasons:"
                        }}")
                        for (reason in instance.marker.reasons) {
                            sb.appendLine("    - $reason")
                        }
                    }
                    
                    if (instance.marker.customNote.isNotEmpty()) {
                        sb.appendLine("  ${when (selectedLanguage) {
                            "German" -> "Notiz:"
                            "Spanish" -> "Nota:"
                            else -> "Note:"
                        }} ${instance.marker.customNote}")
                    }
                    
                    sb.appendLine()
                }
                
                return sb.toString()
            }
            
            val context = LocalContext.current

            val openPatternOverview: () -> Unit = {
                analysisOpenedFromPatternInsights = true
                analysisDateRange = null
                analysisDaysToAnalyze = 36500
                detectedPatterns = PatternDetectionEngine.detectPatterns(
                    entries = entries,
                    customMarkers = customMarkers,
                    daysToAnalyze = analysisDaysToAnalyze,
                    context = context,
                    dateRange = analysisDateRange
                )
                PatternStorageManager.savePatterns(context, detectedPatterns)
                showMarkerHistoryDialog = false
                showAnalysisScreen = true
                scope.launch { drawerState.close() }
            }

            val navigateToDateFromAnalysisMarkers: (String) -> Unit = { navigationPayload ->
                // Save current state before navigating
                previousFilterState = selectedDateFilter
                previousCustomStartDate = customStartDate
                previousCustomEndDate = customEndDate
                previousSpecificDate = specificDate
                previousFlexibleNumber = flexibleNumber
                previousFlexibleUnit = flexibleUnit
                previousPage = currentPage
                isViewingOccurrence = true
                navigationSource = "analysis_markers_overview"

                // Close Analysis & Markers dialog
                showMarkerHistoryDialog = false

                val (date, timeOfDay) = decodeOccurrenceNavigationPayload(navigationPayload)

                val parsedDate = listOf("dd-MM-yyyy", "dd.MM.yyyy", "yyyy-MM-dd")
                    .firstNotNullOfOrNull { pattern ->
                        runCatching {
                            java.time.LocalDate.parse(
                                date,
                                java.time.format.DateTimeFormatter.ofPattern(pattern)
                            )
                        }.getOrNull()
                    }

                if (parsedDate != null) {
                    customStartDate = null
                    customEndDate = null
                    specificDate = parsedDate
                    selectedDateFilter = DateFilter.SPECIFIC_DATE
                    currentPage = 0

                    if (timeOfDay != null) {
                        highlightedOccurrenceDate = parsedDate
                        highlightedOccurrenceTimeOfDay = timeOfDay
                        occurrenceHighlightToken += 1
                    } else {
                        highlightedOccurrenceDate = null
                        highlightedOccurrenceTimeOfDay = null
                    }
                } else {
                    android.util.Log.e("Navigation", "Failed to parse date from analysis markers: $date")
                }
            }
            
