                                            val mostCommonTime = timeDistribution.firstOrNull()
                                            val allReasons = categoryMarkers.flatMap { it.marker.reasons }
                                            val reasonCounts = allReasons.groupBy { it }
                                                .mapValues { it.value.size }.toList().sortedByDescending { it.second }
                                            
                                            HorizontalDivider(modifier = Modifier.padding(vertical = 8.dp))
                                            
