@Composable
fun ExpandableText(
    text: String,
    modifier: Modifier = Modifier,
    style: androidx.compose.ui.text.TextStyle = LocalTextStyle.current,
    maxLines: Int = 2
) {
    val density = LocalDensity.current
    var containerSize by remember { mutableStateOf(androidx.compose.ui.unit.IntSize.Zero) }
    var textSize by remember { mutableStateOf(androidx.compose.ui.unit.IntSize.Zero) }
    var isTextTruncated by remember { mutableStateOf(false) }
    var scrollOffset by remember { mutableStateOf(0f) }
    
    val textMeasurer = rememberTextMeasurer()
    
    LaunchedEffect(text, style, containerSize.width) {
        if (containerSize.width > 0) {
            val measured = textMeasurer.measure(
                text = text,
                style = style,
                maxLines = maxLines,
                constraints = androidx.compose.ui.unit.Constraints(maxWidth = containerSize.width)
            )
            textSize = measured.size
            
            val fullTextMeasured = textMeasurer.measure(
                text = text,
                style = style,
                constraints = androidx.compose.ui.unit.Constraints(maxWidth = Int.MAX_VALUE)
            )
            
            isTextTruncated = fullTextMeasured.size.width > containerSize.width || 
                             fullTextMeasured.lineCount > maxLines
        }
    }
    
    Box(
        modifier = modifier
            .onSizeChanged { containerSize = it }
            .clipToBounds()
    ) {
        if (isTextTruncated) {
            val fullTextMeasured = textMeasurer.measure(
                text = text,
                style = style,
                constraints = androidx.compose.ui.unit.Constraints(maxWidth = Int.MAX_VALUE)
            )
            val maxScrollOffset = maxOf(0f, fullTextMeasured.size.width - containerSize.width.toFloat())
            
            Box(
                modifier = Modifier
                    .pointerInput(Unit) {
                        detectHorizontalDragGestures(
                            onDragEnd = {
                                // Snap back to bounds if needed
                                if (scrollOffset < 0) scrollOffset = 0f
                                if (scrollOffset > maxScrollOffset) scrollOffset = maxScrollOffset
                            }
                        ) { _, dragAmount ->
                            val newOffset = scrollOffset - dragAmount
                            scrollOffset = newOffset.coerceIn(0f, maxScrollOffset)
                        }
                    }
            ) {
                // Show truncated text with ellipsis when not scrolled
                if (scrollOffset == 0f) {
                    Text(
                        text = text,
                        style = style,
                        maxLines = 1,
                        overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis,
                        softWrap = false,
                        textAlign = TextAlign.Start
                    )
                } else {
                    // Show full scrollable text when user is scrolling
                    Text(
                        text = text,
                        style = style,
                        maxLines = 1,
                        overflow = androidx.compose.ui.text.style.TextOverflow.Visible,
                        softWrap = false,
                        textAlign = TextAlign.Start,
                        modifier = Modifier.offset(x = with(density) { (-scrollOffset).toDp() })
                    )
                }
            }
        } else {
            Text(
                text = text,
                style = style,
                maxLines = maxLines,
                overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis,
                textAlign = TextAlign.Center,
                lineHeight = 16.sp
            )
        }
    }
}

@Composable
fun MarqueeText(
    text: String,
    modifier: Modifier = Modifier,
    fontSize: androidx.compose.ui.unit.TextUnit = 14.sp,
    textAlign: TextAlign = TextAlign.Center,
    color: Color = Color.Black
) {
    ExpandableText(
        text = text,
        modifier = modifier,
        style = LocalTextStyle.current.copy(
            fontSize = fontSize,
            color = color,
            textAlign = textAlign
        )
    )
}

