    val relevantMarkers = remember(currentEntry?.markers, markerCellId, isDateCell, timeOfDay) {
        val markers = currentEntry?.markers ?: emptyList()
        when {
            markers.isEmpty() -> emptyList()
            isDateCell -> markers.filter { it.startTime == "all_day" || it.cellId == "date" }
            markerCellId != null -> markers.filter { it.cellId == markerCellId }
            timeOfDay != null -> markers.filter { it.startTime == timeOfDay }
            else -> emptyList()
        }
    }
    
    val hasRelevantMarker = relevantMarkers.isNotEmpty()
    
