            if (marker.type == "feel_bad") {
                // Default color for "I feel bad" marker
                Color(0xFFFF9800) // Orange
            } else if (marker.customMarkerTypeId != null) {
                // Get color from custom marker type
                customMarkers.firstOrNull { it.id == marker.customMarkerTypeId }?.color
                    ?: Color(0xFFFF9800) // Fallback to orange if marker type not found
            } else {
                Color(0xFFFF9800) // Fallback to orange
            }
        }
    }
    
    // Create gradient brush for multiple markers - properly memoized
    val markerBorderBrush = remember(markerBorderColors.size, markerBorderColors.hashCode()) {
        if (markerBorderColors.size > 1) {
            // Multiple markers: create gradient with smooth transitions
            Brush.sweepGradient(
                colors = markerBorderColors
            )
        } else {
            // Single marker: solid color
            null
        }
    }
    
    val singleMarkerColor = if (markerBorderColors.size == 1) markerBorderColors.first() else Color(0xFFFF9800)

    var pressStartTime by remember { mutableStateOf(0L) }
    var isLongPressHandled by remember { mutableStateOf(false) }
    var showInterceptOverlay by remember { mutableStateOf(false) }
    var shouldHideOverlay by remember { mutableStateOf(false) }
    var isPressing by remember { mutableStateOf(false) }
    var allowTextFieldInteraction by remember { mutableStateOf(true) }
    var suppressEditConfirmation by remember { mutableStateOf(false) } // Suppress edit dialog during long press
    // LaunchedEffect to hide overlay after release
    LaunchedEffect(shouldHideOverlay) {
        if (shouldHideOverlay) {
            kotlinx.coroutines.delay(100)
            showInterceptOverlay = false
            shouldHideOverlay = false
            // Re-enable text field after overlay is hidden
            if (!isLongPressHandled) {
                allowTextFieldInteraction = true
            }
        }
    }
    
    // LaunchedEffect to re-enable text field after long press dialog is dismissed
    LaunchedEffect(showMarkerSnackbar, showMarkerMenu, showFeelBadDialog) {
        if (!showMarkerSnackbar && !showMarkerMenu && !showFeelBadDialog && isLongPressHandled) {
            // Dialog was dismissed, immediately reset states to allow next long press
            isLongPressHandled = false // Reset FIRST to allow new long press detection
            isPressing = false // Ensure pressing state is cleared
            
            // Then re-enable interactions after short delay
            kotlinx.coroutines.delay(100)
            allowTextFieldInteraction = true
            showInterceptOverlay = false // Reset overlay to show + button again
            suppressEditConfirmation = false // Reset the flag
            markerMenuWasOpened = false // Reset marker menu flag
        }
    }
    
    // LaunchedEffect to check for long press
    LaunchedEffect(isPressing) {
        if (isPressing) {
            kotlinx.coroutines.delay(1000)
            if (isPressing && !isLongPressHandled) {
                // Long press detected! NOW block the text field
                allowTextFieldInteraction = false
                showInterceptOverlay = true // Show overlay to block further interactions
                
                // Close ANY dialogs that might have been opened by short tap actions
                showAddFoodDialog = false
                showFoodList = false
                showContextMenu = false // Close date context menu
                showDatePicker = false // Close date picker
                
                // Dismiss keyboard if it was opened
                keyboardController?.hide()
                
                // Remove focus from text field if it gained focus
                focusManager.clearFocus()
                
                // Always show marker menu on long press, regardless of existing markers
                // This allows users to add more markers or edit existing ones
                showMarkerMenu = true
                markerMenuWasOpened = true // Track that marker menu was opened
                
                isLongPressHandled = true
                suppressEditConfirmation = true // Suppress edit confirmation only for long press
            }
        } else {
            // Press was released - clear the suppression flag after a delay
            // This allows the next tap to show the edit confirmation dialog
            kotlinx.coroutines.delay(300)
            if (!isPressing) { // Double check we're still not pressing
                suppressEditConfirmation = false
            }
        }
    }
    
    Box(
        modifier = modifier
            .pointerInput(showMarkerMenu, showFeelBadDialog, showAddFoodDialog, showFoodList, showDatePicker, showContextMenu) {
                // Only intercept touches when NO dialogs are showing
                if (!showMarkerMenu && !showFeelBadDialog && !showAddFoodDialog && !showFoodList && !showDatePicker && !showContextMenu) {
                    awaitPointerEventScope {
                        while (true) {
                            // Intercept at Initial pass to get events before children
                            val down = awaitPointerEvent(androidx.compose.ui.input.pointer.PointerEventPass.Initial)
                            
                            if (down.type == androidx.compose.ui.input.pointer.PointerEventType.Press) {
                                // DON'T consume the press event - let it through for short taps
                                // We'll only block if it becomes a long press
                                
                                pressStartTime = System.currentTimeMillis()
                                isLongPressHandled = false
                                isPressing = true
                                // Set markerMenuWasOpened immediately to prevent edit dialog during long press detection
                                markerMenuWasOpened = true
                                // DON'T block text field immediately - let short taps through
                                
                                var isPressed = true
                                
                                // Monitor events while pressed
                                while (isPressed) {
                                    val event = awaitPointerEvent(androidx.compose.ui.input.pointer.PointerEventPass.Initial)
                                    
                                    when (event.type) {
                                        androidx.compose.ui.input.pointer.PointerEventType.Release -> {
                                            isPressed = false
                                            isPressing = false
                                            
                                            val pressDuration = System.currentTimeMillis() - pressStartTime
                                            
                                            // If it was a long press, consume the release to prevent click
                                            if (isLongPressHandled) {
                                                event.changes.forEach { it.consume() }
                                                // Keep text field blocked
                                                // markerMenuWasOpened stays true until menu closes
                                            } else {
                                                // Short tap - reset the flag immediately so edit dialog can show
                                                markerMenuWasOpened = false
                                            }
                                            // Short press - text field remains enabled (was never blocked)
                                            
                                            shouldHideOverlay = true
                                        }
                                        androidx.compose.ui.input.pointer.PointerEventType.Move -> {
                                            // If long press was handled, consume move events
                                            if (isLongPressHandled) {
                                                event.changes.forEach { it.consume() }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
    ) {
        Box {
            Surface(
                modifier = Modifier
                    .padding(horizontal = 2.dp)
                    .height((40 * scale * heightScale).dp) // Height affected by both scale and heightScale
                    .then(
                        if (hasRelevantMarker) {
                            // Make orange border clickable to view/edit markers
                            Modifier.clickable(
                                indication = null,
                                interactionSource = remember { MutableInteractionSource() }
                            ) {
                                showMarkerMenu = true
                            }
                        } else {
                            Modifier
                        }
                    ),
                shape = RoundedCornerShape(6.dp),
                color = MaterialTheme.colorScheme.surface.copy(alpha = 0.7f),
                border = if (hasRelevantMarker) {
                    if (markerBorderBrush != null) {
                        // Multiple markers: use gradient brush
                        BorderStroke(2.5.dp, markerBorderBrush)
                    } else {
                        // Single marker: use solid color
                        BorderStroke(2.5.dp, singleMarkerColor)
                    }
                } else {
                    BorderStroke(0.5.dp, gridColor.copy(alpha = 0.3f)) // Normal border
                }
            ) {
        Row(
            modifier = Modifier.padding(4.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            // Text field gets more space when no food items, less space when food items exist to show count button
            Box(
                modifier = Modifier
                    .then(
                        if (isInsulinCell) {
                            // Insulin cells always take full width (no food button)
                            Modifier.fillMaxWidth()
                        } else if (currentCellFoodItems.isNotEmpty()) {
                            // When food items exist, give space for the food count button
                            Modifier.weight(2.2f)
                        } else {
                            // When no food items, give space for the add food button
                            Modifier.weight(2.2f)
                        }
                    )
                    .padding(end = 6.dp),
                contentAlignment = Alignment.Center
            ) {
                if (!isDateCell) {
                    BasicTextField(
                            value = value,
                            enabled = allowTextFieldInteraction, // Only allow interaction when explicitly enabled
                            onValueChange = { newValue ->
                            // Allow normal editing - confirmation dialog is now handled on focus
                            // Normalize comma to dot for decimal input (supports both European and US formats)
                            val normalizedText = if (customKeyboardType == "number") {
                                // Remove spaces and replace comma with dot for numeric input
                                newValue.text.replace(" ", "").replace(',', '.')
                            } else {
                                newValue.text
                            }
                            val normalizedValue = newValue.copy(text = normalizedText)
                            onValueChange(normalizedValue)
                        },
                        textStyle = TextStyle(
                            color = fontColor,
                            fontSize = 14.sp,
                            textAlign = TextAlign.Center
                        ),
                        singleLine = true,
                        keyboardOptions = KeyboardOptions(
                            imeAction = ImeAction.Next,
                            keyboardType = if (customKeyboardType == "number") KeyboardType.Decimal else KeyboardType.Text
                        ),
                        modifier = Modifier
                            .fillMaxWidth()
                            .focusRequester(focusRequester)
                            .onFocusChanged { state ->
                                // Define variables outside the conditional blocks for proper scope
                                val hasData = value.text.isNotBlank()
                                val isBloodSugarOrInsulinCell =
                                    cellKey.endsWith("_morningBloodSugar") ||
                                    cellKey.endsWith("_afternoonBloodSugar") ||
                                    cellKey.endsWith("_eveningBloodSugar") ||
                                    cellKey.endsWith("_nightBloodSugar") ||
                                    cellKey.endsWith("_morningInsulin") ||
                                    cellKey.endsWith("_afternoonInsulin") ||
                                    cellKey.endsWith("_eveningInsulin")
                                
                                if (state.isFocused) {
                                    onRequestFocus()
                                    
                                    // Debug: Log all conditions for edit confirmation
                                    println("DEBUG EDIT_CONFIRM: cellKey=$cellKey, isSecured=$isSecured, hasData=$hasData, isBloodSugarOrInsulinCell=$isBloodSugarOrInsulinCell, confirmedEditingSessions.contains=${ confirmedEditingSessions.contains(cellKey) }, suppressEditConfirmation=$suppressEditConfirmation, markerMenuWasOpened=$markerMenuWasOpened, onShowEditConfirmDialog=${onShowEditConfirmDialog != null}")
                                    
                                    // Show confirmation dialog immediately when focusing on a filled (secured) cell
                                    // Only for cells with actual data in Blood Sugar Control or Insulin sections
                                    // BUT: Don't show if we're in the middle of detecting a long press or if marker menu was opened
                                    if (isSecured && hasData && isBloodSugarOrInsulinCell && !confirmedEditingSessions.contains(cellKey) && !suppressEditConfirmation && !markerMenuWasOpened) {
                                        println("DEBUG EDIT_CONFIRM: All conditions met! Showing dialog for cellKey=$cellKey")
                                        // Show confirmation dialog immediately - no delay for new focus
                                        onShowEditConfirmDialog?.invoke(cellKey) {
                                            // Focus is already gained, now show keyboard and move cursor to end
                                            keyboardController?.show()
                                            // Move cursor to end of text
                                            val textLength = value.text.length
                                            onValueChange(value.copy(selection = TextRange(textLength)))
                                        }
                                    }
                                }
                                isEditing = state.isFocused
                                // Only show keyboard if we're not going to show a confirmation dialog
                                val needsConfirmation = isSecured && hasData && isBloodSugarOrInsulinCell && !confirmedEditingSessions.contains(cellKey)
                                if (state.isFocused && !needsConfirmation) {
                                    keyboardController?.show()
                                }
                            }
                            .testTag("EditableTextField")
                    )

                    if (value.text.isEmpty() && !isEditing) {
                        Text(
                            text = hint,
                            color = fontColor.copy(alpha = 0.5f),
                            fontSize = 14.sp,
                            textAlign = TextAlign.Center,
                            modifier = Modifier.fillMaxWidth()
                        )
                    }
                } else {
                    val nestedScrollConnection = remember {
                        object : NestedScrollConnection {
                            override fun onPostScroll(
                                consumed: Offset,
                                available: Offset,
                                source: NestedScrollSource
                            ): Offset {
                                // Only consume remaining horizontal scroll to prevent parent scrolling
                                return if (available.x != 0f) Offset(available.x, 0f) else Offset.Zero
                            }
                        }
                    }
                    
                    LazyRow(
                        modifier = Modifier
                            .fillMaxWidth()
                            .nestedScroll(nestedScrollConnection),
                        horizontalArrangement = Arrangement.Center,
                        userScrollEnabled = true
                    ) {
                        item {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                modifier = Modifier.padding(horizontal = 4.dp)
                            ) {
                                Text(
                                    text = value.text.ifEmpty { hint },
                                    fontSize = 14.sp,
                                    textAlign = TextAlign.Center,
                                    color = if (value.text.isEmpty()) fontColor.copy(alpha = 0.5f) else fontColor,
                                    maxLines = 1,
                                    overflow = TextOverflow.Visible,
                                    softWrap = false,
                                    modifier = Modifier
                                        .padding(start = 4.dp, end = 2.dp)
                                        .clickable {
                                            // Only open context menu if it wasn't a long press
                                            if (!isLongPressHandled) {
                                                if (value.text.isEmpty()) {
                                                    val today = LocalDate.now().format(DateTimeFormatter.ofPattern("dd.MM.yyyy"))
                                                    onValueChange(TextFieldValue(today))
                                                }
                                                showContextMenu = true
                                            }
                                        }
                                )
                                
                                IconButton(
                                    onClick = { 
                                        // Only open context menu if it wasn't a long press
                                        if (!isLongPressHandled) {
                                            showContextMenu = true
                                        }
                                    },
                                    modifier = Modifier.size(24.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.DateRange,
                                        contentDescription = "Date options",
                                        tint = fontColor.copy(alpha = 0.6f),
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                            }
                        }
                    }
                    DropdownMenu(
                        expanded = showContextMenu,
                        onDismissRequest = { showContextMenu = false }
                    ) {
                        DropdownMenuItem(
                            text = { Text(stringResource(R.string.today)) },
                            onClick = {
                                val today = LocalDate.now().format(DateTimeFormatter.ofPattern("dd.MM.yyyy"))
                                onValueChange(TextFieldValue(today))
                                showContextMenu = false
                            }
                        )
                        DropdownMenuItem(
                            text = { Text(stringResource(R.string.clear)) },
                            onClick = {
                                onValueChange(TextFieldValue(""))
                                showContextMenu = false
                            }
                        )
                        DropdownMenuItem(
                            text = { Text(stringResource(R.string.pick_date)) },
                            onClick = {
                                showContextMenu = false
                                showDatePicker = true
                            }
                        )
                        HorizontalDivider()
                        DropdownMenuItem(
                            text = { 
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Icon(
                                        imageVector = Icons.Default.Star,
                                        contentDescription = "Marker",
                                        modifier = Modifier.size(18.dp).padding(end = 8.dp)
                                    )
                                    Text(
                                        text = when (selectedLanguage) {
                                            "German" -> "Markierung"
                                            "Spanish" -> "Marcador"
                                            else -> "Marker"
                                        }
                                    )
                                }
                            },
                            onClick = {
                                showContextMenu = false
                                showMarkerMenu = true
                            }
                        )
                        if (onDelete != null) {
                            HorizontalDivider()
                            DropdownMenuItem(
                                text = { Text(stringResource(R.string.delete_entry), color = MaterialTheme.colorScheme.error) },
                                onClick = {
                                    showContextMenu = false
                                    onDelete()
                                }
                            )
                        }
                    }
                }
            }

            // Only show food chips/add button in the dedicated food column
            if (isFoodCell) {
                val blinkTransition = rememberInfiniteTransition(label = "foodCounterBlink")
                val blinkPulse by blinkTransition.animateFloat(
                    initialValue = 0f,
                    targetValue = 1f,
                    animationSpec = infiniteRepeatable(
                        animation = tween(durationMillis = 420, easing = LinearEasing),
                        repeatMode = RepeatMode.Reverse
                    ),
                    label = "foodCounterBlinkPulse"
                )
                val foodChipColor = if (isFoodCounterBlinking) {
                    lerp(
                        MaterialTheme.colorScheme.primaryContainer,
                        MaterialTheme.colorScheme.tertiaryContainer,
                        blinkPulse
                    )
                } else {
                    MaterialTheme.colorScheme.primaryContainer
                }
                val auraColor = lerp(
                    MaterialTheme.colorScheme.tertiary,
                    MaterialTheme.colorScheme.primary,
                    blinkPulse
                )
                val auraScale = if (isFoodCounterBlinking) 1f + (0.38f * blinkPulse) else 1f
                val auraAlpha = if (isFoodCounterBlinking) 0.18f + (0.42f * (1f - blinkPulse)) else 0f

                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(2.dp),
                    modifier = Modifier.weight(1f, false)
                ) {
                    if (currentCellFoodItems.isNotEmpty()) {
                        Box(
                            modifier = Modifier
                                .height((28 * scale * heightScale).dp) // Height affected by both scale and heightScale
                                .widthIn(min = maxOf(24.dp, (24 * scale).dp)) // Minimum width with absolute floor
                        ) {
                            if (isFoodCounterBlinking) {
                                Box(
                                    modifier = Modifier
                                        .matchParentSize()
                                        .graphicsLayer {
                                            scaleX = auraScale
                                            scaleY = auraScale
                                        }
                                        .background(
                                            color = auraColor.copy(alpha = auraAlpha),
                                            shape = RoundedCornerShape((14 * scale).dp)
                                        )
                                )
                            }

                            Surface(
                                shape = RoundedCornerShape((12 * scale).dp),
                                color = foodChipColor,
                                modifier = Modifier
                                    .matchParentSize()
                                    .clickable { showFoodList = true }
                                    .testTag("FoodCountChip")
                            ) {
                                Box(
                                    contentAlignment = Alignment.Center,
                                    modifier = Modifier
                                        .padding(horizontal = (6 * scale).dp, vertical = (2 * scale).dp)
                                        .fillMaxSize()
                                ) {
                                    val foodCountText = "${currentCellFoodItems.size}"

                                    Text(
                                        text = foodCountText,
                                        color = MaterialTheme.colorScheme.onPrimaryContainer,
                                        fontSize = (12 * scale).sp,
                                        maxLines = 1,
                                        overflow = TextOverflow.Visible,
                                        softWrap = false,
                                        textAlign = TextAlign.Center
                                    )
                                }
                            }
                        }
                    }
                    // Only show add food button for non-insulin cells and when no food items exist
                    if (!isInsulinCell && currentCellFoodItems.isEmpty()) {
                        IconButton(
                            onClick = { 
                                if (!showInterceptOverlay) {
                                    showAddFoodDialog = true
                                }
                            },
                            enabled = !showInterceptOverlay,
                            modifier = Modifier
                                .height((28 * scale * heightScale).dp) // Height affected by both scale and heightScale
                                .width(maxOf(24.dp, (28 * scale).dp))
                                .testTag("AddFoodButton")
                        ) {
                            Icon(
                                imageVector = Icons.Default.Add,
                                contentDescription = "Add food",
                                tint = fontColor.copy(alpha = if (showInterceptOverlay) 0.3f else 0.6f),
                                modifier = Modifier.size((16 * scale).dp)
                            )
                        }
                    }

                    DropdownMenu(
                        expanded = showContextMenu,
                        onDismissRequest = { showContextMenu = false }
                    ) {
                        DropdownMenuItem(
                            text = { Text("Clear") },
                            onClick = {
                                onValueChange(TextFieldValue(""))
                                showContextMenu = false
                            }
                        )
                        DropdownMenuItem(
                            text = { Text("Pick Date...") },
                            onClick = {
                                showContextMenu = false
                                showDatePicker = true
                            }
                        )
                    }
                    if (onDelete != null) {
                        HorizontalDivider()
                        DropdownMenuItem(
                            text = { Text("Delete Entry", color = MaterialTheme.colorScheme.error) },
                            onClick = {
                                showContextMenu = false
                                onDelete()
                            }
                        )
                    }
                }
            }
        }

        // Marker count badge removed - orange border is sufficient indicator
    }

        if (showFoodList && currentCellFoodItems.isNotEmpty()) {
            var showDeleteConfirmation by remember { mutableStateOf(false) }
            var showAddConfirmation by remember { mutableStateOf(false) }
            var itemToDelete by remember { mutableStateOf(-1) }
            
            Dialog(onDismissRequest = { showFoodList = false }) {
                Surface(
                    shape = RoundedCornerShape(16.dp),
                    color = MaterialTheme.colorScheme.surface,
                    tonalElevation = 8.dp
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp)
                    ) {
                        Text(
                            text = "Food Entries (${currentCellFoodItems.size})",
                            style = MaterialTheme.typography.titleMedium,
                            modifier = Modifier.padding(bottom = 8.dp)
                        )
                        FlowRow(
                            horizontalArrangement = Arrangement.spacedBy(4.dp),
                            verticalArrangement = Arrangement.spacedBy(4.dp)
                        ) {
                            // Create a snapshot of the current list to ensure proper rendering
                            val foodItems = currentCellFoodItems.toList()
                            foodItems.forEachIndexed { index, food ->
                                // Get risk-based highlight color
                                val highlightColor = FoodWarningHelper.getFoodHighlightColor(food.name, context)
                                val backgroundColor = highlightColor ?: MaterialTheme.colorScheme.primaryContainer
                                val riskLevel = FoodWarningHelper.getFoodRiskLevel(food.name, context)
                                
                                Surface(
                                    shape = RoundedCornerShape(16.dp),
                                    color = backgroundColor
                                ) {
                                    Row(
                                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        // Show warning icon for high-risk foods
                                        if (riskLevel >= 3) {
                                            Text(
                                                text = "⚠️",
                                                fontSize = 14.sp,
                                                modifier = Modifier.padding(end = 2.dp)
                                            )
                                        }
                                        Text(
                                            text = food.emoji,
                                            fontSize = 18.sp,
                                            modifier = Modifier.padding(end = 4.dp)
                                        )
                                        Text(
                                            text = food.name,
                                            color = MaterialTheme.colorScheme.onPrimaryContainer,
                                            fontSize = 14.sp
                                        )
                                        IconButton(
                                            onClick = {
                                                itemToDelete = index
                                                showDeleteConfirmation = true
                                            },
                                            modifier = Modifier.size(16.dp)
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.Close,
                                                contentDescription = "Remove food",
                                                tint = MaterialTheme.colorScheme.onPrimaryContainer,
                                                modifier = Modifier.size(12.dp)
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                    Spacer(modifier = Modifier.height(48.dp))
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.End,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Button(
                            onClick = {
                                showAddConfirmation = true
                            },
                            contentPadding = PaddingValues(horizontal = 12.dp, vertical = 1.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.Add,
                                contentDescription = "Add food",
                                modifier = Modifier.size(14.dp)
                            )
                            Spacer(modifier = Modifier.width(3.dp))
                            Text(
                                text = when (selectedLanguage) {
                                    "German" -> "Essen hinzufügen"
                                    "Spanish" -> "Agregar comida"
                                    else -> "Add Food"
                                },
                                fontSize = 12.sp
                            )
                        }
                    }
                }
            }
            
            // Delete confirmation dialog
            if (showDeleteConfirmation) {
                AlertDialog(
                    onDismissRequest = { showDeleteConfirmation = false },
                    title = { Text("Confirm Delete") },
                    text = { Text("Are you sure you want to remove this food entry?") },
                    confirmButton = {
                        TextButton(
                            onClick = {
                                // Remove only the specific instance at this index
                                val updatedList = currentCellFoodItems.toMutableList()
                                updatedList.removeAt(itemToDelete)
                                onCurrentCellFoodItemsChange(updatedList)
                                if (updatedList.isEmpty()) {
                                    showFoodList = false
                                }
                                showDeleteConfirmation = false
                                itemToDelete = -1
                            }
                        ) {
                            Text(stringResource(R.string.delete))
                        }
                    },
                    dismissButton = {
                        TextButton(
                            onClick = { showDeleteConfirmation = false }
                        ) {
                            Text(stringResource(R.string.cancel))
                        }
                    }
                )
            }
            
            // Add food confirmation dialog
            if (showAddConfirmation) {
                AlertDialog(
                    onDismissRequest = { showAddConfirmation = false },
                    title = { 
                        Text(
                            text = when (selectedLanguage) {
                                "German" -> "Essen hinzufügen bestätigen"
                                "Spanish" -> "Confirmar agregar comida"
                                else -> "Confirm Add Food"
                            }
                        )
                    },
                    text = { 
                        Text(
                            text = when (selectedLanguage) {
                                "German" -> "Sind Sie sicher, dass Sie mehr Essen zu diesem Eintrag hinzufügen möchten?"
                                "Spanish" -> "¿Está seguro de que desea agregar más comida a esta entrada?"
                                else -> "Are you sure you want to add more food to this entry?"
                            }
                        )
                    },
                    confirmButton = {
                        TextButton(
                            onClick = {
                                showFoodList = false
                                showAddFoodDialog = true
                                showAddConfirmation = false
                            }
                        ) {
                            Text(
                                text = when (selectedLanguage) {
                                    "German" -> "Hinzufügen"
                                    "Spanish" -> "Agregar"
                                    else -> "Add"
                                }
                            )
                        }
                    },
                    dismissButton = {
                        TextButton(
                            onClick = { showAddConfirmation = false }
                        ) {
                            Text(
                                text = when (selectedLanguage) {
                                    "German" -> "Abbrechen"
                                    "Spanish" -> "Cancelar"
                                    else -> "Cancel"
                                }
                            )
                        }
                    }
                )
            }
        }

        if (showAddFoodDialog) {
            var activeDeletePreset by remember { mutableStateOf<String?>(null) }
            var showEmojiPicker by remember { mutableStateOf(false) }
            var tooltipPreset by remember { mutableStateOf<FoodPreset?>(null) }
            // var showFoodPickerDialog by remember { mutableStateOf(false) } // May be used later
            var flyingPreset by remember { mutableStateOf<FoodPreset?>(null) }
            var flyingStartPosition by remember { mutableStateOf(ComposeOffset.Zero) }
            var flyingTargetPosition by remember { mutableStateOf(ComposeOffset.Zero) }
            var flyingAnimationProgress by remember { mutableStateOf(0f) }
            var searchText by remember { mutableStateOf("") }

            AlertDialog(
                onDismissRequest = {
                    showAddFoodDialog = false
                    newFoodText = ""
                    selectedEmoji = ""
                    searchText = ""
                },
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable { activeDeletePreset = null },
                title = { 
                    Text(
                        text = when (selectedLanguage) {
                            "German" -> "Essen hinzufügen"
                            "Spanish" -> "Agregar comida"
                            else -> "Add Food"
                        }
                    )
                },
                text = {
                    val scrollState = rememberScrollState()
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .verticalScroll(scrollState)
                            .padding(16.dp)
                    ) {
                        // Search bar for existing presets
                        if (foodPresets.isNotEmpty()) {
                            OutlinedTextField(
                                value = searchText,
                                onValueChange = { searchText = it },
                                label = { 
                                    Text(
                                        text = when (selectedLanguage) {
                                            "German" -> "Vorlagen suchen"
                                            "Spanish" -> "Buscar plantillas"
                                            else -> "Search presets"
                                        }
                                    )
                                },
                                leadingIcon = { Icon(Icons.Default.Search, contentDescription = null) },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(bottom = 16.dp),
                                singleLine = true
                            )
                        }
                        
                        // Food name input and emoji selector in a row (emoji left, same height as text field)
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(12.dp),
                            modifier = Modifier.fillMaxWidth().padding(bottom = 16.dp)
                        ) {
                            val foodFieldHeight = 56.dp // Default OutlinedTextField height
                            Surface(
                                modifier = Modifier
                                    .size(foodFieldHeight)
                                    .clickable { showEmojiPicker = true },
                                shape = RoundedCornerShape(8.dp),
                                color = MaterialTheme.colorScheme.primaryContainer,
                                border = BorderStroke(
                                    1.dp,
                                    MaterialTheme.colorScheme.primary
                                )
                            ) {
                                Box(
                                    contentAlignment = Alignment.Center,
                                    modifier = Modifier.fillMaxSize()
                                ) {
                                    Text(
                                        text = selectedEmoji.ifEmpty { "🍽️" },
                                        fontSize = 28.sp,
                                        textAlign = TextAlign.Center
                                    )
                                }
                            }
                            OutlinedTextField(
                                value = newFoodText,
                                onValueChange = { newFoodText = it },
                                label = { 
                                    Text(
                                        text = when (selectedLanguage) {
                                            "German" -> "Essensname"
                                            "Spanish" -> "Nombre de comida"
                                            else -> "Food name"
                                        }
                                    )
                                },
                                singleLine = true,
                                modifier = Modifier
                                    .weight(1f)
                                    .heightIn(min = foodFieldHeight)
                                    .padding(vertical = 4.dp),
                                keyboardOptions = KeyboardOptions(imeAction = ImeAction.Done),
                                keyboardActions = KeyboardActions(
                                    onDone = {
                                        if (newFoodText.isNotEmpty()) {
                                                // Check if food is suspicious before adding
                                                val warningMessage = FoodWarningChecker.checkFoodWarning(
                                                    context = context,
                                                    foodName = newFoodText,
                                                    language = selectedLanguage
                                                )
                                                
                                                val addFoodAction = {
                                                    // Add to presets if not already present
                                                    val newPreset = FoodPreset(name = newFoodText, emoji = selectedEmoji)
                                                    if (foodPresets.none { it.name == newFoodText && it.emoji == selectedEmoji }) {
                                                        PresetManager.addFoodPreset(context, newPreset)
                                                        setFoodPresets(PresetManager.getFoodPresets(context))
                                                    }
                                                    onCurrentCellFoodItemsChange(currentCellFoodItems + newPreset)
                                                    newFoodText = ""
                                                    selectedEmoji = ""
                                                }
                                                
                                                if (warningMessage != null) {
                                                    // Show warning dialog
                                                    onFoodWarningMessageChange(warningMessage)
                                                    onPendingFoodActionChange(addFoodAction)
                                                    onWarningFoodNameChange(newFoodText)
                                                    onFoodWarningChange(true)
                                                } else {
                                                    // No warning, add directly
                                                    addFoodAction()
                                                }
                                                // Keep the dialog open after adding food
                                            }                                  }
                                )
                            )
                        }
                        Spacer(modifier = Modifier.height(8.dp))
                        
                        // Saved presets section
                        // Sorting toggle
                        var sortByLastUsed by remember { mutableStateOf(true) } // Default to "Last Used"
                        
                        if (foodPresets.isNotEmpty()) {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(bottom = 8.dp),
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                // Sort by Name button
                                FilterChip(
                                    onClick = { sortByLastUsed = false },
                                    label = {
                                        Text(
                                            text = when (selectedLanguage) {
                                                "German" -> "Name"
                                                "Spanish" -> "Nombre"
                                                else -> "Name"
                                            },
                                            fontSize = 12.sp
                                        )
                                    },
                                    selected = !sortByLastUsed,
                                    modifier = Modifier.height(32.dp)
                                )
                                
                                // Sort by Last Used button
                                FilterChip(
                                    onClick = { sortByLastUsed = true },
                                    label = {
                                        Text(
                                            text = when (selectedLanguage) {
                                                "German" -> "Zuletzt verwendet"
                                                "Spanish" -> "Último uso"
                                                else -> "Last Used"
                                            },
                                            fontSize = 12.sp
                                        )
                                    },
                                    selected = sortByLastUsed,
                                    modifier = Modifier.height(32.dp)
                                )
                            }
                        }
                        
                        val filteredPresets = if (searchText.isEmpty()) {
                            foodPresets
                        } else {
                            foodPresets.filter { preset ->
                                preset.name.contains(searchText, ignoreCase = true)
                            }
                        }.let { presets ->
                            // Apply sorting
                            if (sortByLastUsed) {
                                presets.sortedByDescending { it.lastUsed }
                            } else {
                                presets.sortedBy { it.name.lowercase() }
                            }
                        }
                        
                        if (filteredPresets.isNotEmpty()) {
                            Text(
                                text = when (selectedLanguage) {
                                    "German" -> "Ihre Vorlagen"
                                    "Spanish" -> "Sus plantillas"
                                    else -> "Your Presets"
                                },
                                style = MaterialTheme.typography.titleSmall,
                                modifier = Modifier.padding(bottom = 8.dp)
                            )
                            // Box as a container for the FlowRow
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { activeDeletePreset = null }
                            ) {
                                // Main FlowRow for food presets
                                FlowRow(
                                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                                    verticalArrangement = Arrangement.spacedBy(8.dp),
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    filteredPresets.forEach { preset ->
                                        key(preset.id) {
                                            // Animation state for recently used items
                                            val isRecentlyUsed = sortByLastUsed && preset.lastUsed > 0 && 
                                                System.currentTimeMillis() - preset.lastUsed < 2000 // 2 seconds
                                            
                                            val animatedScale by animateFloatAsState(
                                                targetValue = if (isRecentlyUsed) 1.1f else 1f,
                                                animationSpec = spring(
                                                    dampingRatio = Spring.DampingRatioMediumBouncy,
                                                    stiffness = Spring.StiffnessMedium
                                                ),
                                                label = "preset_scale"
                                            )
                                            
                                            val animatedAlpha by animateFloatAsState(
                                                targetValue = if (isRecentlyUsed) 0.8f else 1f,
                                                animationSpec = tween(durationMillis = 300),
                                                label = "preset_alpha"
                                            )
                                            
                                            // Flying animation effect
                                            LaunchedEffect(flyingPreset?.id) {
                                                if (flyingPreset?.id == preset.id) {
                                                    // Set target position (top of the grid)
                                                    flyingTargetPosition = ComposeOffset(flyingStartPosition.x, 0f)
                                                    
                                                    // Start animation immediately
                                                    flyingAnimationProgress = 0.01f // Small value to make it visible
                                                    
                                                    // Small delay to ensure position is captured
                                                    delay(100)
                                                    
                                                    // Animate progress from 0 to 1
                                                    val animatable = Animatable(0f)
                                                    animatable.animateTo(
                                                        targetValue = 1f,
                                                        animationSpec = tween(
                                                            durationMillis = 1000,
                                                            easing = FastOutSlowInEasing
                                                        )
                                                    ) { 
                                                        flyingAnimationProgress = this.value
                                                    }
                                                    
                                                    // Clear flying state after animation
                                                    delay(200)
                                                    flyingPreset = null
                                                    flyingAnimationProgress = 0f
                                                }
                                            }
                                            
                                            Column(
                                            horizontalAlignment = Alignment.CenterHorizontally,
                                            modifier = Modifier
                                                .width(100.dp)
                                                .padding(4.dp)
                                                .scale(animatedScale)
                                                .alpha(animatedAlpha)
                                                .onGloballyPositioned { coordinates ->
                                                    // Store position for flying animation
                                                    if (flyingPreset?.id == preset.id && flyingAnimationProgress == 0f) {
                                                        flyingStartPosition = coordinates.positionInParent()
                                                    }
                                                }
                                        ) {
                                            // Main preset button
                                            Surface(
                                                shape = RoundedCornerShape(8.dp),
                                                color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.7f),
                                                modifier = Modifier
                                                    .size(90.dp)
                                                    .clickable {
                                                        // Start flying animation if in "last used" mode
                                                        if (sortByLastUsed) {
                                                            // Ensure we have a valid start position
                                                            if (flyingStartPosition != ComposeOffset.Zero) {
                                                                flyingPreset = preset
                                                                flyingAnimationProgress = 0f
                                                            }
                                                        }
                                                        
                                                        // Check if food is suspicious before adding
                                                        val warningMessage = FoodWarningChecker.checkFoodWarning(
                                                            context = context,
                                                            foodName = preset.name,
                                                            language = selectedLanguage
                                                        )
                                                        
                                                        val addPresetAction = {
                                                            // Always allow adding the food item, regardless of edit mode
                                                            // Create a mutable list from the current items
                                                            val updatedItems = currentCellFoodItems.toMutableList()
                                                            // Add the new preset
                                                            updatedItems.add(preset)
                                                            
                                                            println("DEBUG FOOD ADD: Adding food '${preset.name}', updatedItems.size=${updatedItems.size}")
                                                            
                                                            // Update the cell's food items list with the new list
                                                            onCurrentCellFoodItemsChange(updatedItems)
                                                            
                                                            // Update last used timestamp
                                                            val updatedPreset = preset.copy(lastUsed = System.currentTimeMillis())
                                                            val updatedPresets = foodPresets.map { p ->
                                                                if (p.id == preset.id) updatedPreset else p
                                                            }
                                                            PresetManager.saveFoodPresets(context, updatedPresets)
                                                            setFoodPresets(updatedPresets)
                                                            
                                                            // Close edit tools when item is selected
                                                            activeDeletePreset = null
                                                        }
                                                        
                                                        if (warningMessage != null) {
                                                            // Show warning dialog
                                                            onFoodWarningMessageChange(warningMessage)
                                                            onPendingFoodActionChange(addPresetAction)
                                                            onWarningFoodNameChange(preset.name)
                                                            onFoodWarningChange(true)
                                                        } else {
                                                            // No warning, add directly
                                                            addPresetAction()
                                                        }
                                                        
                                                        // Show tooltip
                                                        tooltipPreset = preset
                                                        CoroutineScope(Dispatchers.Main).launch {
                                                            delay(1500)
                                                            tooltipPreset = null
                                                        }
                                                    }
                                            ) {
                                                Box(modifier = Modifier.fillMaxSize()) {
                                                    // Emoji and name in center
                                                    Column(
                                                        modifier = Modifier
                                                            .fillMaxSize()
                                                            .padding(4.dp),
                                                        horizontalAlignment = Alignment.CenterHorizontally,
                                                        verticalArrangement = Arrangement.Center
                                                    ) {
                                                        // Emoji
                                                        Text(
                                                            text = preset.emoji,
                                                            fontSize = 32.sp,
                                                            textAlign = TextAlign.Center
                                                        )
                                                        
                                                        // Name
                                                        Text(
                                                            text = preset.name,
                                                            fontSize = 12.sp,
                                                            color = MaterialTheme.colorScheme.onPrimaryContainer,
                                                            textAlign = TextAlign.Center,
                                                            maxLines = 1,
                                                            overflow = TextOverflow.Ellipsis
                                                        )
                                                    }
                                                    
                                                    // Three dots menu button
                                                    IconButton(
                                                        onClick = { activeDeletePreset = preset.id },
                                                        modifier = Modifier
                                                            .size(24.dp)
                                                            .align(Alignment.TopEnd)
                                                    ) {
                                                        Icon(
                                                            imageVector = Icons.Default.MoreVert,
                                                            contentDescription = "More options",
                                                            tint = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.7f),
                                                            modifier = Modifier.size(16.dp)
                                                        )
                                                    }
                                                    
                                                    // Show tooltip directly within the food item when it's tapped
                                                    if (tooltipPreset?.id == preset.id) {
                                                        Box(
                                                            modifier = Modifier.fillMaxSize(),
                                                            contentAlignment = Alignment.Center
                                                        ) {
                                                            FoodTagTooltip(
                                                                text = "Added",
                                                                visible = true,
                                                                modifier = Modifier.padding(4.dp)
                                                            )
                                                        }
                                                    }
                                                }
                                            }
                                            
                                            // Menu options when three-dots is clicked
                                            if (activeDeletePreset == preset.id) {
                                                Row(
                                                    horizontalArrangement = Arrangement.spacedBy(4.dp),
                                                    modifier = Modifier.padding(top = 4.dp),
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Box(
                                                        modifier = Modifier
                                                            .size(24.dp)
                                                            .background(
                                                                color = MaterialTheme.colorScheme.surface.copy(alpha = 0.9f),
                                                                shape = RoundedCornerShape(12.dp)
                                                            )
                                                            .clickable { 
                                                                showEditPresetDialog = preset
                                                                activeDeletePreset = null
                                                            },
                                                        contentAlignment = Alignment.Center
                                                    ) {
                                                        Icon(
                                                            imageVector = Icons.Default.Edit,
                                                            contentDescription = "Edit preset",
                                                            tint = MaterialTheme.colorScheme.primary,
                                                            modifier = Modifier.size(16.dp)
                                                        )
                                                    }
                                                    Box(
                                                        modifier = Modifier
                                                            .size(24.dp)
                                                            .background(
                                                                color = MaterialTheme.colorScheme.surface.copy(alpha = 0.9f),
                                                                shape = RoundedCornerShape(12.dp)
                                                            )
                                                            .clickable { 
                                                                showDeletePresetDialog = preset
                                                                activeDeletePreset = null
                                                            },
                                                        contentAlignment = Alignment.Center
                                                    ) {
                                                        Icon(
                                                            imageVector = Icons.Default.Close,
                                                            contentDescription = stringResource(R.string.delete_preset),
                                                            tint = MaterialTheme.colorScheme.error,
                                                            modifier = Modifier.size(12.dp)
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                        }
                                    }
                                }
                                
                                // Tooltips are now displayed directly within each food item
                            }
                            
                            // Flying animation overlay
                            Box(modifier = Modifier.fillMaxSize()) {
                                if (flyingPreset != null && flyingAnimationProgress > 0f) {
                                    val currentPosition = ComposeOffset(
                                        x = flyingStartPosition.x + (flyingTargetPosition.x - flyingStartPosition.x) * flyingAnimationProgress,
                                        y = flyingStartPosition.y + (flyingTargetPosition.y - flyingStartPosition.y) * flyingAnimationProgress
                                    )
                                    
                                    Surface(
                                        shape = RoundedCornerShape(8.dp),
                                        color = MaterialTheme.colorScheme.primary.copy(alpha = 0.9f),
                                        modifier = Modifier
                                            .size(90.dp)
                                            .offset(
                                                x = with(LocalDensity.current) { currentPosition.x.toDp() },
                                                y = with(LocalDensity.current) { currentPosition.y.toDp() }
                                            )
                                            .scale(1.3f - 0.3f * flyingAnimationProgress) // Start bigger, scale down
                                            .alpha(1f - flyingAnimationProgress * 0.2f) // Slight fade
                                    ) {
                                        Column(
                                            modifier = Modifier
                                                .fillMaxSize()
                                                .padding(4.dp),
                                            horizontalAlignment = Alignment.CenterHorizontally,
                                            verticalArrangement = Arrangement.Center
                                        ) {
                                            Text(
                                                text = flyingPreset!!.emoji,
                                                fontSize = 36.sp,
                                                textAlign = TextAlign.Center
                                            )
                                            Text(
                                                text = flyingPreset!!.name,
                                                fontSize = 10.sp,
                                                color = MaterialTheme.colorScheme.onPrimary,
                                                textAlign = TextAlign.Center,
                                                maxLines = 1,
                                                overflow = TextOverflow.Ellipsis
                                            )
                                        }
                                    }
                                }
                            }

                            Spacer(modifier = Modifier.height(16.dp))
                        }
                    }
                },
                confirmButton = {
                    TextButton(
                        onClick = { 
                            showAddFoodDialog = false  // Close dialog on done
                            newFoodText = ""
                            selectedEmoji = ""
                        }
                    ) {
                        Text(
                            text = when (selectedLanguage) {
                                "German" -> "Fertig"
                                "Spanish" -> "Listo"
                                else -> "Done"
                            }
                        )
                    }
                },
                dismissButton = {
                    TextButton(
                        onClick = {
                            if (newFoodText.isNotEmpty()) {
                                val newPresetToAdd = FoodPreset(
                                    name = newFoodText, 
                                    emoji = selectedEmoji,
                                    lastUsed = System.currentTimeMillis() // Set current timestamp for proper sorting
                                )
                                PresetManager.addFoodPreset(context, newPresetToAdd) // Save globally
                                
                                // Force immediate state update with the new preset list
                                val updatedPresets = PresetManager.getFoodPresets(context)
                                setFoodPresets(updatedPresets)

                                // Create a mutable list from the current items (may be used later)
                                // val updatedItems = currentCellFoodItems.toMutableList()
                                newFoodText = ""
                                selectedEmoji = ""
                                // Do not close dialog to allow multiple selections
                            }
                        },
                        enabled = newFoodText.isNotEmpty()
                    ) {
                        Text(
                            text = when (selectedLanguage) {
                                "German" -> "Essen hinzufügen"
                                "Spanish" -> "Agregar comida"
                                else -> "Add Food"
                            }
                        )
                    }
                }
            )

            // Emoji picker dialog
            if (showEmojiPicker) {
                Dialog(onDismissRequest = { showEmojiPicker = false }) {
                    Surface(
                        shape = RoundedCornerShape(16.dp),
                        color = MaterialTheme.colorScheme.surface,
                        tonalElevation = 8.dp
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(16.dp)
                        ) {
                            Text(
                                text = "Select Emoji",
                                style = MaterialTheme.typography.titleMedium,
                                modifier = Modifier.padding(bottom = 16.dp)
                            )
                            LazyVerticalGrid(
                                columns = GridCells.Adaptive(minSize = 36.dp), // Bigger icons
                                horizontalArrangement = Arrangement.spacedBy(16.dp),
                                verticalArrangement = Arrangement.spacedBy(16.dp),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .heightIn(min = 200.dp, max = 420.dp)
                            ) {
                                items(foodEmojis) { emoji ->
                                    Box(
                                        modifier = Modifier
                                            .size(36.dp)
                                            .clickable {
                                                selectedEmoji = emoji
                                                showEmojiPicker = false
                                            },
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text(
                                            text = emoji,
                                            fontSize = 20.sp,
                                            textAlign = TextAlign.Center
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        if (showDeletePresetDialog != null) {
            AlertDialog(
                onDismissRequest = { showDeletePresetDialog = null },
                title = { Text("Delete Food Preset") },
                text = { 
                    Text(
                        text = "Are you sure you want to delete '${showDeletePresetDialog!!.emoji} ${showDeletePresetDialog!!.name}'?"
                    )
                },
                confirmButton = {
                    TextButton(
                        onClick = {
                            PresetManager.removeFoodPreset(context, showDeletePresetDialog!!.id)
                            setFoodPresets(PresetManager.getFoodPresets(context))
                            showDeletePresetDialog = null
                        }
                    ) {
                        Text(stringResource(R.string.delete))
                    }
                },
                dismissButton = {
                    TextButton(onClick = { showDeletePresetDialog = null }) {
                        Text(stringResource(R.string.cancel))
                    }
                }
            )
        }

        if (showEditPresetDialog != null) {
            var editedName by remember { mutableStateOf(showEditPresetDialog!!.name) }
            var editedEmoji by remember { mutableStateOf(showEditPresetDialog!!.emoji) }
            // var showEmojiPicker by remember { mutableStateOf(false) } // May be used later
            // var showError by remember { mutableStateOf(false) } // May be used later

            Dialog(onDismissRequest = { showEditPresetDialog = null }) {
                Surface(
                    shape = RoundedCornerShape(16.dp),
                    color = MaterialTheme.colorScheme.surface,
                    tonalElevation = 8.dp
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp)
                    ) {
                        Text(
                            text = "Edit Food Preset",
                            style = MaterialTheme.typography.titleLarge,
                            modifier = Modifier.padding(bottom = 16.dp)
                        )
                        // Show emoji and food name in a row, with moderate emoji size
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(12.dp),
                            modifier = Modifier.padding(bottom = 16.dp)
                        ) {
                            Text(
                                text = editedEmoji,
                                fontSize = 32.sp,
                                modifier = Modifier.padding(end = 4.dp)
                            )
                            OutlinedTextField(
                                value = editedName,
                                onValueChange = { editedName = it },
                                label = { Text("Food name") },
                                singleLine = true,
                                modifier = Modifier.weight(1f)
                            )
                        }
                        // Emoji picker
                        Text(
                            text = "Change Emoji",
                            style = MaterialTheme.typography.bodyMedium,
                            modifier = Modifier.padding(vertical = 8.dp)
                        )
                        LazyVerticalGrid(
                            columns = GridCells.Adaptive(minSize = 48.dp),
                            horizontalArrangement = Arrangement.spacedBy(12.dp),
                            verticalArrangement = Arrangement.spacedBy(12.dp),
                            modifier = Modifier
                                .fillMaxWidth()
                                .heightIn(min = 120.dp, max = 280.dp)
                        ) {
                            items(foodEmojis) { emoji ->
                                Box(
                                    modifier = Modifier
                                        .size(48.dp)
                                        .clickable {
                                            editedEmoji = emoji
                                        },
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text(
                                        text = emoji,
                                        fontSize = 28.sp,
                                        textAlign = TextAlign.Center
                                    )
                                }
                            }
                        }
                        Row(
                            horizontalArrangement = Arrangement.End,
                            modifier = Modifier.fillMaxWidth().padding(top = 16.dp)
                        ) {
                            TextButton(onClick = { showEditPresetDialog = null }) {
                                Text("Cancel")
                            }
                            TextButton(
                                onClick = {
                                    if (editedName.isNotBlank()) {
                                        val updatedPreset = showEditPresetDialog!!.copy(
                                            name = editedName,
                                            emoji = editedEmoji
                                        )
                                        val updatedPresets = foodPresets.map { 
                                            if (it.id == updatedPreset.id) updatedPreset else it 
                                        }
                                        setFoodPresets(updatedPresets)
                                        PresetManager.saveFoodPresets(context, updatedPresets)
                                        showEditPresetDialog = null
                                    }
                                }
                            ) {
                                Text(stringResource(R.string.save))
                            }
                        }
                    }
                }
            }
        }


        if (showDatePicker) {
            val currentDate = LocalDate.now()
            var selectedYear by remember { mutableStateOf(currentDate.year) }
            var selectedMonth by remember { mutableStateOf(currentDate.monthValue) }
            
            AlertDialog(
                onDismissRequest = { showDatePicker = false },
                title = { Text("Select Date") },
                text = {
                    Column(Modifier.fillMaxWidth()) {
                        // Year and Month selection
                        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                            // Year dropdown
                            Column(Modifier.weight(1f)) {
                                Text("Year", style = MaterialTheme.typography.bodyMedium)
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    IconButton(onClick = { selectedYear-- }) {
                                        Icon(Icons.Filled.KeyboardArrowLeft, "Previous Year")
                                    }
                                    Text(
                                        "$selectedYear",
                                        Modifier.weight(1f),
                                        textAlign = TextAlign.Center
                                    )
                                    IconButton(onClick = { selectedYear++ }) {
                                        Icon(Icons.Filled.KeyboardArrowRight, "Next Year")
                                    }
                                }
                            }
                            
                            Spacer(Modifier.width(8.dp))
                            
                            // Month dropdown
                            Column(Modifier.weight(1f)) {
                                Text("Month", style = MaterialTheme.typography.bodyMedium)
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    IconButton(onClick = { 
                                        if (selectedMonth > 1) selectedMonth-- 
                                        else {
                                            selectedMonth = 12
                                            selectedYear--
                                        }
                                    }) {
                                        Icon(Icons.Filled.KeyboardArrowLeft, "Previous Month")
                                    }
                                    Text(
                                        Month.of(selectedMonth).getDisplayName(java.time.format.TextStyle.FULL_STANDALONE, Locale.getDefault()),
                                        Modifier.weight(1f),
                                        textAlign = TextAlign.Center,
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis
                                    )
                                    IconButton(onClick = { 
                                        if (selectedMonth < 12) selectedMonth++ 
                                        else {
                                            selectedMonth = 1
                                            selectedYear++
                                        }
                                    }) {
                                        Icon(Icons.Filled.KeyboardArrowRight, "Next Month")
                                    }
                                }
                            }
                        }
                        
                        Spacer(Modifier.height(8.dp))
                        HorizontalDivider()
                        Spacer(Modifier.height(8.dp))
                        
                        // Days grid
                        LazyColumn(Modifier.height(200.dp)) {
                            val yearMonth = YearMonth.of(selectedYear, selectedMonth)
                            val daysInMonth = yearMonth.lengthOfMonth()
                            val days = (1..daysInMonth).map { LocalDate.of(selectedYear, selectedMonth, it) }
                            
                            items(days) { date ->
                                val isToday = date.equals(LocalDate.now())
                                Text(
                                    text = date.format(DateTimeFormatter.ofPattern("dd.MM.yyyy")),
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable {
                                            onValueChange(TextFieldValue(date.format(DateTimeFormatter.ofPattern("dd.MM.yyyy"))))
                                            showDatePicker = false
                                        }
                                        .padding(8.dp)
                                        .background(
                                            if (isToday) MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.3f)
                                            else Color.Transparent,
                                            shape = RoundedCornerShape(4.dp)
                                        ),
                                    textAlign = TextAlign.Center,
                                    fontWeight = if (isToday) FontWeight.Bold else FontWeight.Normal
                                )
                            }
                        }
                    }
                },
                confirmButton = {
                    TextButton(onClick = { showDatePicker = false }) {
                        Text("Cancel")
                    }
                },
                dismissButton = {
                    TextButton(
                        onClick = { 
                            onValueChange(TextFieldValue(""))
                            showDatePicker = false 
                        }
                    ) {
                        Text("Clear Date")
                    }
                }
            )
        }
        
        // Transparent overlay to intercept touches during long press detection
        if (showInterceptOverlay) {
            Box(
                modifier = Modifier
                    .matchParentSize()
                    .clickable(
                        interactionSource = remember { MutableInteractionSource() },
                        indication = null
                    ) {
                        // Intercept all clicks during long press detection
                    }
            )
        }
    }
        
        // State for marker delete confirmation
        var markerToDelete by remember { mutableStateOf<Marker?>(null) }
        var showDeleteConfirmation by remember { mutableStateOf(false) }
        
        // State for marker editing
        var markerToEdit by remember { mutableStateOf<Marker?>(null) }
        var showEditMarkerDialog by remember { mutableStateOf(false) }
        
        // Marker submenu dialog
        if (showMarkerMenu) {
            // Get markers applied to this cell
            val appliedMarkers = if (currentEntry != null) {
                if (isDateCell) {
                    // Date cell: show both cell-specific markers AND all_day markers
                    currentEntry.markers.filter { it.cellId == "date" || it.startTime == "all_day" }
                } else if (markerCellId != null) {
                    // Cell-specific markers (remark, custom columns)
                    currentEntry.markers.filter { it.cellId == markerCellId }
                } else if (timeOfDay != null) {
                    // Time-based markers (blood sugar cells)
                    currentEntry.markers.filter { it.startTime == timeOfDay }
                } else {
                    emptyList()
                }
            } else {
                emptyList()
            }
            
            Dialog(onDismissRequest = { showMarkerMenu = false; showAddMarkerMenu = false }) {
                Surface(
                    shape = RoundedCornerShape(16.dp),
                    color = MaterialTheme.colorScheme.surface,
                    modifier = Modifier.padding(16.dp)
                ) {
                    Column(
                        modifier = Modifier
                            .padding(24.dp)
                            .heightIn(max = 500.dp)
                            .verticalScroll(rememberScrollState()),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Text(
                            text = when (selectedLanguage) {
                                "German" -> "Marker"
                                "Spanish" -> "Marcadores"
                                else -> "Markers"
                            },
                            style = MaterialTheme.typography.titleMedium,
                            modifier = Modifier.padding(bottom = 8.dp)
                        )
                        
                        // Show applied markers
                        if (appliedMarkers.isNotEmpty()) {
                            Text(
                                text = when (selectedLanguage) {
                                    "German" -> "Angewendet"
                                    "Spanish" -> "Aplicado"
                                    else -> "Applied"
                                },
                                style = MaterialTheme.typography.labelMedium,
                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                                modifier = Modifier.padding(bottom = 4.dp)
                            )
                            
                            appliedMarkers.forEach { marker ->
                                val customMarkerType = if (marker.type == "custom" && marker.customMarkerTypeId != null) {
                                    customMarkers.find { it.id == marker.customMarkerTypeId }
                                } else null
                                
                                // Build details text for "I feel bad" markers
                                val markerDetails = if (marker.type == "feel_bad") {
                                    buildString {
                                        // Add time of day
                                        val timeLabel = when (marker.startTime) {
                                            "morning" -> when (selectedLanguage) {
                                                "German" -> "Morgens"
                                                "Spanish" -> "Mañana"
                                                else -> "Morning"
                                            }
                                            "afternoon" -> when (selectedLanguage) {
                                                "German" -> "Nachmittags"
                                                "Spanish" -> "Tarde"
                                                else -> "Afternoon"
                                            }
                                            "evening" -> when (selectedLanguage) {
                                                "German" -> "Abends"
                                                "Spanish" -> "Noche"
                                                else -> "Evening"
                                            }
                                            "night" -> when (selectedLanguage) {
                                                "German" -> "Nachts"
                                                "Spanish" -> "Noche tarde"
                                                else -> "Night"
                                            }
                                            "all_day" -> when (selectedLanguage) {
                                                "German" -> "Ganzer Tag"
                                                "Spanish" -> "Todo el día"
                                                else -> "All day"
                                            }
                                            else -> ""
                                        }
                                        if (timeLabel.isNotEmpty()) {
                                            append("⏰ $timeLabel")
                                        }
                                        
                                        // Add symptoms/reasons
                                        if (marker.reasons.isNotEmpty()) {
                                            if (isNotEmpty()) append("\n")
                                            append(marker.reasons.joinToString(", "))
                                        }
                                        
                                        // Add custom note
                                        if (marker.customNote.isNotBlank()) {
                                            if (isNotEmpty()) append("\n")
                                            append("📝 ${marker.customNote}")
                                        }
                                    }
                                } else null
                                
                                Surface(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable {
                                            // Open edit dialog when tapping on the marker (not the X)
                                            markerToEdit = marker
                                            showEditMarkerDialog = true
                                        },
                                    shape = RoundedCornerShape(8.dp),
                                    color = if (customMarkerType != null) {
                                        customMarkerType.color.copy(alpha = 0.2f)
                                    } else {
                                        MaterialTheme.colorScheme.errorContainer.copy(alpha = 0.3f)
                                    },
                                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.3f))
                                ) {
                                    Column(
                                        modifier = Modifier.padding(12.dp)
                                    ) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            modifier = Modifier.fillMaxWidth()
                                        ) {
                                            if (customMarkerType != null) {
                                                Box(
                                                    modifier = Modifier
                                                        .size(28.dp)
                                                        .background(customMarkerType.color, RoundedCornerShape(6.dp)),
                                                    contentAlignment = Alignment.Center
                                                ) {
                                                    Text(
                                                        text = customMarkerType.icon,
                                                        fontSize = 16.sp
                                                    )
                                                }
                                            } else {
                                                Icon(
                                                    imageVector = Icons.Default.Warning,
                                                    contentDescription = null,
                                                    tint = MaterialTheme.colorScheme.error,
                                                    modifier = Modifier.size(20.dp)
                                                )
                                            }
                                            
                                            Spacer(modifier = Modifier.width(12.dp))
                                            
                                            Text(
                                                text = if (customMarkerType != null) {
                                                    customMarkerType.name
                                                } else {
                                                    when (selectedLanguage) {
                                                        "German" -> "Ich fühle mich schlecht"
                                                        "Spanish" -> "Me siento mal"
                                                        else -> "I feel bad"
                                                    }
                                                },
                                                style = MaterialTheme.typography.bodyMedium,
                                                modifier = Modifier.weight(1f)
                                            )
                                            
                                            // Delete button - only this triggers delete confirmation
                                            IconButton(
                                                onClick = {
                                                    markerToDelete = marker
                                                    showDeleteConfirmation = true
                                                },
                                                modifier = Modifier.size(24.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Close,
                                                    contentDescription = "Remove",
                                                    tint = MaterialTheme.colorScheme.error.copy(alpha = 0.8f),
                                                    modifier = Modifier.size(18.dp)
                                                )
                                            }
                                        }
                                        
                                        // Show marker details (symptoms, notes) for "I feel bad" markers
                                        if (!markerDetails.isNullOrBlank()) {
                                            Spacer(modifier = Modifier.height(8.dp))
                                            Text(
                                                text = markerDetails,
                                                style = MaterialTheme.typography.bodySmall,
                                                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
                                                lineHeight = 18.sp
                                            )
                                        }
                                    }
                                }
                            }
                            
                            Spacer(modifier = Modifier.height(8.dp))
                        }
                        
                        // Add marker button
                        OutlinedButton(
                            onClick = { showAddMarkerMenu = !showAddMarkerMenu },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(8.dp)
                        ) {
                            Icon(
                                imageVector = if (showAddMarkerMenu) Icons.Default.KeyboardArrowUp else Icons.Default.Add,
                                contentDescription = null,
                                modifier = Modifier.size(20.dp)
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Text(
                                text = when (selectedLanguage) {
                                    "German" -> "Marker hinzufügen"
                                    "Spanish" -> "Agregar marcador"
                                    else -> "Add Marker"
                                }
                            )
                        }
                        
                        // Expanded marker selection menu
                        if (showAddMarkerMenu) {
                            // "I feel bad" option
                            val isFeelBadApplied = appliedMarkers.any { it.type == "feel_bad" }
                            
                            Surface(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable(enabled = !isFeelBadApplied) {
                                        showMarkerMenu = false
                                        showAddMarkerMenu = false
                                        showFeelBadDialog = true
                                    },
                                shape = RoundedCornerShape(8.dp),
                                color = if (isFeelBadApplied) {
                                    MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f)
                                } else {
                                    MaterialTheme.colorScheme.errorContainer.copy(alpha = 0.3f)
                                }
                            ) {
                                Row(
                                    modifier = Modifier.padding(12.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Warning,
                                        contentDescription = "I feel bad",
                                        tint = if (isFeelBadApplied) {
                                            MaterialTheme.colorScheme.onSurface.copy(alpha = 0.4f)
                                        } else {
                                            MaterialTheme.colorScheme.error
                                        },
                                        modifier = Modifier.size(20.dp)
                                    )
                                    Spacer(modifier = Modifier.width(12.dp))
                                    Text(
                                        text = when (selectedLanguage) {
                                            "German" -> "Ich fühle mich schlecht"
                                            "Spanish" -> "Me siento mal"
                                            else -> "I feel bad"
                                        },
                                        style = MaterialTheme.typography.bodyMedium,
                                        color = if (isFeelBadApplied) {
                                            MaterialTheme.colorScheme.onSurface.copy(alpha = 0.4f)
                                        } else {
                                            MaterialTheme.colorScheme.onSurface
                                        },
                                        modifier = Modifier.weight(1f)
                                    )
                                    
                                    // Show checkmark if already applied
                                    if (isFeelBadApplied) {
                                        Icon(
                                            imageVector = Icons.Default.Check,
                                            contentDescription = "Applied",
                                            tint = MaterialTheme.colorScheme.primary,
                                            modifier = Modifier.size(20.dp)
                                        )
                                    }
                                }
                            }
                            
                            // Custom markers
                            if (customMarkers.isNotEmpty()) {
                                for (markerType in customMarkers) {
                                    // Check if this marker is already applied
                                    val isAlreadyApplied = appliedMarkers.any { 
                                        it.type == "custom" && it.customMarkerTypeId == markerType.id 
                                    }
                                    
                                    Surface(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .clickable(enabled = !isAlreadyApplied) {
                                                // Apply custom marker to entry (only if not already applied)
                                                if (currentEntry != null && onEntryUpdate != null && !isAlreadyApplied) {
                                                    val newMarker = if (markerCellId != null) {
                                                        // Cell-specific marker (date, remark, custom columns)
                                                        Marker(
                                                            id = UUID.randomUUID().toString(),
                                                            type = "custom",
                                                            startTime = "cell_specific",
                                                            customMarkerTypeId = markerType.id,
                                                            timestamp = System.currentTimeMillis(),
                                                            cellId = markerCellId
                                                        )
                                                    } else if (timeOfDay != null) {
                                                        // Time-based marker (blood sugar cells)
                                                        Marker(
                                                            id = UUID.randomUUID().toString(),
                                                            type = "custom",
                                                            startTime = timeOfDay,
                                                            customMarkerTypeId = markerType.id,
                                                            timestamp = System.currentTimeMillis()
                                                        )
                                                    } else {
                                                        null
                                                    }
                                                    
                                                    if (newMarker != null) {
                                                        val updatedMarkers = currentEntry.markers + newMarker
                                                        onEntryUpdate(currentEntry.copy(markers = updatedMarkers))
                                                    }
                                                }
                                                // Keep dialog open to allow adding multiple markers
                                            },
                                        shape = RoundedCornerShape(8.dp),
                                        color = if (isAlreadyApplied) {
                                            MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f)
                                        } else {
                                            markerType.color.copy(alpha = 0.2f)
                                        }
                                    ) {
                                        Row(
                                            modifier = Modifier.padding(12.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Box(
                                                modifier = Modifier
                                                    .size(28.dp)
                                                    .background(markerType.color, RoundedCornerShape(6.dp)),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Text(
                                                    text = markerType.icon,
                                                    fontSize = 16.sp
                                                )
                                            }
                                            
                                            Spacer(modifier = Modifier.width(12.dp))
                                            
                                            Column(modifier = Modifier.weight(1f)) {
                                                Text(
                                                    text = markerType.name,
                                                    style = MaterialTheme.typography.bodyMedium,
                                                    fontWeight = FontWeight.Medium,
                                                    color = if (isAlreadyApplied) {
                                                        MaterialTheme.colorScheme.onSurface.copy(alpha = 0.4f)
                                                    } else {
                                                        MaterialTheme.colorScheme.onSurface
                                                    }
                                                )
                                                if (markerType.description.isNotEmpty()) {
                                                    Text(
                                                        text = markerType.description,
                                                        style = MaterialTheme.typography.bodySmall,
                                                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                                                        maxLines = 1,
                                                        overflow = TextOverflow.Ellipsis
                                                    )
                                                }
                                            }
                                            
                                            // Edit icon - opens edit dialog for this marker type
                                            IconButton(
                                                onClick = {
                                                    // Create a temporary marker to edit the marker type
                                                    val tempMarker = Marker(
                                                        id = UUID.randomUUID().toString(),
                                                        type = "custom",
                                                        startTime = "cell_specific",
                                                        customMarkerTypeId = markerType.id,
                                                        timestamp = System.currentTimeMillis()
                                                    )
                                                    markerToEdit = tempMarker
                                                    showEditMarkerDialog = true
                                                },
                                                modifier = Modifier.size(32.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Edit,
                                                    contentDescription = "Edit marker",
                                                    tint = MaterialTheme.colorScheme.primary.copy(alpha = 0.7f),
                                                    modifier = Modifier.size(18.dp)
                                                )
                                            }
                                            
                                            // Delete icon - deletes this marker type
                                            IconButton(
                                                onClick = {
                                                    CustomMarkerManager.deleteCustomMarker(context, markerType.id)
                                                    val updatedMarkers = customMarkers.filter { it.id != markerType.id }
                                                    onCustomMarkersUpdate?.invoke(updatedMarkers)
                                                },
                                                modifier = Modifier.size(32.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Close,
                                                    contentDescription = "Delete marker",
                                                    tint = MaterialTheme.colorScheme.error.copy(alpha = 0.7f),
                                                    modifier = Modifier.size(18.dp)
                                                )
                                            }
                                            
                                            // Show checkmark if already applied
                                            if (isAlreadyApplied) {
                                                Icon(
                                                    imageVector = Icons.Default.Check,
                                                    contentDescription = "Applied",
                                                    tint = MaterialTheme.colorScheme.primary,
                                                    modifier = Modifier.size(20.dp)
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                            
                            // Create new marker button
                            OutlinedButton(
                                onClick = {
                                    showMarkerMenu = false
                                    showAddMarkerMenu = false
                                    showCreateMarkerDialog = true
                                },
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(8.dp),
                                colors = ButtonDefaults.outlinedButtonColors(
                                    contentColor = MaterialTheme.colorScheme.primary
                                )
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Add,
                                    contentDescription = null,
                                    modifier = Modifier.size(20.dp)
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(
                                    text = when (selectedLanguage) {
                                        "German" -> "Neuen Marker erstellen"
                                        "Spanish" -> "Crear nuevo marcador"
                                        else -> "Create New Marker"
                                    }
                                )
                            }
                        }
                        
                        Spacer(modifier = Modifier.height(8.dp))
                        
                        Button(
                            onClick = { showMarkerMenu = false },
                            modifier = Modifier.align(Alignment.End)
                        ) {
                            Text(
                                text = when (selectedLanguage) {
                                    "German" -> "OK"
                                    "Spanish" -> "OK"
                                    else -> "OK"
                                }
                            )
                        }
                    }
                }
            }
        }
        
        // Delete confirmation dialog
        if (showDeleteConfirmation && markerToDelete != null) {
            val markerName = if (markerToDelete!!.type == "feel_bad") {
                when (selectedLanguage) {
                    "German" -> "Ich fühle mich schlecht"
                    "Spanish" -> "Me siento mal"
                    else -> "I feel bad"
                }
            } else {
                customMarkers.find { it.id == markerToDelete!!.customMarkerTypeId }?.name ?: "Marker"
            }
            
            AlertDialog(
                onDismissRequest = { 
                    showDeleteConfirmation = false
                    markerToDelete = null
                },
                title = {
                    Text(
                        text = when (selectedLanguage) {
                            "German" -> "Marker löschen?"
                            "Spanish" -> "¿Eliminar marcador?"
                            else -> "Delete marker?"
                        }
                    )
                },
                text = {
                    Text(
                        text = when (selectedLanguage) {
                            "German" -> "Möchten Sie \"$markerName\" wirklich löschen?"
                            "Spanish" -> "¿Está seguro de que desea eliminar \"$markerName\"?"
                            else -> "Are you sure you want to delete \"$markerName\"?"
                        }
                    )
                },
                confirmButton = {
                    Button(
                        onClick = {
                            if (currentEntry != null && onEntryUpdate != null && markerToDelete != null) {
                                val updatedMarkers = currentEntry.markers.filter { it.id != markerToDelete!!.id }
                                onEntryUpdate(currentEntry.copy(markers = updatedMarkers))
                            }
                            showDeleteConfirmation = false
                            markerToDelete = null
                        },
                        colors = ButtonDefaults.buttonColors(
                            containerColor = MaterialTheme.colorScheme.error
                        )
                    ) {
                        Text(
                            text = when (selectedLanguage) {
                                "German" -> "Löschen"
                                "Spanish" -> "Eliminar"
                                else -> "Delete"
                            }
                        )
                    }
                },
                dismissButton = {
                    OutlinedButton(
                        onClick = {
                            showDeleteConfirmation = false
                            markerToDelete = null
                        }
                    ) {
                        Text(
                            text = when (selectedLanguage) {
                                "German" -> "Abbrechen"
                                "Spanish" -> "Cancelar"
                                else -> "Cancel"
                            }
                        )
                    }
                }
            )
        }
        
        // Edit marker dialog
        if (showEditMarkerDialog && markerToEdit != null) {
            val isFeelBadMarker = markerToEdit!!.type == "feel_bad"
            val customMarkerType = if (!isFeelBadMarker && markerToEdit!!.customMarkerTypeId != null) {
                customMarkers.find { it.id == markerToEdit!!.customMarkerTypeId }
            } else null
            
            if (isFeelBadMarker) {
                // Edit "I feel bad" marker - use similar dialog to creation
                var editStep by remember { mutableStateOf(1) }
                var editSelectedTimeOfDay by remember { mutableStateOf(markerToEdit!!.startTime) }
                var editSelectedReasons by remember { mutableStateOf(markerToEdit!!.reasons.toSet()) }
                var editCustomNote by remember { mutableStateOf(markerToEdit!!.customNote) }
                var editShowPresetSymptoms by remember { mutableStateOf(false) }
                
                // Time options with icons
                val timeOptions = listOf(
                    Triple("morning", "🌅", when (selectedLanguage) {
                        "German" -> "Morgens"
                        "Spanish" -> "Mañana"
                        else -> "Morning"
                    }),
                    Triple("afternoon", "☀️", when (selectedLanguage) {
                        "German" -> "Nachmittags"
                        "Spanish" -> "Tarde"
                        else -> "Afternoon"
                    }),
                    Triple("evening", "🌆", when (selectedLanguage) {
                        "German" -> "Abends"
                        "Spanish" -> "Noche"
                        else -> "Evening"
                    }),
                    Triple("night", "🌙", when (selectedLanguage) {
                        "German" -> "Nachts"
                        "Spanish" -> "Noche tarde"
                        else -> "Night"
                    }),
                    Triple("all_day", "📅", when (selectedLanguage) {
                        "German" -> "Ganzer Tag"
                        "Spanish" -> "Todo el día"
                        else -> "All day"
                    })
                )
                
                // Preset symptoms with emojis
                val presetSymptoms = listOf(
                    "🤕" to when (selectedLanguage) { "German" -> "Kopfschmerzen"; "Spanish" -> "Dolor de cabeza"; else -> "Headache" },
                    "🤢" to when (selectedLanguage) { "German" -> "Übelkeit"; "Spanish" -> "Náuseas"; else -> "Nausea" },
                    "😵" to when (selectedLanguage) { "German" -> "Schwindel"; "Spanish" -> "Mareo"; else -> "Dizziness" },
                    "😴" to when (selectedLanguage) { "German" -> "Müdigkeit"; "Spanish" -> "Fatiga"; else -> "Fatigue" },
                    "🫨" to when (selectedLanguage) { "German" -> "Zittern"; "Spanish" -> "Temblores"; else -> "Shaking" },
                    "💦" to when (selectedLanguage) { "German" -> "Schwitzen"; "Spanish" -> "Sudoración"; else -> "Sweating" },
                    "😵‍💫" to when (selectedLanguage) { "German" -> "Verwirrung"; "Spanish" -> "Confusión"; else -> "Confusion" },
                    "👁️" to when (selectedLanguage) { "German" -> "Verschwommenes Sehen"; "Spanish" -> "Visión borrosa"; else -> "Blurred vision" },
                    "🍽️" to when (selectedLanguage) { "German" -> "Hunger"; "Spanish" -> "Hambre"; else -> "Hunger" },
                    "😤" to when (selectedLanguage) { "German" -> "Reizbarkeit"; "Spanish" -> "Irritabilidad"; else -> "Irritability" },
                    "💓" to when (selectedLanguage) { "German" -> "Herzrasen"; "Spanish" -> "Corazón acelerado"; else -> "Heart racing" },
                    "😰" to when (selectedLanguage) { "German" -> "Angst"; "Spanish" -> "Ansiedad"; else -> "Anxiety" }
                )
                
                Dialog(onDismissRequest = { 
                    showEditMarkerDialog = false
                    markerToEdit = null
                }) {
                    Surface(
                        shape = RoundedCornerShape(24.dp),
                        color = MaterialTheme.colorScheme.surface,
                        tonalElevation = 6.dp,
                        modifier = Modifier
                            .width(320.dp)
                            .padding(16.dp)
                    ) {
                        // Use Crossfade instead of AnimatedContent to prevent layout instability
                        Crossfade(
                            targetState = editStep,
                            animationSpec = tween(200),
                            label = "editStepTransition"
