                                    // Second row: Evening, Night
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                                    ) {
                                        timeOptions.drop(2).take(2).forEach { (key, icon, label) ->
                                            Surface(
                                                onClick = { selectedTimeOfDay = key },
                                                modifier = Modifier
                                                    .weight(1f)
                                                    .height(72.dp),
                                                shape = RoundedCornerShape(16.dp),
                                                color = if (selectedTimeOfDay == key)
                                                    MaterialTheme.colorScheme.primaryContainer
                                                else
                                                    MaterialTheme.colorScheme.surfaceVariant,
                                                border = if (selectedTimeOfDay == key)
                                                    BorderStroke(2.dp, MaterialTheme.colorScheme.primary)
                                                else
                                                    null
                                            ) {
                                                Column(
                                                    modifier = Modifier.fillMaxSize(),
                                                    horizontalAlignment = Alignment.CenterHorizontally,
                                                    verticalArrangement = Arrangement.Center
                                                ) {
                                                    Text(text = icon, fontSize = 24.sp)
                                                    Spacer(modifier = Modifier.height(4.dp))
                                                    Text(
                                                        text = label,
                                                        style = MaterialTheme.typography.bodyMedium,
                                                        fontWeight = if (selectedTimeOfDay == key) FontWeight.Bold else FontWeight.Normal,
                                                        color = if (selectedTimeOfDay == key)
                                                            MaterialTheme.colorScheme.onPrimaryContainer
                                                        else
                                                            MaterialTheme.colorScheme.onSurfaceVariant
                                                    )
                                                }
                                            }
                                        }
                                    }
                                    
                                    // Third row: All day (full width)
                                    val allDayOption = timeOptions.last()
                                    Surface(
                                        onClick = { selectedTimeOfDay = allDayOption.first },
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .height(56.dp),
                                        shape = RoundedCornerShape(16.dp),
                                        color = if (selectedTimeOfDay == allDayOption.first)
                                            MaterialTheme.colorScheme.primaryContainer
                                        else
                                            MaterialTheme.colorScheme.surfaceVariant,
                                        border = if (selectedTimeOfDay == allDayOption.first)
                                            BorderStroke(2.dp, MaterialTheme.colorScheme.primary)
                                        else
                                            null
                                    ) {
                                        Row(
                                            modifier = Modifier.fillMaxSize(),
                                            horizontalArrangement = Arrangement.Center,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(text = allDayOption.second, fontSize = 24.sp)
                                            Spacer(modifier = Modifier.width(12.dp))
                                            Text(
                                                text = allDayOption.third,
                                                style = MaterialTheme.typography.bodyLarge,
                                                fontWeight = if (selectedTimeOfDay == allDayOption.first) FontWeight.Bold else FontWeight.Normal,
                                                color = if (selectedTimeOfDay == allDayOption.first)
                                                    MaterialTheme.colorScheme.onPrimaryContainer
                                                else
                                                    MaterialTheme.colorScheme.onSurfaceVariant
                                            )
                                        }
                                    }
                                }
                                
                                Spacer(modifier = Modifier.height(8.dp))
                                
                                // Action buttons
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    OutlinedButton(
                                        onClick = { showFeelBadDialog = false },
                                        modifier = Modifier.weight(1f),
                                        shape = RoundedCornerShape(12.dp)
                                    ) {
                                        Text(when (selectedLanguage) {
                                            "German" -> "Abbrechen"
                                            "Spanish" -> "Cancelar"
                                            else -> "Cancel"
                                        })
                                    }
                                    
                                    Button(
                                        onClick = { currentStep = 2 },
                                        modifier = Modifier.weight(1f),
                                        enabled = selectedTimeOfDay != null,
                                        shape = RoundedCornerShape(12.dp)
                                    ) {
                                        Text(when (selectedLanguage) {
                                            "German" -> "Weiter"
                                            "Spanish" -> "Siguiente"
                                            else -> "Next"
                                        })
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Icon(
                                            imageVector = Icons.Default.ArrowForward,
                                            contentDescription = null,
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }
                                }
                            }
                            
                            // STEP 2: Symptoms Selection
                            2 -> Column(
                                modifier = Modifier.padding(24.dp),
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.spacedBy(16.dp)
                            ) {
                                // Header
                                Text(
                                    text = when (selectedLanguage) {
                                        "German" -> "Was fühlst du?"
                                        "Spanish" -> "¿Qué sientes?"
                                        else -> "What do you feel?"
                                    },
                                    style = MaterialTheme.typography.titleLarge,
                                    textAlign = TextAlign.Center,
                                    fontWeight = FontWeight.Medium
                                )
                                
                                // Custom note input (primary)
                                OutlinedTextField(
                                    value = customNote,
                                    onValueChange = { customNote = it },
                                    modifier = Modifier.fillMaxWidth(),
                                    placeholder = {
                                        Text(when (selectedLanguage) {
                                            "German" -> "Beschreibe wie du dich fühlst..."
                                            "Spanish" -> "Describe cómo te sientes..."
                                            else -> "Describe how you feel..."
                                        })
                                    },
                                    minLines = 2,
                                    maxLines = 4,
                                    shape = RoundedCornerShape(12.dp)
                                )
                                
                                // Expandable preset symptoms
                                Surface(
                                    onClick = { showPresetSymptoms = !showPresetSymptoms },
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(12.dp),
                                    color = MaterialTheme.colorScheme.surfaceVariant
                                ) {
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(16.dp),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.List,
                                                contentDescription = null,
                                                tint = MaterialTheme.colorScheme.primary
                                            )
                                            Column {
                                                Text(
                                                    text = when (selectedLanguage) {
                                                        "German" -> "Häufige Symptome"
                                                        "Spanish" -> "Síntomas comunes"
                                                        else -> "Common symptoms"
                                                    },
                                                    style = MaterialTheme.typography.bodyLarge,
                                                    fontWeight = FontWeight.Medium
                                                )
                                                if (selectedReasons.isNotEmpty()) {
                                                    Text(
                                                        text = "${selectedReasons.size} " + when (selectedLanguage) {
                                                            "German" -> "ausgewählt"
                                                            "Spanish" -> "seleccionados"
                                                            else -> "selected"
                                                        },
                                                        style = MaterialTheme.typography.bodySmall,
                                                        color = MaterialTheme.colorScheme.primary
                                                    )
                                                }
                                            }
                                        }
                                        Icon(
                                            imageVector = if (showPresetSymptoms) 
                                                Icons.Default.KeyboardArrowUp 
                                            else 
                                                Icons.Default.KeyboardArrowDown,
                                            contentDescription = null
                                        )
                                    }
                                }
                                
                                // Expandable symptom list
                                AnimatedVisibility(
                                    visible = showPresetSymptoms,
                                    enter = expandVertically() + fadeIn(),
                                    exit = shrinkVertically() + fadeOut()
                                ) {
                                    Surface(
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(12.dp),
                                        color = MaterialTheme.colorScheme.surface,
                                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant)
                                    ) {
                                        Column(
                                            modifier = Modifier
                                                .heightIn(max = 200.dp)
                                                .verticalScroll(rememberScrollState())
                                                .padding(8.dp),
                                            verticalArrangement = Arrangement.spacedBy(4.dp)
                                        ) {
                                            symptomPresets.forEach { (key, label) ->
                                                val isSelected = selectedReasons.contains(key)
                                                Surface(
                                                    onClick = {
                                                        selectedReasons = if (isSelected) {
                                                            selectedReasons - key
                                                        } else {
                                                            selectedReasons + key
                                                        }
                                                    },
                                                    modifier = Modifier.fillMaxWidth(),
                                                    shape = RoundedCornerShape(8.dp),
                                                    color = if (isSelected)
                                                        MaterialTheme.colorScheme.primaryContainer
                                                    else
                                                        Color.Transparent
                                                ) {
                                                    Row(
                                                        modifier = Modifier
                                                            .fillMaxWidth()
                                                            .padding(horizontal = 12.dp, vertical = 10.dp),
                                                        horizontalArrangement = Arrangement.SpaceBetween,
                                                        verticalAlignment = Alignment.CenterVertically
                                                    ) {
                                                        Text(
                                                            text = label,
                                                            style = MaterialTheme.typography.bodyMedium,
                                                            color = if (isSelected)
                                                                MaterialTheme.colorScheme.onPrimaryContainer
                                                            else
                                                                MaterialTheme.colorScheme.onSurface
                                                        )
                                                        if (isSelected) {
                                                            Icon(
                                                                imageVector = Icons.Default.Check,
                                                                contentDescription = null,
                                                                tint = MaterialTheme.colorScheme.primary,
                                                                modifier = Modifier.size(20.dp)
                                                            )
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                                
                                Spacer(modifier = Modifier.height(8.dp))
                                
                                // Action buttons
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    OutlinedButton(
                                        onClick = { currentStep = 1 },
                                        modifier = Modifier.weight(1f),
                                        shape = RoundedCornerShape(12.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.ArrowBack,
                                            contentDescription = null,
                                            modifier = Modifier.size(18.dp)
                                        )
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Text(when (selectedLanguage) {
                                            "German" -> "Zurück"
                                            "Spanish" -> "Atrás"
                                            else -> "Back"
                                        })
                                    }
                                    
                                    Button(
                                        onClick = {
                                            if (selectedTimeOfDay != null && currentEntry != null && onEntryUpdate != null) {
                                                // Create new marker
                                                val newMarker = if (isDateCell) {
                                                    // Date cell marker - always use all_day
                                                    Marker(
                                                        id = UUID.randomUUID().toString(),
                                                        type = "feel_bad",
                                                        startTime = "all_day",
                                                        reasons = selectedReasons.toList(),
                                                        customNote = customNote.trim(),
                                                        timestamp = System.currentTimeMillis(),
                                                        cellId = "date"
                                                    )
                                                } else if (markerCellId != null) {
                                                    // Cell-specific marker (remark, custom columns)
                                                    Marker(
                                                        id = UUID.randomUUID().toString(),
                                                        type = "feel_bad",
                                                        startTime = "cell_specific",
                                                        reasons = selectedReasons.toList(),
                                                        customNote = customNote.trim(),
                                                        timestamp = System.currentTimeMillis(),
                                                        cellId = markerCellId
                                                    )
                                                } else if (timeOfDay != null && selectedTimeOfDay == "all_day") {
                                                    // All day marker from blood sugar cell - use "all_day" as startTime
                                                    Marker(
                                                        id = UUID.randomUUID().toString(),
                                                        type = "feel_bad",
                                                        startTime = "all_day",
                                                        reasons = selectedReasons.toList(),
                                                        customNote = customNote.trim(),
                                                        timestamp = System.currentTimeMillis()
                                                    )
                                                } else {
                                                    // Time-specific marker
                                                    Marker(
                                                        id = UUID.randomUUID().toString(),
                                                        type = "feel_bad",
                                                        startTime = selectedTimeOfDay!!,
                                                        reasons = selectedReasons.toList(),
                                                        customNote = customNote.trim(),
                                                        timestamp = System.currentTimeMillis()
                                                    )
                                                }
                                                
                                                val updatedEntry = currentEntry.copy(
                                                    markers = currentEntry.markers + newMarker
                                                )
                                                onEntryUpdate(updatedEntry)
                                                showFeelBadDialog = false
                                            }
                                        },
                                        modifier = Modifier.weight(1f),
                                        enabled = selectedTimeOfDay != null && currentEntry != null && onEntryUpdate != null,
                                        shape = RoundedCornerShape(12.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Check,
                                            contentDescription = null,
                                            modifier = Modifier.size(18.dp)
                                        )
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Text(when (selectedLanguage) {
                                            "German" -> "Speichern"
                                            "Spanish" -> "Guardar"
                                            else -> "Save"
                                        })
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        
        // Marker info snackbar - shown on long press of cell with marker
        if (showMarkerSnackbar && currentEntry != null) {
            // Get markers for this cell
            val relevantMarkers = if (isDateCell) {
                currentEntry.markers.filter { it.startTime == "all_day" }
            } else if (timeOfDay != null) {
                currentEntry.markers.filter { it.startTime == timeOfDay }
            } else {
                emptyList()
            }
            
            if (relevantMarkers.isNotEmpty()) {
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(16.dp),
                    contentAlignment = Alignment.BottomCenter
                ) {
                    Surface(
                        shape = RoundedCornerShape(8.dp),
                        color = MaterialTheme.colorScheme.inverseSurface,
                        tonalElevation = 6.dp,
                        shadowElevation = 6.dp,
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { showMarkerSnackbar = false }
                    ) {
                        Row(
                            modifier = Modifier
                                .padding(16.dp)
                                .fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Column(
                                modifier = Modifier.weight(1f)
                            ) {
                                relevantMarkers.forEach { marker ->
                                    // Get custom marker type if this is a custom marker
                                    val customMarkerType = if (marker.type == "custom" && marker.customMarkerTypeId != null) {
                                        customMarkers.find { it.id == marker.customMarkerTypeId }
                                    } else null
                                    
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        modifier = Modifier.padding(bottom = 4.dp)
                                    ) {
                                        // Display icon based on marker type
                                        if (customMarkerType != null) {
                                            // Custom marker: show emoji with colored background
                                            Box(
                                                modifier = Modifier
                                                    .size(28.dp)
                                                    .background(customMarkerType.color, RoundedCornerShape(4.dp))
                                                    .padding(end = 8.dp),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Text(
                                                    text = customMarkerType.icon,
                                                    fontSize = 16.sp
                                                )
                                            }
                                        } else {
                                            // Feel bad marker: show warning icon
                                            Icon(
                                                imageVector = Icons.Default.Warning,
                                                contentDescription = null,
                                                tint = Color(0xFFFF9800),
                                                modifier = Modifier.size(20.dp).padding(end = 8.dp)
                                            )
                                        }
                                        Column {
                                            Text(
                                                text = if (customMarkerType != null) {
                                                    customMarkerType.name
                                                } else {
                                                    when (selectedLanguage) {
                                                        "German" -> "Ich fühle mich schlecht"
                                                        "Spanish" -> "Me siento mal"
                                                        else -> "I feel bad"
                                                    }
                                                },
                                                color = MaterialTheme.colorScheme.inverseOnSurface,
                                                style = MaterialTheme.typography.bodyMedium,
                                                fontWeight = FontWeight.Bold
                                            )
                                            // Show custom marker description if available
                                            if (customMarkerType != null && customMarkerType.description.isNotEmpty()) {
                                                Text(
                                                    text = customMarkerType.description,
                                                    color = MaterialTheme.colorScheme.inverseOnSurface.copy(alpha = 0.7f),
                                                    style = MaterialTheme.typography.bodySmall
                                                )
                                            }
                                            if (marker.reasons.isNotEmpty()) {
                                                // Translate reason keys to localized text
                                                val localizedReasons = marker.reasons.map { reason ->
                                                    when (reason) {
                                                        "headache" -> when (selectedLanguage) {
                                                            "German" -> "Kopfschmerzen"
                                                            "Spanish" -> "Dolor de cabeza"
                                                            else -> "Headache"
                                                        }
                                                        "nausea" -> when (selectedLanguage) {
                                                            "German" -> "Übelkeit"
                                                            "Spanish" -> "Náuseas"
                                                            else -> "Nausea"
                                                        }
                                                        "dizziness" -> when (selectedLanguage) {
                                                            "German" -> "Schwindel"
                                                            "Spanish" -> "Mareos"
                                                            else -> "Dizziness"
                                                        }
                                                        "fatigue" -> when (selectedLanguage) {
                                                            "German" -> "Müdigkeit"
                                                            "Spanish" -> "Fatiga"
                                                            else -> "Fatigue"
                                                        }
                                                        "shaking" -> when (selectedLanguage) {
                                                            "German" -> "Zittern"
                                                            "Spanish" -> "Temblores"
                                                            else -> "Shaking"
                                                        }
                                                        "sweating" -> when (selectedLanguage) {
                                                            "German" -> "Schwitzen"
                                                            "Spanish" -> "Sudoración"
                                                            else -> "Sweating"
                                                        }
                                                        "confusion" -> when (selectedLanguage) {
                                                            "German" -> "Verwirrung"
                                                            "Spanish" -> "Confusión"
                                                            else -> "Confusion"
                                                        }
                                                        "blurred_vision" -> when (selectedLanguage) {
                                                            "German" -> "Verschwommenes Sehen"
                                                            "Spanish" -> "Visión borrosa"
                                                            else -> "Blurred vision"
                                                        }
                                                        "hunger" -> when (selectedLanguage) {
                                                            "German" -> "Hunger"
                                                            "Spanish" -> "Hambre"
                                                            else -> "Hunger"
                                                        }
                                                        "irritability" -> when (selectedLanguage) {
                                                            "German" -> "Reizbarkeit"
                                                            "Spanish" -> "Irritabilidad"
                                                            else -> "Irritability"
                                                        }
                                                        else -> reason // Fallback to key if unknown
                                                    }
                                                }
                                                Text(
                                                    text = localizedReasons.joinToString(", "),
                                                    color = MaterialTheme.colorScheme.inverseOnSurface.copy(alpha = 0.7f),
                                                    style = MaterialTheme.typography.bodySmall
                                                )
                                            }
                                            if (marker.customNote.isNotBlank()) {
                                                Text(
                                                    text = marker.customNote,
                                                    color = MaterialTheme.colorScheme.inverseOnSurface.copy(alpha = 0.7f),
                                                    style = MaterialTheme.typography.bodySmall,
                                                    fontStyle = androidx.compose.ui.text.font.FontStyle.Italic
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                            
                            // Add new marker button
                            IconButton(
                                onClick = {
                                    showMarkerSnackbar = false
                                    if (isDateCell) {
                                        showMarkerMenu = true
                                    } else {
                                        showFeelBadDialog = true
                                    }
                                }
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Add,
                                    contentDescription = "Add marker",
                                    tint = MaterialTheme.colorScheme.inverseOnSurface
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun CommentCell(
    value: String,
    onValueChange: (String) -> Unit,
    modifier: Modifier = Modifier,
    fontColor: Color,
    gridColor: Color,
    scale: Float = 1f,
    heightScale: Float = 1f
) {
    Surface(
        modifier = modifier
            .padding(horizontal = 2.dp)
            .height((40 * scale * heightScale).dp), // Height affected by both scale and heightScale
        shape = RoundedCornerShape(6.dp),
        color = MaterialTheme.colorScheme.surface.copy(alpha = 0.7f),
        border = BorderStroke(0.5.dp, gridColor.copy(alpha = 0.3f))
    ) {
        Box(
            modifier = Modifier.padding(4.dp),
            contentAlignment = Alignment.Center
        ) {
            BasicTextField(
                value = value,
                onValueChange = onValueChange,
                textStyle = TextStyle(
                    color = fontColor,
                    fontSize = (14 * scale).sp,
                    textAlign = TextAlign.Center
                ),
                singleLine = true,
                keyboardOptions = KeyboardOptions(
                    imeAction = ImeAction.Done
                ),
                modifier = Modifier.fillMaxWidth()
            )
            if (value.isEmpty()) {
                Text(
                    text = "Remarks",
                    color = fontColor.copy(alpha = 0.5f),
                    fontSize = (14 * scale).sp,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.fillMaxWidth()
                )
            }
        }
    }
}

@Composable
fun ColorPickerSection(
    title: String,
    color: Color,
    onColorChange: (Color) -> Unit,
    context: Context = LocalContext.current,
    onDeleteModeChange: (Boolean) -> Unit = {},
    category: String = "general"
) {
    var showCustomDialog by remember { mutableStateOf(false) }
    var presets by remember { mutableStateOf(emptyList<ColorPreset>()) }
    var globalDeleteMode by remember { mutableStateOf(false) }
    
    // Refresh presets when component is first composed or when category changes
    LaunchedEffect(category) {
        presets = PresetManager.getPresetsByCategory(context, category)
    }
    
    // Also refresh presets when the component is first composed (handles backup restore case)
    LaunchedEffect(Unit) {
        presets = PresetManager.getPresetsByCategory(context, category)
    }
    
    // Notify parent about delete mode changes
    LaunchedEffect(globalDeleteMode) {
        onDeleteModeChange(globalDeleteMode)
    }
    
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .heightIn(max = 400.dp)
            .pointerInput(Unit) {
                // Global tap detection for canceling delete mode
                detectTapGestures(
                    onTap = { 
                        if (globalDeleteMode) {
                            globalDeleteMode = false
                        }
                    }
                )
            }
    ) {
        LazyColumn(
            modifier = Modifier
                .fillMaxWidth()
                .padding(vertical = 8.dp)
        ) {
            // Title
            item {
                Text(
                    text = title,
                    style = MaterialTheme.typography.titleMedium,
                    modifier = Modifier.padding(bottom = 8.dp)
                )
            }

            // Color presets section
            if (presets.isNotEmpty()) {
                item {
                    Text(
                        text = "Saved Presets",
                        style = MaterialTheme.typography.bodyMedium,
                        modifier = Modifier.padding(bottom = 4.dp)
                    )
                }
                
                item {
                    val lazyRowState = rememberLazyListState()
                    
                    // Auto-scroll to show newly added presets
                    LaunchedEffect(presets.size) {
                        if (presets.isNotEmpty()) {
                            lazyRowState.animateScrollToItem(presets.size - 1)
                        }
                    }
                    
                    LazyRow(
                        state = lazyRowState,
                        horizontalArrangement = Arrangement.spacedBy(4.dp),
                        modifier = Modifier.padding(bottom = 8.dp)
                    ) {
                        items(
                            items = presets,
                            key = { it.id }
                        ) { preset ->
                            var isShaking by remember { mutableStateOf(false) }
                            
                            // Shake animation - triggered by global delete mode
                            LaunchedEffect(globalDeleteMode) {
                                isShaking = globalDeleteMode
                            }
                            
                            val shakeOffset by animateFloatAsState(
                                targetValue = if (globalDeleteMode) 2f else 0f,
                                animationSpec = if (globalDeleteMode) {
                                    infiniteRepeatable(
                                        animation = tween(50, easing = LinearEasing),
                                        repeatMode = RepeatMode.Reverse
                                    )
                                } else {
                                    tween(100)
                                },
                                label = "shake"
                            )
                            
                            Column(
                                horizontalAlignment = Alignment.CenterHorizontally,
                                modifier = Modifier
                                    .width(50.dp)
                                    .offset(x = shakeOffset.dp)
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(36.dp)
                                        .background(
                                            color = preset.color,
                                            shape = RoundedCornerShape(4.dp)
                                        )
                                        .border(
                                            width = 2.dp,
                                            color = if (color == preset.color) MaterialTheme.colorScheme.primary else Color.Transparent,
                                            shape = RoundedCornerShape(4.dp)
                                        )
                                        .pointerInput(Unit) {
                                            detectTapGestures(
                                                onTap = { 
                                                    if (!globalDeleteMode) {
                                                        onColorChange(preset.color) 
                                                    }
                                                },
                                                onLongPress = {
                                                    globalDeleteMode = true
                                                }
                                            )
                                        }
                                ) {
                                    // Delete button - show for all presets when in delete mode
                                    if (globalDeleteMode) {
                                        Box(
                                            modifier = Modifier
                                                .size(16.dp)
                                                .align(Alignment.TopEnd)
                                                .offset(x = (-2).dp, y = 2.dp)
                                                .background(
                                                    Color.Red,
                                                    RoundedCornerShape(50)
                                                )
                                                .clickable {
                                                    PresetManager.deletePreset(context, preset.id)
                                                    presets = PresetManager.getPresetsByCategory(context, category)
                                                    // Keep delete mode active for multiple deletions
                                                    // globalDeleteMode = false
                                                }
                                        ) {
                                            Icon(
                                                imageVector = Icons.Filled.Close,
                                                contentDescription = stringResource(R.string.delete_preset),
                                                tint = Color.White,
                                                modifier = Modifier
                                                    .size(12.dp)
                                                    .align(Alignment.Center)
                                            )
                                        }
                                    }
                                }
                                Text(
                                    text = preset.name,
                                    style = MaterialTheme.typography.bodySmall,
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis,
                                    modifier = Modifier.padding(top = 2.dp)
                                )
                            }
                        }
                    }
                }
            }

            // Standard color palette
            item {
                val colors = listOf(
                    // Reds
                    Color(0xFFF44336), Color(0xFFE91E63), Color(0xFFFF1744), Color(0xFFFF5252),
                    // Purples
                    Color(0xFF9C27B0), Color(0xFF673AB7), Color(0xFF7C4DFF), Color(0xFFD500F9),
                    // Blues
                    Color(0xFF2196F3), Color(0xFF03A9F4), Color(0xFF00BCD4), Color(0xFF448AFF),
                    // Cyans and Teals
                    Color(0xFF00BCD4), Color(0xFF009688), Color(0xFF64FFDA), Color(0xFF1DE9B6),
                    // Greens
                    Color(0xFF4CAF50), Color(0xFF8BC34A), Color(0xFF69F0AE), Color(0xFFB2FF59),
                    // Yellows and Oranges
                    Color(0xFFFFEB3B), Color(0xFFFFC107), Color(0xFFFF9800), Color(0xFFFF6D00),
                    // Browns and Greys
                    Color(0xFF795548), Color(0xFF9E9E9E), Color(0xFF607D8B), Color(0xFF757575),
                    // Black, White and Transparent
                    Color.Black, Color.White, Color.Transparent, Color.DarkGray
                )

                LazyVerticalGrid(
                    columns = GridCells.Fixed(8),
                    horizontalArrangement = Arrangement.spacedBy(4.dp),
                    verticalArrangement = Arrangement.spacedBy(4.dp),
                    modifier = Modifier
                        .fillMaxWidth()
                        .heightIn(min = 200.dp, max = 400.dp)
                ) {
                    items(
                        count = colors.size
                    ) { index ->
                        val colorOption = colors[index]
                        Box(
                            modifier = Modifier
                                .size(36.dp)
                                .background(
                                    color = colorOption,
                                    shape = RoundedCornerShape(4.dp)
                                )
                                .border(
                                    width = 2.dp,
                                    color = if (color == colorOption) MaterialTheme.colorScheme.primary else Color.Transparent,
                                    shape = RoundedCornerShape(4.dp)
                                )
                                .clickable { 
                                    onColorChange(colorOption)
                                }
                        ) {
                            IconButton(
                                onClick = {
                                    PresetManager.savePreset(context, ColorPreset("Custom", colorOption, category = category))
                                    presets = PresetManager.getPresetsByCategory(context, category)
                                },
                                modifier = Modifier
                                    .size(16.dp)
                                    .align(Alignment.TopEnd)
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.Add,
                                    contentDescription = "Save preset",
                                    tint = MaterialTheme.colorScheme.onSurface,
                                    modifier = Modifier.size(12.dp)
                                )
                            }
                        }
                    }
                }
            }
        }
    }

    // Custom Color Dialog
    if (showCustomDialog) {
        var red by remember { mutableFloatStateOf(color.red) }
        var green by remember { mutableFloatStateOf(color.green) }
        var blue by remember { mutableFloatStateOf(color.blue) }
        var alpha by remember { mutableFloatStateOf(color.alpha) }

        Dialog(
            onDismissRequest = { showCustomDialog = false }
        ) {
            Surface(
                modifier = Modifier.padding(16.dp),
                shape = RoundedCornerShape(8.dp),
                color = MaterialTheme.colorScheme.surface
            ) {
                Column(
                    modifier = Modifier.padding(16.dp)
                ) {
                    Text(
                        text = "Custom Color",
                        style = MaterialTheme.typography.titleLarge,
                        modifier = Modifier.padding(bottom = 16.dp)
                    )
                    
                    ColorSlider("Red", red) { red = it }
                    ColorSlider("Green", green) { green = it }
                    ColorSlider("Blue", blue) { blue = it }
                    ColorSlider("Alpha", alpha) { alpha = it }
                    
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(40.dp)
                            .padding(vertical = 8.dp)
                            .background(
                                Color(red, green, blue, alpha),
                                RoundedCornerShape(4.dp)
                            )
                    )

                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(top = 16.dp),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        TextButton(
                            onClick = { showCustomDialog = false },
                            modifier = Modifier.weight(1f)
                        ) {
                            Text("Cancel")
                        }
                        Button(
                            onClick = {
                                val newColor = Color(red, green, blue, alpha)
                                onColorChange(newColor)
                                showCustomDialog = false
                            },
                            modifier = Modifier.weight(1f)
                        ) {
                            Text("Apply")
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun ColorSlider(
    label: String,
    value: Float,
    onValueChange: (Float) -> Unit
) {
    Column(modifier = Modifier.padding(vertical = 4.dp)) {
        Text(
            text = "$label: ${(value * 255).toInt()}",
            style = MaterialTheme.typography.bodyMedium,
            modifier = Modifier.padding(bottom = 4.dp)
        )
        Slider(
            value = value,
            onValueChange = onValueChange,
            valueRange = 0f..1f,
            modifier = Modifier.fillMaxWidth()
        )
    }
}

@Composable
fun FoodTagTooltip(
    text: String,
    visible: Boolean,
    modifier: Modifier = Modifier
) {
    if (visible) {
        Surface(
            modifier = modifier,
            shape = RoundedCornerShape(4.dp),
            color = Color(0xFF4CAF50).copy(alpha = 0.9f), // Bright green color for better visibility
            shadowElevation = 4.dp
        ) {
            Text(
                text = text,
                modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
                style = MaterialTheme.typography.bodySmall
            )
        }
    }
}

enum class BloodSugarTimeFilter {
    ALL_AVERAGE,
    MORNING,
    AFTERNOON,
    EVENING,
    NIGHT
}

enum class InsulinTimeFilter {
    ALL_AVERAGE,
    MORNING,
    AFTERNOON,
    EVENING
}

enum class ChartType {
    BLOOD_SUGAR,
    INSULIN,
    CUSTOM_COLUMN
}

private enum class ChartDateRangePreset {
    ALL,
    LAST_7_DAYS,
    LAST_30_DAYS,
    LAST_90_DAYS,
    CUSTOM
}

private data class ChartDateRangeFilter(
    val preset: ChartDateRangePreset = ChartDateRangePreset.ALL,
    val startDate: LocalDate? = null,
    val endDate: LocalDate? = null,
)

private const val CHART_TRACKER_TAG = "CHART_TRACKER"
private const val CHART_TRACKER_ENABLED = true
private const val CHART_TAP_MIN_BAND_WIDTH_PX = 36f
private const val CHART_MULTI_TOUCH_COMMIT_BLOCK_MS = 250L
private const val CHART_TAP_SLOP_PX = 8f
private const val CHART_VIEWPORT_TAP_SLOP_X = 0.01f
private val CHART_AXIS_DATE_FORMATTER: DateTimeFormatter = DateTimeFormatter.ofPattern("dd.MM.yy")
private const val CHART_AXIS_MIN_VISIBLE_LABELS = 3
private const val CHART_AXIS_MAX_VISIBLE_LABELS = 7

private fun chartTrackerLog(message: String) {
    if (!CHART_TRACKER_ENABLED) return
    Log.d(CHART_TRACKER_TAG, message)
}

private fun resolveChartDateRangeBounds(
    filter: ChartDateRangeFilter,
    minDate: LocalDate,
    maxDate: LocalDate,
): Pair<LocalDate, LocalDate> {
    return when (filter.preset) {
        ChartDateRangePreset.ALL -> minDate to maxDate
        ChartDateRangePreset.LAST_7_DAYS -> maxDate.minusDays(6) to maxDate
        ChartDateRangePreset.LAST_30_DAYS -> maxDate.minusDays(29) to maxDate
        ChartDateRangePreset.LAST_90_DAYS -> maxDate.minusDays(89) to maxDate
        ChartDateRangePreset.CUSTOM -> {
            val start = (filter.startDate ?: minDate)
            val end = (filter.endDate ?: maxDate)
            if (start <= end) start to end else end to start
        }
    }
}

private fun filterEntriesByChartDateRange(
    entries: List<DiabetesEntry>,
    dateFormatter: DateTimeFormatter,
    filter: ChartDateRangeFilter,
): List<DiabetesEntry> {
    val parsedEntries = entries.mapNotNull { entry ->
        val parsedDate = runCatching { LocalDate.parse(entry.date, dateFormatter) }.getOrNull() ?: return@mapNotNull null
        parsedDate to entry
    }
    if (parsedEntries.isEmpty()) return emptyList()

    val minDate = parsedEntries.minOf { it.first }
    val maxDate = parsedEntries.maxOf { it.first }
    val (resolvedStart, resolvedEnd) = resolveChartDateRangeBounds(
        filter = filter,
        minDate = minDate,
        maxDate = maxDate,
    )

    return parsedEntries
        .asSequence()
        .filter { (date, _) -> date in resolvedStart..resolvedEnd }
        .map { it.second }
        .toList()
}

private fun mapChartTapToVisibleIndex(
    tapX: Float,
    chartWidthPx: Float,
    pointCount: Int,
    visibleMinX: Float,
    visibleMaxX: Float,
    snapSpacing: Int = 1,
    chartStartPaddingPx: Float = 56f,
    chartEndPaddingPx: Float = 12f,
    debugSink: ((String) -> Unit)? = null
): Int? {
    if (pointCount <= 0) {
        debugSink?.invoke("pointCount<=0")
        return null
    }

    val effectiveChartWidthPx = (chartWidthPx - chartStartPaddingPx - chartEndPaddingPx).coerceAtLeast(1f)
    val relativeX = tapX - chartStartPaddingPx
    if (relativeX < 0f || relativeX > effectiveChartWidthPx) {
        debugSink?.invoke(
            "outside_plot tapX=$tapX relativeX=$relativeX effectiveWidth=$effectiveChartWidthPx width=$chartWidthPx"
        )
        return null
    }

    val firstVisibleIndex = ceil(visibleMinX.toDouble()).toInt().coerceIn(0, pointCount - 1)
    val lastVisibleIndex = visibleMaxX.toInt().coerceIn(firstVisibleIndex, pointCount - 1)
    val visibleSpan = (lastVisibleIndex - firstVisibleIndex).coerceAtLeast(0)

    val fraction = (relativeX / effectiveChartWidthPx).coerceIn(0f, 1f)
    val rawIndex = (firstVisibleIndex + fraction * visibleSpan)
        .roundToInt()
        .coerceIn(0, pointCount - 1)
    val indexStepWidthPx = if (visibleSpan <= 0) effectiveChartWidthPx else effectiveChartWidthPx / visibleSpan.toFloat()

    if (snapSpacing <= 1) {
        val selectedOffset = (rawIndex - firstVisibleIndex).coerceAtLeast(0)
        val selectedFraction = if (visibleSpan <= 0) 0f else selectedOffset.toFloat() / visibleSpan.toFloat()
        val selectedCenterX = chartStartPaddingPx + selectedFraction * effectiveChartWidthPx
        val deltaFromCenter = tapX - selectedCenterX
        debugSink?.invoke(
            "mapped raw=$rawIndex snapped=$rawIndex spacing=1 first=$firstVisibleIndex last=$lastVisibleIndex span=$visibleSpan fraction=$fraction stepPx=$indexStepWidthPx bandPx=$indexStepWidthPx centerX=$selectedCenterX deltaX=$deltaFromCenter"
        )
        return rawIndex
    }

    val rawIndexFloat = firstVisibleIndex.toFloat() + fraction * visibleSpan.toFloat()
    val snappedBucket = floor((rawIndexFloat - firstVisibleIndex.toFloat()) / snapSpacing.toFloat())
        .toInt()
        .coerceAtLeast(0)
    val snappedOffset = snappedBucket * snapSpacing
    val snappedIndex = (firstVisibleIndex + snappedOffset).coerceIn(firstVisibleIndex, lastVisibleIndex)
    val selectedOffset = (snappedIndex - firstVisibleIndex).coerceAtLeast(0)
    val selectedFraction = if (visibleSpan <= 0) 0f else selectedOffset.toFloat() / visibleSpan.toFloat()
    val selectedCenterX = chartStartPaddingPx + selectedFraction * effectiveChartWidthPx
    val bandWidthPx = indexStepWidthPx * snapSpacing.toFloat()
    val deltaFromCenter = tapX - selectedCenterX
    debugSink?.invoke(
        "mapped raw=$rawIndex snapped=$snappedIndex spacing=$snapSpacing first=$firstVisibleIndex last=$lastVisibleIndex span=$visibleSpan fraction=$fraction stepPx=$indexStepWidthPx bandPx=$bandWidthPx centerX=$selectedCenterX deltaX=$deltaFromCenter"
    )
    return snappedIndex
}

private fun formatAdaptiveAxisDateLabel(date: LocalDate): String {
    return date.format(CHART_AXIS_DATE_FORMATTER)
}

private fun createDynamicChartDateAxisItemPlacer(
    minimumLabelCount: Int = CHART_AXIS_MIN_VISIBLE_LABELS,
    maximumLabelCount: Int = CHART_AXIS_MAX_VISIBLE_LABELS,
): AxisItemPlacer.Horizontal {
    val fallback = AxisItemPlacer.Horizontal.default(spacing = 1, addExtremeLabelPadding = true)
    return object : AxisItemPlacer.Horizontal by fallback {
        override fun getLabelValues(
            context: ChartDrawContext,
            visibleXRange: ClosedFloatingPointRange<Float>,
            fullXRange: ClosedFloatingPointRange<Float>,
        ): List<Float> {
            val chartValues = context.chartValuesProvider.getChartValues()
            val xStep = chartValues.xStep.takeIf { it > 0f } ?: 1f
            val fullStart = ceil(fullXRange.start.toDouble()).toInt()
            val fullEnd = floor(fullXRange.endInclusive.toDouble()).toInt()
            if (fullEnd < fullStart) return emptyList()

            val firstVisible = ceil(visibleXRange.start.toDouble()).toInt().coerceIn(fullStart, fullEnd)
            val lastVisible = floor(visibleXRange.endInclusive.toDouble()).toInt().coerceIn(firstVisible, fullEnd)
            val visibleSpanSteps = ((visibleXRange.endInclusive - visibleXRange.start) / xStep)
                .coerceAtLeast(0f)
            val visibleCount = (visibleSpanSteps.roundToInt() + 1).coerceAtLeast(1)
            if (visibleCount == 1) return listOf(firstVisible.toFloat())

            val normalizedMinimum = minimumLabelCount.coerceAtLeast(2)
            val normalizedMaximum = maximumLabelCount.coerceAtLeast(normalizedMinimum)
            val targetLabelCount = visibleCount.coerceIn(normalizedMinimum, normalizedMaximum)
            val spacing = ceil((visibleCount - 1).toDouble() / (targetLabelCount - 1).toDouble())
                .toInt()
                .coerceAtLeast(1)

            val values = mutableListOf<Float>()
            val offsetFromStart = (firstVisible - fullStart).mod(spacing)
            var current = if (offsetFromStart == 0) firstVisible else firstVisible + (spacing - offsetFromStart)
            while (current <= lastVisible) {
                values += current.toFloat()
                current += spacing
            }
            if (values.lastOrNull()?.toInt() != lastVisible) {
                values += lastVisible.toFloat()
            }
            return values
        }

        override fun getMeasuredLabelValues(
            context: MeasureContext,
            horizontalDimensions: HorizontalDimensions,
            fullXRange: ClosedFloatingPointRange<Float>,
        ): List<Float> {
            val fullStart = ceil(fullXRange.start.toDouble()).toInt()
            val fullEnd = floor(fullXRange.endInclusive.toDouble()).toInt()
            if (fullEnd < fullStart) return emptyList()
            val mid = fullStart + (fullEnd - fullStart) / 2
            return listOf(fullStart.toFloat(), mid.toFloat(), fullEnd.toFloat())
        }
    }
}

private fun formatSynchronizedAxisDateLabel(
    date: LocalDate,
    index: Int,
    totalPointCount: Int,
    visibleMinX: Float,
    visibleMaxX: Float,
    chartContainerWidthPx: Float
): String {
    if (totalPointCount <= 0) return ""
    val firstVisibleIndex = ceil(visibleMinX.toDouble()).toInt().coerceIn(0, totalPointCount - 1)
    val lastVisibleIndex = visibleMaxX.toInt().coerceIn(firstVisibleIndex, totalPointCount - 1)
    if (index !in firstVisibleIndex..lastVisibleIndex) return ""

    return formatAdaptiveAxisDateLabel(
        date = date
    )
}

@Composable
private fun ChartTimelinePreviewStrip(
    entries: List<FloatEntry>,
    chartScrollState: ChartScrollState,
    visibleMinX: Float,
    visibleMaxX: Float,
    modifier: Modifier = Modifier,
) {
    if (entries.size < 2) return

    val coroutineScope = rememberCoroutineScope()
    val maxIndex = (entries.size - 1).coerceAtLeast(1)
    val viewportStartFraction = (visibleMinX / maxIndex.toFloat()).coerceIn(0f, 1f)
    val viewportEndFraction = (visibleMaxX / maxIndex.toFloat()).coerceIn(viewportStartFraction, 1f)
    val viewportFillColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.16f)
    val viewportEdgeColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.9f)

    fun scrollMainChartToFraction(fraction: Float) {
        val maxScroll = chartScrollState.maxValue
        if (maxScroll == 0f) return
        val targetScroll = maxScroll * fraction.coerceIn(0f, 1f)
        val delta = targetScroll - chartScrollState.value
        if (abs(delta) <= 0.5f) return
        coroutineScope.launch {
            chartScrollState.scrollBy(delta)
        }
    }

    Surface(
        modifier = modifier
            .fillMaxWidth()
            .height(56.dp),
        shape = RoundedCornerShape(10.dp),
        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.24f),
    ) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .pointerInput(chartScrollState.maxValue) {
                    fun handleTouchPosition(x: Float) {
                        val width = size.width.toFloat().coerceAtLeast(1f)
                        scrollMainChartToFraction(x / width)
                    }
                    detectTapGestures { offset ->
                        handleTouchPosition(offset.x)
                    }
                }
                .pointerInput(chartScrollState.maxValue, chartScrollState.value) {
                    fun handleTouchPosition(x: Float) {
                        val width = size.width.toFloat().coerceAtLeast(1f)
                        scrollMainChartToFraction(x / width)
                    }
                    detectDragGestures(
                        onDragStart = { offset -> handleTouchPosition(offset.x) },
                        onDrag = { change, _ -> handleTouchPosition(change.position.x) },
                    )
                },
        ) {
            Chart(
                chart = lineChart(),
                model = entryModelOf(entries),
                chartScrollSpec = rememberChartScrollSpec(isScrollEnabled = false),
                isZoomEnabled = false,
                modifier = Modifier
                    .fillMaxSize()
                    .padding(horizontal = 6.dp, vertical = 6.dp),
            )

            Canvas(modifier = Modifier.fillMaxSize()) {
                val left = size.width * viewportStartFraction
                val right = size.width * viewportEndFraction
                val viewportWidth = (right - left).coerceAtLeast(2f)

                drawRect(
                    color = viewportFillColor,
                    topLeft = Offset(left, 0f),
                    size = androidx.compose.ui.geometry.Size(viewportWidth, size.height),
                )
                drawLine(
                    color = viewportEdgeColor,
                    start = Offset(left, 0f),
                    end = Offset(left, size.height),
                    strokeWidth = 2f,
                )
                drawLine(
                    color = viewportEdgeColor,
                    start = Offset(left + viewportWidth, 0f),
                    end = Offset(left + viewportWidth, size.height),
                    strokeWidth = 2f,
                )
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun ChartDateRangeSelector(
    filter: ChartDateRangeFilter,
    minDate: LocalDate?,
    maxDate: LocalDate?,
    onFilterChanged: (ChartDateRangeFilter) -> Unit,
    modifier: Modifier = Modifier,
) {
    if (minDate == null || maxDate == null) return

    val displayFormatter = remember { DateTimeFormatter.ofPattern("dd.MM.yy") }
    val pickerFormatter = remember { DateTimeFormatter.ofPattern("dd.MM.yyyy") }
    var pickerTarget by remember { mutableStateOf<Boolean?>(null) }
    val zoneId = remember { ZoneId.systemDefault() }

    val (resolvedStartDate, resolvedEndDate) = remember(filter, minDate, maxDate) {
        resolveChartDateRangeBounds(filter, minDate, maxDate)
    }

    fun toEpochMillis(date: LocalDate): Long {
        return date
            .atStartOfDay(zoneId)
            .toInstant()
            .toEpochMilli()
    }

    val initialSelectedMillis = remember(pickerTarget, filter, minDate, maxDate) {
        val fallbackDate = when (pickerTarget) {
            true -> filter.startDate ?: resolvedStartDate
            false -> filter.endDate ?: resolvedEndDate
            null -> resolvedStartDate
        }
        toEpochMillis(fallbackDate)
    }

    val datePickerState = rememberDatePickerState(initialSelectedDateMillis = initialSelectedMillis)

    if (pickerTarget != null) {
        DatePickerDialog(
            onDismissRequest = { pickerTarget = null },
            confirmButton = {
                TextButton(
                    onClick = {
                        val selectedMillis = datePickerState.selectedDateMillis
                        if (selectedMillis != null) {
                            val selectedDate = Instant
                                .ofEpochMilli(selectedMillis)
                                .atZone(zoneId)
                                .toLocalDate()
                            val currentStart = filter.startDate ?: resolvedStartDate
                            val currentEnd = filter.endDate ?: resolvedEndDate
                            val updatedFilter = if (pickerTarget == true) {
                                val nextStart = selectedDate
                                val nextEnd = if (nextStart <= currentEnd) currentEnd else nextStart
                                filter.copy(
                                    preset = ChartDateRangePreset.CUSTOM,
                                    startDate = nextStart,
                                    endDate = nextEnd,
                                )
                            } else {
                                val nextEnd = selectedDate
                                val nextStart = if (currentStart <= nextEnd) currentStart else nextEnd
                                filter.copy(
                                    preset = ChartDateRangePreset.CUSTOM,
                                    startDate = nextStart,
                                    endDate = nextEnd,
                                )
                            }
                            onFilterChanged(updatedFilter)
                        }
                        pickerTarget = null
                    }
                ) {
                    Text(text = stringResource(android.R.string.ok))
                }
            },
            dismissButton = {
                TextButton(onClick = { pickerTarget = null }) {
                    Text(text = stringResource(android.R.string.cancel))
                }
            }
        ) {
            DatePicker(state = datePickerState)
        }
    }

    Surface(
        modifier = modifier.fillMaxWidth(),
        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.25f),
        shape = RoundedCornerShape(10.dp),
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 10.dp, vertical = 8.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Text(
                text = "Date range",
                style = MaterialTheme.typography.labelLarge,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )

            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .horizontalScroll(rememberScrollState()),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                val presets = listOf(
                    ChartDateRangePreset.ALL to "All",
                    ChartDateRangePreset.LAST_7_DAYS to "7D",
                    ChartDateRangePreset.LAST_30_DAYS to "30D",
                    ChartDateRangePreset.LAST_90_DAYS to "90D",
                    ChartDateRangePreset.CUSTOM to "Custom",
                )
                presets.forEach { (preset, label) ->
                    FilterChip(
                        selected = filter.preset == preset,
                        onClick = {
                            val nextFilter = if (preset == ChartDateRangePreset.CUSTOM) {
                                filter.copy(
                                    preset = ChartDateRangePreset.CUSTOM,
                                    startDate = filter.startDate ?: resolvedStartDate,
                                    endDate = filter.endDate ?: resolvedEndDate,
                                )
                            } else {
                                filter.copy(preset = preset)
                            }
                            onFilterChanged(nextFilter)
                        },
                        label = { Text(label) }
                    )
                }
            }

            if (filter.preset == ChartDateRangePreset.CUSTOM) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    OutlinedButton(
                        onClick = { pickerTarget = true },
                        modifier = Modifier.weight(1f)
                    ) {
                        Text("From ${resolvedStartDate.format(displayFormatter)}")
                    }
                    OutlinedButton(
                        onClick = { pickerTarget = false },
                        modifier = Modifier.weight(1f)
                    ) {
                        Text("To ${resolvedEndDate.format(displayFormatter)}")
                    }
                }
            }

            Text(
                text = "Showing ${resolvedStartDate.format(pickerFormatter)} - ${resolvedEndDate.format(pickerFormatter)}",
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.9f),
            )
        }
    }
}

@Composable
private fun SelectedChartDateBanner(
    selectedDate: LocalDate?,
    onNavigateToDate: (LocalDate) -> Unit
) {
    if (selectedDate == null) return

    val fullDateFormatter = remember { DateTimeFormatter.ofPattern("dd.MM.yyyy") }
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 8.dp, vertical = 4.dp),
        shape = RoundedCornerShape(10.dp),
        color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.45f)
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 12.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            Text(
                text = "Selected date: ${selectedDate.format(fullDateFormatter)}",
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.onSurface
            )
            TextButton(onClick = { onNavigateToDate(selectedDate) }) {
                Text(text = "Open")
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class, ExperimentalComposeUiApi::class)
@Composable
fun SimpleTimeChart(
    data: List<DiabetesEntry>, 
    useSymbolsInCharts: Boolean = false, 
    showStatistics: Boolean = true,
    onNavigateToDate: (String) -> Unit = {}
) {
    var selectedFilter by remember { mutableStateOf(BloodSugarTimeFilter.ALL_AVERAGE) }
    var isStatisticsExpanded by remember { mutableStateOf(showStatistics) }

    val dateFormatter = remember { DateTimeFormatter.ofPattern("dd.MM.yyyy") }
    
    val sortedData = remember(data) {
        data.mapNotNull { entry ->
            try {
                val date = LocalDate.parse(entry.date, dateFormatter)
                entry to date
            } catch (e: Exception) {
                null
            }
        }.sortedBy { it.second }
    }
    var visibleMinX by remember(sortedData) { mutableFloatStateOf(0f) }
    var visibleMaxX by remember(sortedData) { mutableFloatStateOf((sortedData.size - 1).coerceAtLeast(0).toFloat()) }

    val plottedData = remember(sortedData, selectedFilter) {
        sortedData.mapNotNull { (entry, date) ->
            val value = when (selectedFilter) {
                BloodSugarTimeFilter.ALL_AVERAGE -> {
                    val values = listOfNotNull(
                        entry.morningBloodSugarLevel.takeIf { it.isNotBlank() }?.toFloatOrNull(),
                        entry.afternoonBloodSugarLevel.takeIf { it.isNotBlank() }?.toFloatOrNull(),
                        entry.eveningBloodSugarLevel.takeIf { it.isNotBlank() }?.toFloatOrNull(),
                        entry.nightBloodSugarLevel.takeIf { it.isNotBlank() }?.toFloatOrNull()
                    )
                    if (values.isEmpty()) null else values.average().toFloat()
                }
                BloodSugarTimeFilter.MORNING -> entry.morningBloodSugarLevel.takeIf { it.isNotBlank() }?.toFloatOrNull()
                BloodSugarTimeFilter.AFTERNOON -> entry.afternoonBloodSugarLevel.takeIf { it.isNotBlank() }?.toFloatOrNull()
                BloodSugarTimeFilter.EVENING -> entry.eveningBloodSugarLevel.takeIf { it.isNotBlank() }?.toFloatOrNull()
                BloodSugarTimeFilter.NIGHT -> entry.nightBloodSugarLevel.takeIf { it.isNotBlank() }?.toFloatOrNull()
            }
            value?.let { date to it }
        }
    }
    val chartScrollState = rememberChartScrollState()
    var selectedChartIndex by remember(plottedData) { mutableStateOf<Int?>(null) }
    var selectedMarkerX by remember(plottedData) { mutableStateOf<Float?>(null) }
    var lastMultiTouchAtMs by remember(plottedData) { mutableStateOf(0L) }
    var isMultiTouchActive by remember(plottedData) { mutableStateOf(false) }
    val selectionMarker = remember { object : VicoMarker {} }
    val markerVisibilityChangeListener = remember(plottedData) {
        object : VicoMarkerVisibilityChangeListener {
            var pendingMarkerIndex: Int? = null
            var pendingMarkerX: Float? = null
            var gestureStartMarkerX: Float? = null
            var gestureStartMarkerIndex: Int? = null
            var gestureStartVisibleMinX: Float? = null
            var gestureStartVisibleMaxX: Float? = null
            var didMoveBeyondTapSlop = false

            override fun onMarkerShown(marker: VicoMarker, markerEntryModels: List<VicoMarker.EntryModel>) {
                val shouldBlockMarkerUpdates = isMultiTouchActive ||
                    SystemClock.elapsedRealtime() - lastMultiTouchAtMs <= CHART_MULTI_TOUCH_COMMIT_BLOCK_MS
                if (shouldBlockMarkerUpdates) {
                    pendingMarkerIndex = null
                    pendingMarkerX = null
                    gestureStartMarkerX = null
                    gestureStartMarkerIndex = null
                    gestureStartVisibleMinX = null
                    gestureStartVisibleMaxX = null
                    didMoveBeyondTapSlop = false
                    return
                }
                val firstMarkerEntry = markerEntryModels.firstOrNull() ?: return
                val markerIndex = firstMarkerEntry.index
                if (markerIndex !in plottedData.indices) return
                pendingMarkerIndex = markerIndex
                pendingMarkerX = firstMarkerEntry.location.x
                gestureStartMarkerX = firstMarkerEntry.location.x
                gestureStartMarkerIndex = markerIndex
                gestureStartVisibleMinX = visibleMinX
                gestureStartVisibleMaxX = visibleMaxX
                didMoveBeyondTapSlop = false
            }

            override fun onMarkerMoved(marker: VicoMarker, markerEntryModels: List<VicoMarker.EntryModel>) {
                val shouldBlockMarkerUpdates = isMultiTouchActive ||
                    SystemClock.elapsedRealtime() - lastMultiTouchAtMs <= CHART_MULTI_TOUCH_COMMIT_BLOCK_MS
                if (shouldBlockMarkerUpdates) return
                val firstMarkerEntry = markerEntryModels.firstOrNull() ?: return
                val markerIndex = firstMarkerEntry.index
                if (markerIndex !in plottedData.indices) return
                val markerX = firstMarkerEntry.location.x
                val startX = gestureStartMarkerX
                if (startX != null && abs(markerX - startX) > CHART_TAP_SLOP_PX) {
                    didMoveBeyondTapSlop = true
                }
                val startIndex = gestureStartMarkerIndex
                if (startIndex != null && markerIndex != startIndex) {
                    didMoveBeyondTapSlop = true
                }
                pendingMarkerIndex = markerIndex
                pendingMarkerX = markerX
            }

            override fun onMarkerHidden(marker: VicoMarker) {
                val markerIndex = pendingMarkerIndex
                val markerX = pendingMarkerX
                val wasRecentMultiTouch = isMultiTouchActive ||
                    SystemClock.elapsedRealtime() - lastMultiTouchAtMs <= CHART_MULTI_TOUCH_COMMIT_BLOCK_MS
                val startVisibleMinX = gestureStartVisibleMinX
                val startVisibleMaxX = gestureStartVisibleMaxX
                val didViewportMove = startVisibleMinX != null && startVisibleMaxX != null &&
                    (abs(visibleMinX - startVisibleMinX) > CHART_VIEWPORT_TAP_SLOP_X ||
                        abs(visibleMaxX - startVisibleMaxX) > CHART_VIEWPORT_TAP_SLOP_X)
                if (!didMoveBeyondTapSlop && !didViewportMove && !wasRecentMultiTouch && markerIndex != null && markerX != null) {
                    val tappedDate = plottedData[markerIndex].first
                    chartTrackerLog("chart=blood_sugar markerIndex=$markerIndex selectedDate=$tappedDate")
                    selectedChartIndex = markerIndex
                    selectedMarkerX = markerX
                }
                pendingMarkerIndex = null
                pendingMarkerX = null
                gestureStartMarkerX = null
                gestureStartMarkerIndex = null
                gestureStartVisibleMinX = null
                gestureStartVisibleMaxX = null
                didMoveBeyondTapSlop = false
            }
        }
    }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(bottom = 16.dp)
    ) {
        // Filter options
        SingleChoiceSegmentedButtonRow(
            modifier = Modifier
                .fillMaxWidth()
                .padding(8.dp)
        ) {
            BloodSugarTimeFilter.values().forEach { filter ->
                val text = when (filter) {
                    BloodSugarTimeFilter.ALL_AVERAGE -> stringResource(R.string.average)
                    BloodSugarTimeFilter.MORNING -> stringResource(R.string.morning)
                    BloodSugarTimeFilter.AFTERNOON -> stringResource(R.string.afternoon)
                    BloodSugarTimeFilter.EVENING -> stringResource(R.string.evening)
                    BloodSugarTimeFilter.NIGHT -> stringResource(R.string.night)
                }
                SegmentedButton(
                    selected = selectedFilter == filter,
                    onClick = { selectedFilter = filter },
                    shape = SegmentedButtonDefaults.itemShape(index = filter.ordinal, count = BloodSugarTimeFilter.values().size)
                ) {
                    TimeFilterText(text, useSymbolsInCharts, true)
                }
            }
        }

        // Chart
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(400.dp)
                .padding(
                    start = 8.dp,
                    end = 8.dp,
                    top = 8.dp,
                    bottom = 16.dp
                )
        ) {
            val entries = remember(plottedData) {
                plottedData.mapIndexed { index, (_, value) ->
                    FloatEntry(index.toFloat(), value)
                }
            }

            if (entries.isNotEmpty()) {
                BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
                    val density = LocalDensity.current
                    val chartWidthPx = with(density) { maxWidth.toPx() }

                    Box(modifier = Modifier.fillMaxSize()) {
                        Chart(
                            chart = lineChart(),
                            model = entryModelOf(entries),
                            chartScrollState = chartScrollState,
                            startAxis = rememberStartAxis(
                                title = stringResource(R.string.blood_sugar),
                                valueFormatter = { value, _ -> "${value.toInt()}" }
                            ),
                            bottomAxis = rememberBottomAxis(
                                title = stringResource(R.string.date),
                                itemPlacer = remember {
                                    createDynamicChartDateAxisItemPlacer()
                                },
                                valueFormatter = { value, chartValues ->
                                    visibleMinX = chartValues.minX
                                    visibleMaxX = chartValues.maxX
                                    val index = value.roundToInt()
                                    if (index >= 0 && index < plottedData.size) {
                                        formatSynchronizedAxisDateLabel(
                                            date = plottedData[index].first,
                                            index = index,
                                            totalPointCount = plottedData.size,
                                            visibleMinX = chartValues.minX,
                                            visibleMaxX = chartValues.maxX,
                                            chartContainerWidthPx = chartWidthPx
                                        )
                                    } else {
                                        ""
                                    }
                                }
                            ),
                            marker = selectionMarker,
                            markerVisibilityChangeListener = markerVisibilityChangeListener,
                            modifier = Modifier
                                .fillMaxSize()
                                .pointerInteropFilter { motionEvent ->
                                    val now = SystemClock.elapsedRealtime()
                                    when (motionEvent.actionMasked) {
                                        MotionEvent.ACTION_DOWN -> {
                                            isMultiTouchActive = false
                                        }
                                        MotionEvent.ACTION_POINTER_DOWN -> {
                                            isMultiTouchActive = true
                                            lastMultiTouchAtMs = now
                                        }
                                        MotionEvent.ACTION_MOVE -> {
                                            if (motionEvent.pointerCount > 1) {
                                                isMultiTouchActive = true
                                                lastMultiTouchAtMs = now
                                            }
                                        }
                                        MotionEvent.ACTION_POINTER_UP -> {
                                            lastMultiTouchAtMs = now
                                        }
                                        MotionEvent.ACTION_UP,
                                        MotionEvent.ACTION_CANCEL -> {
                                            isMultiTouchActive = false
                                            lastMultiTouchAtMs = now
                                        }
                                    }
                                    false
                                }
                        )

                        val selectedIndex = selectedChartIndex
                        val selectedX = selectedMarkerX
                        if (selectedIndex != null && selectedX != null && plottedData.isNotEmpty()) {
                            val highlightColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.35f)
                            Canvas(modifier = Modifier.fillMaxSize()) {
                                val lineX = selectedX.coerceIn(0f, size.width)
                                drawLine(
                                    color = highlightColor,
                                    start = Offset(lineX, 0f),
                                    end = Offset(lineX, size.height),
                                    strokeWidth = 4f
                                )
                            }
                        }
                    }
                }
            } else {
                Box(
                    modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = stringResource(R.string.no_data_available_time_period),
                        style = MaterialTheme.typography.bodyLarge,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                    )
                }
            }
        }

        val timelinePreviewEntries = remember(plottedData) {
            plottedData.mapIndexed { index, (_, value) -> FloatEntry(index.toFloat(), value) }
        }
        ChartTimelinePreviewStrip(
            entries = timelinePreviewEntries,
            chartScrollState = chartScrollState,
            visibleMinX = visibleMinX,
            visibleMaxX = visibleMaxX,
            modifier = Modifier.padding(horizontal = 8.dp),
        )

        val selectedDate = selectedChartIndex
            ?.takeIf { it in plottedData.indices }
            ?.let { plottedData[it].first }
        SelectedChartDateBanner(
            selectedDate = selectedDate,
            onNavigateToDate = { onNavigateToDate(it.toString()) }
        )
        
        // Calculate blood sugar entries for statistics
        val bloodSugarEntries = remember(data, selectedFilter) {
            data.mapNotNull { entry ->
                val value = when (selectedFilter) {
                    BloodSugarTimeFilter.ALL_AVERAGE -> {
                        val values = listOfNotNull(
                            entry.morningBloodSugarLevel.takeIf { it.isNotBlank() }?.toFloatOrNull(),
                            entry.afternoonBloodSugarLevel.takeIf { it.isNotBlank() }?.toFloatOrNull(),
                            entry.eveningBloodSugarLevel.takeIf { it.isNotBlank() }?.toFloatOrNull(),
                            entry.nightBloodSugarLevel.takeIf { it.isNotBlank() }?.toFloatOrNull()
                        )
                        if (values.isEmpty()) null else values.average().toFloat()
                    }
                    BloodSugarTimeFilter.MORNING -> entry.morningBloodSugarLevel.takeIf { it.isNotBlank() }?.toFloatOrNull()
                    BloodSugarTimeFilter.AFTERNOON -> entry.afternoonBloodSugarLevel.takeIf { it.isNotBlank() }?.toFloatOrNull()
                    BloodSugarTimeFilter.EVENING -> entry.eveningBloodSugarLevel.takeIf { it.isNotBlank() }?.toFloatOrNull()
                    BloodSugarTimeFilter.NIGHT -> entry.nightBloodSugarLevel.takeIf { it.isNotBlank() }?.toFloatOrNull()
                }
                value
            }
        }
        
        // Toggle button for statistics
        if (bloodSugarEntries.isNotEmpty()) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 4.dp)
                    .clickable { isStatisticsExpanded = !isStatisticsExpanded }
                    .background(
                        MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
                        RoundedCornerShape(8.dp)
                    )
                    .padding(horizontal = 12.dp, vertical = 6.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = stringResource(R.string.blood_sugar_statistics),
                    style = MaterialTheme.typography.bodyMedium
                )
                Icon(
                    imageVector = if (isStatisticsExpanded) 
                        Icons.Default.KeyboardArrowUp 
                    else 
                        Icons.Default.KeyboardArrowDown,
                    contentDescription = if (isStatisticsExpanded) "Hide statistics" else "Show statistics",
                    modifier = Modifier.size(20.dp)
                )
            }
        }
        
        if (bloodSugarEntries.isNotEmpty() && isStatisticsExpanded) {
            val bloodSugarValues = bloodSugarEntries
            
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 8.dp),
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.surfaceVariant
                )
            ) {
                Column(
                    modifier = Modifier.padding(16.dp)
                ) {
                    Text(
                        text = stringResource(R.string.blood_sugar_statistics),
                        style = MaterialTheme.typography.titleSmall,
                        modifier = Modifier.padding(bottom = 8.dp)
                    )
                    
                    val minValue = bloodSugarValues.minOf { it }
                    val maxValue = bloodSugarValues.maxOf { it }
                    val avgValue = bloodSugarValues.average()
                    val latestValue = bloodSugarValues.lastOrNull()
                    
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Column {
                            Text(
                                text = stringResource(R.string.latest),
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                            Text(
                                text = "${latestValue?.let { "%.1f".format(it) } ?: "N/A"} ${stringResource(R.string.mg_dl)}",
                                style = MaterialTheme.typography.bodyMedium,
                                fontWeight = FontWeight.Bold
                            )
                        }
                        Column {
                            Text(
                                text = stringResource(R.string.average),
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                            Text(
                                text = "${"%.1f".format(avgValue)} ${stringResource(R.string.mg_dl)}",
                                style = MaterialTheme.typography.bodyMedium
                            )
                        }
                        Column {
                            Text(
                                text = stringResource(R.string.range),
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                            Text(
                                text = "${"%.1f".format(minValue)} - ${"%.1f".format(maxValue)} ${stringResource(R.string.mg_dl)}",
                                style = MaterialTheme.typography.bodyMedium
                            )
                        }
                    }
                    
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class, ExperimentalComposeUiApi::class)
@Composable
fun InsulinTimeChart(
    data: List<DiabetesEntry>, 
    useSymbolsInCharts: Boolean = false, 
    showStatistics: Boolean = true,
    onNavigateToDate: (String) -> Unit = {}
) {
    var selectedFilter by remember { mutableStateOf(InsulinTimeFilter.ALL_AVERAGE) }
    var isStatisticsExpanded by remember { mutableStateOf(showStatistics) }

    val dateFormatter = remember { DateTimeFormatter.ofPattern("dd.MM.yyyy") }
    
    val sortedData = remember(data) {
        data.mapNotNull { entry ->
            try {
                val date = LocalDate.parse(entry.date, dateFormatter)
                entry to date
            } catch (e: Exception) {
                null
            }
        }.sortedBy { it.second }
    }

    var visibleMinX by remember(sortedData) { mutableFloatStateOf(0f) }
    var visibleMaxX by remember(sortedData) { mutableFloatStateOf((sortedData.size - 1).coerceAtLeast(0).toFloat()) }

    val plottedData = remember(sortedData, selectedFilter) {
        sortedData.mapNotNull { (entry, date) ->
            val value = when (selectedFilter) {
                InsulinTimeFilter.ALL_AVERAGE -> {
                    val values = listOfNotNull(
                        entry.morningInsulin.takeIf { it.isNotBlank() }?.toFloatOrNull(),
                        entry.afternoonInsulin.takeIf { it.isNotBlank() }?.toFloatOrNull(),
                        entry.eveningInsulin.takeIf { it.isNotBlank() }?.toFloatOrNull()
                    )
                    if (values.isEmpty()) null else values.average().toFloat()
                }
                InsulinTimeFilter.MORNING -> entry.morningInsulin.takeIf { it.isNotBlank() }?.toFloatOrNull()
                InsulinTimeFilter.AFTERNOON -> entry.afternoonInsulin.takeIf { it.isNotBlank() }?.toFloatOrNull()
                InsulinTimeFilter.EVENING -> entry.eveningInsulin.takeIf { it.isNotBlank() }?.toFloatOrNull()
            }
            value?.let { date to it }
        }
    }
    val chartScrollState = rememberChartScrollState()
    var selectedChartIndex by remember(plottedData) { mutableStateOf<Int?>(null) }
    var selectedMarkerX by remember(plottedData) { mutableStateOf<Float?>(null) }
    var lastMultiTouchAtMs by remember(plottedData) { mutableStateOf(0L) }
    var isMultiTouchActive by remember(plottedData) { mutableStateOf(false) }
    val selectionMarker = remember { object : VicoMarker {} }
    val markerVisibilityChangeListener = remember(plottedData) {
        object : VicoMarkerVisibilityChangeListener {
            var pendingMarkerIndex: Int? = null
            var pendingMarkerX: Float? = null
            var gestureStartMarkerX: Float? = null
            var gestureStartMarkerIndex: Int? = null
            var gestureStartVisibleMinX: Float? = null
            var gestureStartVisibleMaxX: Float? = null
            var didMoveBeyondTapSlop = false

            override fun onMarkerShown(marker: VicoMarker, markerEntryModels: List<VicoMarker.EntryModel>) {
                val shouldBlockMarkerUpdates = isMultiTouchActive ||
                    SystemClock.elapsedRealtime() - lastMultiTouchAtMs <= CHART_MULTI_TOUCH_COMMIT_BLOCK_MS
                if (shouldBlockMarkerUpdates) {
                    pendingMarkerIndex = null
                    pendingMarkerX = null
                    gestureStartMarkerX = null
                    gestureStartMarkerIndex = null
                    gestureStartVisibleMinX = null
                    gestureStartVisibleMaxX = null
                    didMoveBeyondTapSlop = false
                    return
                }
                val firstMarkerEntry = markerEntryModels.firstOrNull() ?: return
                val markerIndex = firstMarkerEntry.index
                if (markerIndex !in plottedData.indices) return
                pendingMarkerIndex = markerIndex
                pendingMarkerX = firstMarkerEntry.location.x
                gestureStartMarkerX = firstMarkerEntry.location.x
                gestureStartMarkerIndex = markerIndex
                gestureStartVisibleMinX = visibleMinX
                gestureStartVisibleMaxX = visibleMaxX
                didMoveBeyondTapSlop = false
            }

            override fun onMarkerMoved(marker: VicoMarker, markerEntryModels: List<VicoMarker.EntryModel>) {
                val shouldBlockMarkerUpdates = isMultiTouchActive ||
                    SystemClock.elapsedRealtime() - lastMultiTouchAtMs <= CHART_MULTI_TOUCH_COMMIT_BLOCK_MS
                if (shouldBlockMarkerUpdates) return
                val firstMarkerEntry = markerEntryModels.firstOrNull() ?: return
                val markerIndex = firstMarkerEntry.index
                if (markerIndex !in plottedData.indices) return
                val markerX = firstMarkerEntry.location.x
                val startX = gestureStartMarkerX
                if (startX != null && abs(markerX - startX) > CHART_TAP_SLOP_PX) {
                    didMoveBeyondTapSlop = true
                }
                val startIndex = gestureStartMarkerIndex
                if (startIndex != null && markerIndex != startIndex) {
                    didMoveBeyondTapSlop = true
                }
                pendingMarkerIndex = markerIndex
                pendingMarkerX = markerX
            }

            override fun onMarkerHidden(marker: VicoMarker) {
                val markerIndex = pendingMarkerIndex
                val markerX = pendingMarkerX
                val wasRecentMultiTouch = isMultiTouchActive ||
                    SystemClock.elapsedRealtime() - lastMultiTouchAtMs <= CHART_MULTI_TOUCH_COMMIT_BLOCK_MS
                val startVisibleMinX = gestureStartVisibleMinX
                val startVisibleMaxX = gestureStartVisibleMaxX
                val didViewportMove = startVisibleMinX != null && startVisibleMaxX != null &&
                    (abs(visibleMinX - startVisibleMinX) > CHART_VIEWPORT_TAP_SLOP_X ||
                        abs(visibleMaxX - startVisibleMaxX) > CHART_VIEWPORT_TAP_SLOP_X)
                if (!didMoveBeyondTapSlop && !didViewportMove && !wasRecentMultiTouch && markerIndex != null && markerX != null) {
                    val tappedDate = plottedData[markerIndex].first
                    chartTrackerLog("chart=insulin markerIndex=$markerIndex selectedDate=$tappedDate")
                    selectedChartIndex = markerIndex
                    selectedMarkerX = markerX
                }
                pendingMarkerIndex = null
                pendingMarkerX = null
                gestureStartMarkerX = null
                gestureStartMarkerIndex = null
                gestureStartVisibleMinX = null
                gestureStartVisibleMaxX = null
                didMoveBeyondTapSlop = false
            }
        }
    }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(bottom = 16.dp)
    ) {
        // Filter options
        SingleChoiceSegmentedButtonRow(
            modifier = Modifier
                .fillMaxWidth()
                .padding(8.dp)
        ) {
            InsulinTimeFilter.values().forEach { filter ->
                val text = when (filter) {
                    InsulinTimeFilter.ALL_AVERAGE -> stringResource(R.string.average)
                    InsulinTimeFilter.MORNING -> stringResource(R.string.morning)
                    InsulinTimeFilter.AFTERNOON -> stringResource(R.string.afternoon)
                    InsulinTimeFilter.EVENING -> stringResource(R.string.evening)
                }
                SegmentedButton(
                    selected = selectedFilter == filter,
                    onClick = { selectedFilter = filter },
                    shape = SegmentedButtonDefaults.itemShape(index = filter.ordinal, count = InsulinTimeFilter.values().size)
                ) {
                    TimeFilterText(text, useSymbolsInCharts, true)
                }
            }
        }

        // Chart
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(400.dp)
                .padding(
                    start = 8.dp,
                    end = 8.dp,
                    top = 8.dp,
                    bottom = 16.dp
                )
        ) {
            val entries = remember(plottedData) {
                plottedData.mapIndexed { index, (_, value) ->
                    FloatEntry(index.toFloat(), value)
                }
            }

            if (entries.isNotEmpty()) {
                BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
                    val density = LocalDensity.current
                    val chartWidthPx = with(density) { maxWidth.toPx() }

                    Box(modifier = Modifier.fillMaxSize()) {
                        Chart(
                            chart = lineChart(),
                            model = entryModelOf(entries.toList()),
                            chartScrollState = chartScrollState,
                            startAxis = rememberStartAxis(
                                title = stringResource(R.string.insulin),
                                valueFormatter = { value, _ -> "${value.toInt()}" }
                            ),
                            bottomAxis = rememberBottomAxis(
                                title = stringResource(R.string.date),
                                itemPlacer = remember {
                                    createDynamicChartDateAxisItemPlacer()
                                },
                                valueFormatter = { value, chartValues ->
                                    visibleMinX = chartValues.minX
                                    visibleMaxX = chartValues.maxX
                                    val index = value.roundToInt()
                                    if (index >= 0 && index < plottedData.size) {
                                        formatSynchronizedAxisDateLabel(
                                            date = plottedData[index].first,
                                            index = index,
                                            totalPointCount = plottedData.size,
                                            visibleMinX = chartValues.minX,
                                            visibleMaxX = chartValues.maxX,
                                            chartContainerWidthPx = chartWidthPx
                                        )
                                    } else {
                                        ""
                                    }
                                }
                            ),
                            marker = selectionMarker,
                            markerVisibilityChangeListener = markerVisibilityChangeListener,
                            modifier = Modifier
                                .fillMaxSize()
                                .pointerInteropFilter { motionEvent ->
                                    val now = SystemClock.elapsedRealtime()
                                    when (motionEvent.actionMasked) {
                                        MotionEvent.ACTION_DOWN -> {
                                            isMultiTouchActive = false
                                        }
                                        MotionEvent.ACTION_POINTER_DOWN -> {
                                            isMultiTouchActive = true
                                            lastMultiTouchAtMs = now
                                        }
                                        MotionEvent.ACTION_MOVE -> {
                                            if (motionEvent.pointerCount > 1) {
                                                isMultiTouchActive = true
                                                lastMultiTouchAtMs = now
                                            }
                                        }
                                        MotionEvent.ACTION_POINTER_UP -> {
                                            lastMultiTouchAtMs = now
                                        }
                                        MotionEvent.ACTION_UP,
                                        MotionEvent.ACTION_CANCEL -> {
                                            isMultiTouchActive = false
                                            lastMultiTouchAtMs = now
                                        }
                                    }
                                    false
                                }
                        )

                        val selectedIndex = selectedChartIndex
                        val selectedX = selectedMarkerX
                        if (selectedIndex != null && selectedX != null && plottedData.isNotEmpty()) {
                            val highlightColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.35f)
                            Canvas(modifier = Modifier.fillMaxSize()) {
                                val lineX = selectedX.coerceIn(0f, size.width)
                                drawLine(
                                    color = highlightColor,
                                    start = Offset(lineX, 0f),
                                    end = Offset(lineX, size.height),
                                    strokeWidth = 4f
                                )
                            }
                        }
                    }
                }
            } else {
                Box(
                    modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = stringResource(R.string.no_data_available_time_period),
                        style = MaterialTheme.typography.bodyLarge,
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                    )
                }
            }
        }

        val timelinePreviewEntries = remember(plottedData) {
            plottedData.mapIndexed { index, (_, value) -> FloatEntry(index.toFloat(), value) }
        }
        ChartTimelinePreviewStrip(
            entries = timelinePreviewEntries,
            chartScrollState = chartScrollState,
            visibleMinX = visibleMinX,
            visibleMaxX = visibleMaxX,
            modifier = Modifier.padding(horizontal = 8.dp),
        )

        val selectedDate = selectedChartIndex
            ?.takeIf { it in plottedData.indices }
            ?.let { plottedData[it].first }
        SelectedChartDateBanner(
            selectedDate = selectedDate,
            onNavigateToDate = { onNavigateToDate(it.toString()) }
        )
        
        // Statistics summary for insulin - recalculate values outside chart scope
        val insulinEntries = remember(data, selectedFilter) {
            data.mapNotNull { entry ->
                val value = when (selectedFilter) {
                    InsulinTimeFilter.ALL_AVERAGE -> {
                        val values = listOfNotNull(
                            entry.morningInsulin.takeIf { it.isNotBlank() }?.toFloatOrNull(),
                            entry.afternoonInsulin.takeIf { it.isNotBlank() }?.toFloatOrNull(),
                            entry.eveningInsulin.takeIf { it.isNotBlank() }?.toFloatOrNull()
                        )
                        if (values.isEmpty()) null else values.average().toFloat()
                    }
                    InsulinTimeFilter.MORNING -> entry.morningInsulin.takeIf { it.isNotBlank() }?.toFloatOrNull()
                    InsulinTimeFilter.AFTERNOON -> entry.afternoonInsulin.takeIf { it.isNotBlank() }?.toFloatOrNull()
                    InsulinTimeFilter.EVENING -> entry.eveningInsulin.takeIf { it.isNotBlank() }?.toFloatOrNull()
                }
                value
            }
        }
        
        // Toggle button for statistics
        if (insulinEntries.isNotEmpty()) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 4.dp)
                    .clickable { isStatisticsExpanded = !isStatisticsExpanded }
                    .background(
                        MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
                        RoundedCornerShape(8.dp)
                    )
                    .padding(horizontal = 12.dp, vertical = 6.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = stringResource(R.string.insulin_statistics),
                    style = MaterialTheme.typography.bodyMedium
                )
                Icon(
                    imageVector = if (isStatisticsExpanded) 
                        Icons.Default.KeyboardArrowUp 
                    else 
                        Icons.Default.KeyboardArrowDown,
                    contentDescription = if (isStatisticsExpanded) "Hide statistics" else "Show statistics",
                    modifier = Modifier.size(20.dp)
                )
            }
        }
        
        if (insulinEntries.isNotEmpty() && isStatisticsExpanded) {
            val insulinValues = insulinEntries
            
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 8.dp),
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.surfaceVariant
                )
            ) {
                Column(
                    modifier = Modifier.padding(16.dp)
                ) {
                    Text(
                        text = stringResource(R.string.insulin_statistics),
                        style = MaterialTheme.typography.titleSmall,
                        modifier = Modifier.padding(bottom = 8.dp)
                    )
                    
                    val minValue = insulinValues.minOf { it }
                    val maxValue = insulinValues.maxOf { it }
                    val avgValue = insulinValues.average()
                    val latestValue = insulinValues.lastOrNull()
                    val totalUnits = insulinValues.sum()
                    
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Column {
                            Text(
                                text = stringResource(R.string.latest),
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                            Text(
                                text = "${latestValue?.let { "%.1f".format(it) } ?: "N/A"} ${stringResource(R.string.units)}",
                                style = MaterialTheme.typography.bodyMedium,
                                fontWeight = FontWeight.Bold
                            )
                        }
                        Column {
                            Text(
                                text = stringResource(R.string.average),
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                            Text(
                                text = "${"%.1f".format(avgValue)} ${stringResource(R.string.units)}",
                                style = MaterialTheme.typography.bodyMedium
                            )
                        }
                        Column {
                            Text(
                                text = stringResource(R.string.total),
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                            Text(
                                text = "${"%.1f".format(totalUnits)} ${stringResource(R.string.units)}",
                                style = MaterialTheme.typography.bodyMedium
                            )
                        }
                    }
                    
                }
            }
        }
    }
}



@Composable
fun TimeFilterText(text: String, useSymbols: Boolean, useEmojiSymbols: Boolean = true) {
    if (useSymbols) {
        if (useEmojiSymbols) {
            val emoji = when (text.lowercase()) {
                "morning", "morgen", "mañana" -> "🌅"
                "afternoon", "mittag", "mediodía" -> "☀️"
                "evening", "abend", "tarde" -> "🌇"
                "night", "nacht", "noche" -> "🌙"
                else -> null
            }
            
            if (emoji != null) {
                Text(
                    text = emoji,
                    fontSize = 24.sp,
                    textAlign = TextAlign.Center,
                    modifier = Modifier
                        .size(32.dp)
                        .wrapContentSize(Alignment.Center)
                )
            } else {
                Text(text, maxLines = 1)
            }
        } else {
            val icon = when (text.lowercase()) {
                "morning", "morgen", "mañana" -> TimeIcons.Morning
                "afternoon", "mittag", "mediodía" -> TimeIcons.Afternoon
                "evening", "abend", "tarde" -> TimeIcons.Evening
                "night", "nacht", "noche" -> TimeIcons.Night
                else -> null
            }
            
            if (icon != null) {
                Icon(
                    imageVector = icon,
                    contentDescription = text,
                    tint = Color.Unspecified,
                    modifier = Modifier.size(32.dp)
                )
            } else {
                Text(text, maxLines = 1)
            }
        }
    } else {
        Text(text, maxLines = 1)
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun TimeChartDialog(
    onDismissRequest: () -> Unit,
    entries: List<DiabetesEntry>,
    useSymbolsInCharts: Boolean = false,
    customColumns: List<CustomColumn> = emptyList(),
    showStatistics: Boolean = true,
    onNavigateToDate: (String) -> Unit = {}
) {
    var selectedChartType by remember { mutableStateOf(ChartType.BLOOD_SUGAR) }
    var selectedCustomColumn by remember { mutableStateOf<CustomColumn?>(null) }
    val chartDateFormatter = remember { DateTimeFormatter.ofPattern("dd.MM.yyyy") }
    var chartDateRangeFilter by remember {
        mutableStateOf(ChartDateRangeFilter())
    }
    
    // Get custom columns that are enabled for statistics AND use numeric keyboard
    val statisticsColumns = customColumns.filter { it.includeInStatistics && it.keyboardType == "number" }
    val chartParsedEntries = remember(entries, chartDateFormatter) {
        entries.mapNotNull { entry ->
            val parsedDate = runCatching { LocalDate.parse(entry.date, chartDateFormatter) }.getOrNull() ?: return@mapNotNull null
            parsedDate to entry
        }
    }
    val chartMinimumDate = remember(chartParsedEntries) { chartParsedEntries.minOfOrNull { it.first } }
    val chartMaximumDate = remember(chartParsedEntries) { chartParsedEntries.maxOfOrNull { it.first } }
    val filteredChartEntries = remember(entries, chartDateFormatter, chartDateRangeFilter) {
        filterEntriesByChartDateRange(
            entries = entries,
            dateFormatter = chartDateFormatter,
            filter = chartDateRangeFilter,
        )
    }
    
    // Initialize selectedCustomColumn when switching to CUSTOM_COLUMN type
    LaunchedEffect(selectedChartType, statisticsColumns) {
        if (selectedChartType == ChartType.CUSTOM_COLUMN && selectedCustomColumn == null && statisticsColumns.isNotEmpty()) {
            selectedCustomColumn = statisticsColumns.first()
        }
    }
    
    Dialog(
        onDismissRequest = onDismissRequest,
        properties = DialogProperties(usePlatformDefaultWidth = false)
    ) {
        Surface(
            modifier = Modifier.fillMaxSize(),
            color = MaterialTheme.colorScheme.surface
        ) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(12.dp)
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 8.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = when (selectedChartType) {
                            ChartType.BLOOD_SUGAR -> stringResource(R.string.blood_sugar_over_time)
                            ChartType.INSULIN -> stringResource(R.string.insulin_over_time)
                            ChartType.CUSTOM_COLUMN -> selectedCustomColumn?.let { stringResource(R.string.custom_over_time, it.name) } ?: stringResource(R.string.chart_title)
                        },
                        style = MaterialTheme.typography.titleLarge
                    )
                    IconButton(onClick = onDismissRequest) {
                        Icon(
                            imageVector = Icons.Default.Close,
                            contentDescription = "Close"
                        )
                    }
                }

                ChartDateRangeSelector(
                    filter = chartDateRangeFilter,
                    minDate = chartMinimumDate,
                    maxDate = chartMaximumDate,
                    onFilterChanged = { chartDateRangeFilter = it },
                    modifier = Modifier.padding(bottom = 8.dp)
                )

                // Chart Type Selector
                if (statisticsColumns.isNotEmpty()) {
                    // Use ScrollableTabRow when we have custom columns
                    ScrollableTabRow(
                        selectedTabIndex = when (selectedChartType) {
                            ChartType.BLOOD_SUGAR -> 0
                            ChartType.INSULIN -> 1
                            ChartType.CUSTOM_COLUMN -> 2 + (statisticsColumns.indexOf(selectedCustomColumn).takeIf { it >= 0 } ?: 0)
                        },
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Tab(
                            selected = selectedChartType == ChartType.BLOOD_SUGAR,
                            onClick = { selectedChartType = ChartType.BLOOD_SUGAR },
                            text = { Text(stringResource(R.string.blood_sugar)) }
                        )
                        Tab(
                            selected = selectedChartType == ChartType.INSULIN,
                            onClick = { selectedChartType = ChartType.INSULIN },
                            text = { Text(stringResource(R.string.insulin)) }
                        )
                        statisticsColumns.forEach { column ->
                            Tab(
                                selected = selectedChartType == ChartType.CUSTOM_COLUMN && selectedCustomColumn == column,
                                onClick = { 
                                    selectedChartType = ChartType.CUSTOM_COLUMN
                                    selectedCustomColumn = column
                                },
                                text = { Text(column.name) }
                            )
                        }
                    }
                } else {
                    // Use regular TabRow when no custom columns
                    TabRow(
                        selectedTabIndex = selectedChartType.ordinal,
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Tab(
                            selected = selectedChartType == ChartType.BLOOD_SUGAR,
                            onClick = { selectedChartType = ChartType.BLOOD_SUGAR },
                            text = { Text(stringResource(R.string.blood_sugar)) }
                        )
                        Tab(
                            selected = selectedChartType == ChartType.INSULIN,
                            onClick = { selectedChartType = ChartType.INSULIN },
                            text = { Text(stringResource(R.string.insulin)) }
                        )
                    }
                }

                // Scrollable content area for charts and statistics
                LazyColumn(
                    modifier = Modifier.fillMaxSize(),
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    item {
                        when (selectedChartType) {
                            ChartType.BLOOD_SUGAR -> SimpleTimeChart(
                                data = filteredChartEntries,
                                useSymbolsInCharts = useSymbolsInCharts, 
                                showStatistics = showStatistics,
                                onNavigateToDate = onNavigateToDate
                            )
                            ChartType.INSULIN -> InsulinTimeChart(
                                data = filteredChartEntries,
                                useSymbolsInCharts = useSymbolsInCharts, 
                                showStatistics = showStatistics,
                                onNavigateToDate = onNavigateToDate
                            )
                            ChartType.CUSTOM_COLUMN -> {
                                if (selectedCustomColumn != null) {
                                    CustomColumnChart(
                                        data = filteredChartEntries,
                                        column = selectedCustomColumn!!,
                                        useSymbolsInCharts = useSymbolsInCharts,
                                        showStatistics = showStatistics,
                                        onNavigateToDate = onNavigateToDate
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalComposeUiApi::class)
@Composable
fun CustomColumnChart(
    data: List<DiabetesEntry>, 
    column: CustomColumn,
    useSymbolsInCharts: Boolean = false,
    showStatistics: Boolean = true,
    onNavigateToDate: (String) -> Unit = {}
) {
    var isStatisticsExpanded by remember { mutableStateOf(showStatistics) }
    
    val dateFormatter = remember { DateTimeFormatter.ofPattern("dd.MM.yyyy") }
    val sortedData = remember(data, column.id) {
        data.mapNotNull { entry ->
            try {
                val date = LocalDate.parse(entry.date, dateFormatter)
                val value = entry.customColumnData[column.id]?.replace(",", ".")?.toDoubleOrNull()
                if (value != null) {
                    Triple(entry, date, value)
                } else null
            } catch (e: Exception) {
                null
            }
        }.sortedBy { it.second }
    }
    
    var visibleMinX by remember(sortedData) { mutableFloatStateOf(0f) }
    var visibleMaxX by remember(sortedData) { mutableFloatStateOf((sortedData.size - 1).coerceAtLeast(0).toFloat()) }
    val chartScrollState = rememberChartScrollState()
    var selectedChartIndex by remember(sortedData) { mutableStateOf<Int?>(null) }
    var selectedMarkerX by remember(sortedData) { mutableStateOf<Float?>(null) }
    var lastMultiTouchAtMs by remember(sortedData) { mutableStateOf(0L) }
    var isMultiTouchActive by remember(sortedData) { mutableStateOf(false) }
    val selectionMarker = remember { object : VicoMarker {} }
    val markerVisibilityChangeListener = remember(sortedData) {
        object : VicoMarkerVisibilityChangeListener {
            var pendingMarkerIndex: Int? = null
            var pendingMarkerX: Float? = null
            var gestureStartMarkerX: Float? = null
            var gestureStartMarkerIndex: Int? = null
            var gestureStartVisibleMinX: Float? = null
            var gestureStartVisibleMaxX: Float? = null
            var didMoveBeyondTapSlop = false

            override fun onMarkerShown(marker: VicoMarker, markerEntryModels: List<VicoMarker.EntryModel>) {
                val shouldBlockMarkerUpdates = isMultiTouchActive ||
                    SystemClock.elapsedRealtime() - lastMultiTouchAtMs <= CHART_MULTI_TOUCH_COMMIT_BLOCK_MS
                if (shouldBlockMarkerUpdates) {
                    pendingMarkerIndex = null
                    pendingMarkerX = null
                    gestureStartMarkerX = null
                    gestureStartMarkerIndex = null
                    gestureStartVisibleMinX = null
                    gestureStartVisibleMaxX = null
                    didMoveBeyondTapSlop = false
                    return
                }
                val firstMarkerEntry = markerEntryModels.firstOrNull() ?: return
                val markerIndex = firstMarkerEntry.index
                if (markerIndex !in sortedData.indices) return
                pendingMarkerIndex = markerIndex
                pendingMarkerX = firstMarkerEntry.location.x
                gestureStartMarkerX = firstMarkerEntry.location.x
                gestureStartMarkerIndex = markerIndex
                gestureStartVisibleMinX = visibleMinX
                gestureStartVisibleMaxX = visibleMaxX
                didMoveBeyondTapSlop = false
            }

            override fun onMarkerMoved(marker: VicoMarker, markerEntryModels: List<VicoMarker.EntryModel>) {
                val shouldBlockMarkerUpdates = isMultiTouchActive ||
                    SystemClock.elapsedRealtime() - lastMultiTouchAtMs <= CHART_MULTI_TOUCH_COMMIT_BLOCK_MS
                if (shouldBlockMarkerUpdates) return
                val firstMarkerEntry = markerEntryModels.firstOrNull() ?: return
                val markerIndex = firstMarkerEntry.index
                if (markerIndex !in sortedData.indices) return
                val markerX = firstMarkerEntry.location.x
                val startX = gestureStartMarkerX
                if (startX != null && abs(markerX - startX) > CHART_TAP_SLOP_PX) {
                    didMoveBeyondTapSlop = true
                }
                val startIndex = gestureStartMarkerIndex
                if (startIndex != null && markerIndex != startIndex) {
                    didMoveBeyondTapSlop = true
                }
                pendingMarkerIndex = markerIndex
                pendingMarkerX = markerX
            }

            override fun onMarkerHidden(marker: VicoMarker) {
                val markerIndex = pendingMarkerIndex
                val markerX = pendingMarkerX
                val wasRecentMultiTouch = isMultiTouchActive ||
                    SystemClock.elapsedRealtime() - lastMultiTouchAtMs <= CHART_MULTI_TOUCH_COMMIT_BLOCK_MS
                val startVisibleMinX = gestureStartVisibleMinX
                val startVisibleMaxX = gestureStartVisibleMaxX
                val didViewportMove = startVisibleMinX != null && startVisibleMaxX != null &&
                    (abs(visibleMinX - startVisibleMinX) > CHART_VIEWPORT_TAP_SLOP_X ||
                        abs(visibleMaxX - startVisibleMaxX) > CHART_VIEWPORT_TAP_SLOP_X)
                if (!didMoveBeyondTapSlop && !didViewportMove && !wasRecentMultiTouch && markerIndex != null && markerX != null) {
                    val tappedDate = sortedData[markerIndex].second
                    chartTrackerLog("chart=custom_${column.id} markerIndex=$markerIndex selectedDate=$tappedDate")
                    selectedChartIndex = markerIndex
                    selectedMarkerX = markerX
                }
                pendingMarkerIndex = null
                pendingMarkerX = null
                gestureStartMarkerX = null
                gestureStartMarkerIndex = null
                gestureStartVisibleMinX = null
                gestureStartVisibleMaxX = null
                didMoveBeyondTapSlop = false
            }
        }
    }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(bottom = 16.dp)
    ) {
        Text(
            text = "${column.name} Over Time",
            style = MaterialTheme.typography.titleMedium,
            modifier = Modifier.padding(start = 8.dp, end = 8.dp, bottom = 16.dp)
        )
        
        // Chart
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(400.dp)
                .padding(
                    start = 8.dp,
                    end = 8.dp,
                    top = 8.dp,
                    bottom = 16.dp
                )
        ) {
            val (entries, displayRange) = remember(sortedData) {
                if (sortedData.isEmpty()) {
                    Pair(emptyList<FloatEntry>(), Pair(0f, 100f))
                } else {
                    // Calculate original data range
                    val originalValues = sortedData.map { it.third.toFloat() }
                    val originalMin = originalValues.minOf { it }
                    val originalMax = originalValues.maxOf { it }
                    val originalRange = originalMax - originalMin
                    
                    // Calculate smart display range with buffer
                    val buffer = when {
                        originalRange <= 0.1f -> 0.5f // Very small range, add 0.5 units buffer
                        originalRange <= 1f -> originalRange * 0.5f + 0.5f // Small range, add 50% + 0.5 buffer
                        originalRange <= 5f -> originalRange * 0.3f + 1f // Medium range, add 30% + 1 buffer
                        else -> originalRange * 0.2f + 2f // Large range, add 20% + 2 buffer
                    }
                    
                    val displayMin = (originalMin - buffer).coerceAtLeast(0f)
                    val displayMax = originalMax + buffer
                    val displayRange = displayMax - displayMin
                    
                    // Transform data to fit 0-100 scale for better chart rendering
                    val transformedEntries = sortedData.mapIndexed { index, (_, _, value) ->
                        val normalizedValue = if (displayRange > 0) {
                            ((value.toFloat() - displayMin) / displayRange) * 100f
                        } else {
                            50f // Fallback for single value
                        }
                        FloatEntry(index.toFloat(), normalizedValue)
                    }
                    
                    Pair(transformedEntries, Pair(displayMin, displayMax))
                }
            }

            if (entries.isNotEmpty()) {
                BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
                    val density = LocalDensity.current
                    val chartWidthPx = with(density) { maxWidth.toPx() }

                    Box(modifier = Modifier.fillMaxSize()) {
                        Chart(
                            chart = lineChart(),
                            model = entryModelOf(entries),
                            chartScrollState = chartScrollState,
                            startAxis = rememberStartAxis(
                                title = if (column.unit.isNotEmpty()) "${column.name} (${column.unit})" else column.name,
                                valueFormatter = { value, _ ->
                                    // Convert normalized value back to original scale
                                    val originalValue = displayRange.first + (value / 100f) * (displayRange.second - displayRange.first)
                                    if (column.unit.isNotEmpty()) {
                                        "${"%.1f".format(originalValue)} ${column.unit}"
                                    } else {
                                        "%.1f".format(originalValue)
                                    }
                                }
                            ),
                            bottomAxis = rememberBottomAxis(
                                title = stringResource(R.string.date),
                                itemPlacer = remember {
                                    createDynamicChartDateAxisItemPlacer()
                                },
                                valueFormatter = { value, chartValues ->
                                    visibleMinX = chartValues.minX
                                    visibleMaxX = chartValues.maxX
                                    val index = value.roundToInt()
                                    if (index >= 0 && index < sortedData.size) {
                                        formatSynchronizedAxisDateLabel(
                                            date = sortedData[index].second,
                                            index = index,
                                            totalPointCount = sortedData.size,
                                            visibleMinX = chartValues.minX,
                                            visibleMaxX = chartValues.maxX,
                                            chartContainerWidthPx = chartWidthPx
                                        )
                                    } else {
                                        ""
                                    }
                                }
                            ),
                            marker = selectionMarker,
                            markerVisibilityChangeListener = markerVisibilityChangeListener,
                            modifier = Modifier
                                .fillMaxSize()
                                .pointerInteropFilter { motionEvent ->
                                    val now = SystemClock.elapsedRealtime()
                                    when (motionEvent.actionMasked) {
                                        MotionEvent.ACTION_DOWN -> {
                                            isMultiTouchActive = false
                                        }
                                        MotionEvent.ACTION_POINTER_DOWN -> {
                                            isMultiTouchActive = true
                                            lastMultiTouchAtMs = now
                                        }
                                        MotionEvent.ACTION_MOVE -> {
                                            if (motionEvent.pointerCount > 1) {
                                                isMultiTouchActive = true
                                                lastMultiTouchAtMs = now
                                            }
                                        }
                                        MotionEvent.ACTION_POINTER_UP -> {
                                            lastMultiTouchAtMs = now
                                        }
                                        MotionEvent.ACTION_UP,
                                        MotionEvent.ACTION_CANCEL -> {
                                            isMultiTouchActive = false
                                            lastMultiTouchAtMs = now
                                        }
                                    }
                                    false
                                }
                        )

                        val selectedIndex = selectedChartIndex
                        val selectedX = selectedMarkerX
                        if (selectedIndex != null && selectedX != null && sortedData.isNotEmpty()) {
                            val highlightColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.35f)
                            Canvas(modifier = Modifier.fillMaxSize()) {
                                val lineX = selectedX.coerceIn(0f, size.width)
                                drawLine(
                                    color = highlightColor,
                                    start = Offset(lineX, 0f),
                                    end = Offset(lineX, size.height),
                                    strokeWidth = 4f
                                )
                            }
                        }
                    }
                }
            } else {
                Box(
                    modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center
                ) {
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Text(
                            text = "${stringResource(R.string.no_numeric_data_available)} ${column.name}",
                            style = MaterialTheme.typography.bodyLarge,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f),
                            textAlign = TextAlign.Center
                        )
                        Spacer(modifier = Modifier.height(8.dp))
                        Text(
                            text = stringResource(R.string.enter_numeric_values_chart),
                            style = MaterialTheme.typography.bodyMedium,
                            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.4f),
                            textAlign = TextAlign.Center
                        )
                    }
                }
            }
        }

        val timelinePreviewEntries = remember(sortedData) {
            sortedData.mapIndexed { index, (_, _, value) ->
                FloatEntry(index.toFloat(), value.toFloat())
            }
        }
        ChartTimelinePreviewStrip(
            entries = timelinePreviewEntries,
            chartScrollState = chartScrollState,
            visibleMinX = visibleMinX,
            visibleMaxX = visibleMaxX,
            modifier = Modifier.padding(horizontal = 8.dp),
        )

        val selectedDate = selectedChartIndex
            ?.takeIf { it in sortedData.indices }
            ?.let { sortedData[it].second }
        SelectedChartDateBanner(
            selectedDate = selectedDate,
            onNavigateToDate = { onNavigateToDate(it.toString()) }
        )
        
        // Calculate chart data for statistics
        val chartData = remember(data, column.id) {
            data.mapNotNull { entry ->
                entry.customColumnData[column.id]?.replace(",", ".")?.toDoubleOrNull()
            }
        }
        
        // Toggle button for statistics
        if (chartData.isNotEmpty()) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 4.dp)
                    .clickable { isStatisticsExpanded = !isStatisticsExpanded }
                    .background(
                        MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
                        RoundedCornerShape(8.dp)
                    )
                    .padding(horizontal = 12.dp, vertical = 6.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = "Statistics Summary",
                    style = MaterialTheme.typography.bodyMedium
                )
                Icon(
                    imageVector = if (isStatisticsExpanded) 
                        Icons.Default.KeyboardArrowUp 
                    else 
                        Icons.Default.KeyboardArrowDown,
                    contentDescription = if (isStatisticsExpanded) "Hide statistics" else "Show statistics",
                    modifier = Modifier.size(20.dp)
                )
            }
        }
        
        // Statistics summary below the chart
        if (chartData.isNotEmpty() && isStatisticsExpanded) {
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 8.dp),
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.surfaceVariant
                )
            ) {
                Column(
                    modifier = Modifier.padding(16.dp)
                ) {
                        Text(
                            text = "Statistics Summary",
                            style = MaterialTheme.typography.titleSmall,
                            modifier = Modifier.padding(bottom = 8.dp)
                        )
                        
                        val minValue = chartData.minOf { it }
                        val maxValue = chartData.maxOf { it }
                        val avgValue = chartData.average()
                        val latestValue = chartData.lastOrNull()
                        
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Column {
                                Text(
                                    text = "Latest",
                                    style = MaterialTheme.typography.labelSmall,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                                Text(
                                    text = "${latestValue?.let { "%.1f".format(it) } ?: "N/A"}${if (column.unit.isNotEmpty()) " ${column.unit}" else ""}",
                                    style = MaterialTheme.typography.bodyMedium,
                                    fontWeight = FontWeight.Bold
                                )
                            }
                            Column {
                                Text(
                                    text = "Average",
                                    style = MaterialTheme.typography.labelSmall,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                                Text(
                                    text = "${"%.1f".format(avgValue)}${if (column.unit.isNotEmpty()) " ${column.unit}" else ""}",
                                    style = MaterialTheme.typography.bodyMedium
                                )
                            }
                            Column {
                                Text(
                                    text = "Range",
                                    style = MaterialTheme.typography.labelSmall,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                                Text(
                                    text = "${"%.1f".format(minValue)} - ${"%.1f".format(maxValue)}${if (column.unit.isNotEmpty()) " ${column.unit}" else ""}",
                                    style = MaterialTheme.typography.bodyMedium
                                )
                            }
                        }
                    }
                }
            }
    }
}

@Composable
private fun OccurrenceBackNavigationBanner(
    isVisible: Boolean,
    selectedLanguage: String,
    onRestore: () -> Unit
) {
    if (!isVisible) return

    Card(
        modifier = Modifier
            .fillMaxWidth()
            .padding(8.dp)
            .clickable(onClick = onRestore),
        colors = CardDefaults.cardColors(
            containerColor = MaterialTheme.colorScheme.primary
        ),
        elevation = CardDefaults.cardElevation(defaultElevation = 6.dp)
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp),
            horizontalArrangement = Arrangement.Center,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Icon(
                imageVector = Icons.Default.ArrowBack,
                contentDescription = when (selectedLanguage) {
                    "German" -> "Zurück"
                    "Spanish" -> "Volver"
                    else -> "Go Back"
                },
                tint = MaterialTheme.colorScheme.onPrimary,
                modifier = Modifier.size(24.dp)
            )
            Spacer(modifier = Modifier.width(12.dp))
            Text(
                text = when (selectedLanguage) {
                    "German" -> "Tippen um zurückzukehren"
                    "Spanish" -> "Toca para volver"
                    else -> "Tap to Go Back"
                },
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onPrimary
            )
        }
    }
}

@Composable
private fun rememberTableGestureModifier(
    totalPagesForGesture: Int,
    usePaginationMode: Boolean,
    useButtonPaging: Boolean,
    currentPage: Int,
    onCurrentPageChange: (Int) -> Unit,
    onScrollbarVisibilityChange: (Boolean) -> Unit
): Modifier {
    val swipeStartY = remember { mutableStateOf(0f) }
    val swipeStartX = remember { mutableStateOf(0f) }
    val isDragging = remember { mutableStateOf(false) }
    val isVerticalSwipe = remember { mutableStateOf(false) }

    return Modifier.pointerInput(totalPagesForGesture, usePaginationMode, useButtonPaging, currentPage) {
        awaitPointerEventScope {
            while (true) {
                val event = awaitPointerEvent()
                when (event.type) {
                    androidx.compose.ui.input.pointer.PointerEventType.Press -> {
                        val change = event.changes.firstOrNull()
                        if (change != null) {
                            swipeStartY.value = change.position.y
                            swipeStartX.value = change.position.x
                            isDragging.value = false
                            isVerticalSwipe.value = false
                        }
                    }

                    androidx.compose.ui.input.pointer.PointerEventType.Move -> {
                        val change = event.changes.firstOrNull()
                        if (change != null) {
                            val totalDragY = change.position.y - swipeStartY.value
                            val totalDragX = change.position.x - swipeStartX.value

                            if (kotlin.math.abs(totalDragY) > 10 || kotlin.math.abs(totalDragX) > 10) {
                                isDragging.value = true
                            }

                            if (usePaginationMode && !useButtonPaging) {
                                if (
                                    kotlin.math.abs(totalDragY) > kotlin.math.abs(totalDragX) &&
                                    kotlin.math.abs(totalDragY) > 30
                                ) {
                                    isVerticalSwipe.value = true
                                    onScrollbarVisibilityChange(true)
                                } else if (
                                    kotlin.math.abs(totalDragX) > kotlin.math.abs(totalDragY) &&
                                    kotlin.math.abs(totalDragX) > 30
                                ) {
                                    onScrollbarVisibilityChange(false)
                                    isVerticalSwipe.value = false
                                }
                            }
                        }
                    }

                    androidx.compose.ui.input.pointer.PointerEventType.Release -> {
                        if (usePaginationMode && !useButtonPaging) {
                            if (isVerticalSwipe.value) {
                                val totalDragY = swipeStartY.value - (event.changes.firstOrNull()?.position?.y ?: 0f)
                                val swipeThreshold = 50f

                                if (kotlin.math.abs(totalDragY) > swipeThreshold) {
                                    if (totalDragY > 0) {
                                        if (currentPage < totalPagesForGesture - 1) {
                                            onCurrentPageChange(currentPage + 1)
                                        }
                                    } else if (currentPage > 0) {
                                        onCurrentPageChange(currentPage - 1)
                                    }
                                }
                            }

                            if (!isDragging.value) {
                                onScrollbarVisibilityChange(false)
                            }
                        }

                        swipeStartY.value = 0f
                        swipeStartX.value = 0f
                        isDragging.value = false
                        isVerticalSwipe.value = false
                    }
                }
            }
        }
    }
}

private fun tableLabelsForLanguage(selectedLanguage: String): Map<String, String> {
    return when (selectedLanguage) {
        "German" -> mapOf(
            "date" to "Datum",
            "bloodSugarControl" to "Blutzuckerkontrolle",
            "morning" to "Morgen",
            "afternoon" to "Mittag",
            "evening" to "Abend",
            "night" to "Nacht",
            "insulin" to "Insulin",
            "remarks" to "Bemerkungen"
        )

        "Spanish" -> mapOf(
            "date" to "Fecha",
            "bloodSugarControl" to "Control de Azúcar",
            "morning" to "Mañana",
            "afternoon" to "Mediodía",
            "evening" to "Tarde",
            "night" to "Noche",
            "insulin" to "Insulina",
            "remarks" to "Notas"
        )

        else -> mapOf(
            "date" to "Date",
            "bloodSugarControl" to "Blood Sugar Control",
            "morning" to "Morning",
            "afternoon" to "Afternoon",
            "evening" to "Evening",
            "night" to "Night",
            "insulin" to "Insulin",
            "remarks" to "Remarks"
        )
    }
}

@Composable
fun TableHeader(
    labels: Map<String, String>,
    fontColor: Color,
    gridColor: Color,
    insulinColumnColor: Color,
    scale: Float = 1f,
    heightScale: Float = 1f,
    useSymbolsInCharts: Boolean = false,
    useEmojiSymbols: Boolean = true,
    customColumns: List<CustomColumn> = emptyList(),
    isDateSortDescending: Boolean = false,
    onDateSortToggle: () -> Unit = {}
) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .padding(4.dp),
        shape = RoundedCornerShape(12.dp),
        colors = CardDefaults.cardColors(
            containerColor = MaterialTheme.colorScheme.surface,
        ),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding((8 * scale).dp),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.Bottom
        ) {
            // Date Column
            HeaderCell(
                title = labels["date"] ?: "Date",
                modifier = Modifier.weight(1f),
                fontColor = fontColor,
                scale = scale,
                heightScale = heightScale,
                isDateSortDescending = isDateSortDescending,
                showSortIndicator = true,
                onClick = onDateSortToggle
            )
            
            // Blood Sugar Control Column
            Column(
                modifier = Modifier
                    .weight(3f)
                    .padding(horizontal = 4.dp)
            ) {
                Text(
                    text = labels["bloodSugarControl"] ?: "Blood Sugar Control",
                    fontWeight = FontWeight.Bold,
                    fontSize = (14 * scale).sp,
                    textAlign = TextAlign.Center,
                    color = fontColor,
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = (8 * scale).dp)
                )
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceEvenly
                ) {
                    listOf(
                        labels["morning"] ?: "Morning",
                        labels["afternoon"] ?: "Afternoon",
                        labels["evening"] ?: "Evening",
                        labels["night"] ?: "Night"
                    ).forEach { time ->
                        SubHeaderCell(
                            text = time,
                            useSymbols = useSymbolsInCharts,
                            modifier = Modifier.weight(1f),
                            fontColor = fontColor,
                            gridColor = gridColor,
                            useEmojiSymbols = useEmojiSymbols,
                            scale = scale,
                            heightScale = heightScale
                        )
                    }
                }
            }
            
            // Insulin Column
            Column(
                modifier = Modifier
                    .weight(2.2f)
                    .padding(horizontal = 4.dp)
                    .background(
                        color = insulinColumnColor,
                        shape = RoundedCornerShape(8.dp)
                    )
            ) {
                Text(
                    text = labels["insulin"] ?: "Insulin",
                    fontWeight = FontWeight.Bold,
                    fontSize = (14 * scale).sp,
                    textAlign = TextAlign.Center,
                    color = fontColor,
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = (8 * scale).dp)
                )
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceEvenly
                ) {
                    listOf(
                        labels["morning"] ?: "Morning",
                        labels["afternoon"] ?: "Afternoon",
                        labels["evening"] ?: "Evening"
                    ).forEach { time ->
                        SubHeaderCell(
                            text = time,
                            useSymbols = useSymbolsInCharts,
                            modifier = Modifier.weight(1f),
                            fontColor = fontColor,
                            gridColor = gridColor,
                            useEmojiSymbols = useEmojiSymbols,
                            scale = scale,
                            heightScale = heightScale
                        )
                    }
                }
            }
            
            // Custom Columns Headers (including Remarks which is now a built-in custom column)
            val context = LocalContext.current
            customColumns.forEach { column ->
                val displayTitle = if (column.unit.isNotEmpty()) {
                    "${column.name} (${column.unit})"
                } else {
                    column.name
                }
                
                // Use special weight for Remarks column, standard weight for others
                val columnWeight = if (column.id == CustomColumnManager.REMARKS_COLUMN_ID) 1.5f else 1f
                
                EditableHeaderCell(
                    title = displayTitle,
                    onTitleChange = { newTitle ->
                        // Extract name and unit from the new title
                        val (newName, newUnit) = if (newTitle.contains("(") && newTitle.contains(")")) {
                            val name = newTitle.substringBefore("(").trim()
                            val unit = newTitle.substringAfter("(").substringBefore(")").trim()
                            name to unit
                        } else {
                            newTitle.trim() to ""
                        }
                        
                        val updatedColumn = column.copy(name = newName, unit = newUnit)
                        CustomColumnManager.updateCustomColumn(context, column.id, updatedColumn)
                        // Note: customColumns will be refreshed when the parent recomposes
                    },
                    modifier = Modifier.weight(columnWeight),
                    fontColor = fontColor,
                    scale = scale,
                    heightScale = heightScale
                )
            }
        }
    }
}

@Composable
fun HeaderCell(
    title: String,
    modifier: Modifier = Modifier,
    fontColor: Color,
    scale: Float = 1f,
    heightScale: Float = 1f,
    isDateSortDescending: Boolean = false,
    showSortIndicator: Boolean = false,
    onClick: (() -> Unit)? = null
) {
    Surface(
        modifier = modifier
            .padding(horizontal = 2.dp)
            .height((56 * heightScale).dp), // Header height - only affected by heightScale, not zoom scale
        shape = RoundedCornerShape(6.dp),
        color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.8f)
    ) {
        Box(
            modifier = Modifier
                .padding(4.dp)
                .fillMaxSize()
                .let { baseModifier ->
                    if (onClick != null) {
                        baseModifier.clickable(onClick = onClick)
                    } else {
                        baseModifier
                    }
                },
            contentAlignment = Alignment.Center
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 4.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.Center
            ) {
                Text(
                    text = title,
                    fontWeight = FontWeight.Bold,
                    fontSize = (14 * scale).sp,
                    textAlign = TextAlign.Center,
                    color = fontColor,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = if (showSortIndicator) {
                        Modifier.weight(1f).padding(end = 6.dp)
                    } else {
                        Modifier
                    }
                )

                if (showSortIndicator) {
                    Icon(
                        imageVector = if (isDateSortDescending) Icons.Default.ArrowDownward else Icons.Default.ArrowUpward,
                        contentDescription = null,
                        tint = fontColor,
                        modifier = Modifier.size((14 * scale).dp)
                    )
                }
            }
        }
    }
}

@Composable
fun EditableHeaderCell(
    title: String,
    onTitleChange: (String) -> Unit,
    modifier: Modifier = Modifier,
    fontColor: Color,
    scale: Float = 1f,
    heightScale: Float = 1f
) {
    var isEditing by remember { mutableStateOf(false) }
    var editText by remember(title) { mutableStateOf(title) }
    var textFieldValue by remember(title) { mutableStateOf(ComposeTextFieldValue(title, TextRange(title.length))) }
    val focusRequester = remember { FocusRequester() }
    
    // Auto-focus when entering edit mode and set cursor at end
    LaunchedEffect(isEditing) {
        if (isEditing) {
            textFieldValue = ComposeTextFieldValue(editText, TextRange(editText.length))
            focusRequester.requestFocus()
        }
    }
    
    Surface(
        modifier = modifier
            .padding(horizontal = 2.dp)
            .height((56 * heightScale).dp), // Header height - only affected by heightScale, not zoom scale
        shape = RoundedCornerShape(6.dp),
        color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.8f)
    ) {
        Box(
            modifier = Modifier
                .padding(4.dp)
                .fillMaxSize()
                .clickable(
                    indication = null, // Remove ripple effect
                    interactionSource = remember { MutableInteractionSource() }
                ) { 
                    isEditing = true 
                },
            contentAlignment = Alignment.Center
        ) {
            if (isEditing) {
                BasicTextField(
                    value = textFieldValue,
                    onValueChange = { 
                        textFieldValue = it
                        editText = it.text
                    },
                    textStyle = TextStyle(
                        fontWeight = FontWeight.Bold,
                        fontSize = (14 * scale).sp,
                        textAlign = TextAlign.Center,
                        color = fontColor
                    ),
                    singleLine = true,
                    keyboardOptions = KeyboardOptions(
                        imeAction = ImeAction.Done
                    ),
                    keyboardActions = KeyboardActions(
                        onDone = {
                            onTitleChange(editText)
                            isEditing = false
                        }
                    ),
                    modifier = Modifier
                        .fillMaxWidth()
                        .focusRequester(focusRequester)
                )
            } else {
                Text(
                    text = title,
                    fontWeight = FontWeight.Bold,
                    fontSize = (14 * scale).sp,
                    textAlign = TextAlign.Center,
                    color = fontColor,
                    modifier = Modifier.fillMaxWidth()
                )
            }
        }
    }
}


@Composable
fun SubHeaderCell(
    text: String,
    useSymbols: Boolean,
    modifier: Modifier = Modifier,
    fontColor: Color,
    gridColor: Color,
    useEmojiSymbols: Boolean = true,
    scale: Float = 1f,
    heightScale: Float = 1f
) {
    Surface(
        modifier = modifier
            .padding(horizontal = 2.dp)
            .height((40 * scale * heightScale).dp), // Match data cell height
        shape = RoundedCornerShape(6.dp),
        color = MaterialTheme.colorScheme.surface,
        border = BorderStroke(0.5.dp, gridColor.copy(alpha = 0.5f))
    ) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .padding(4.dp),
            contentAlignment = Alignment.Center
        ) {
            TimeFilterText(text, useSymbols, useEmojiSymbols)
        }
    }
}

@Composable
fun TableRow(
    entry: DiabetesEntry,
    entryIndex: Int,
    labels: Map<String, String>,
    isSecured: Boolean = false,
    confirmedEditingSessions: Set<String> = emptySet(),
    onShowEditConfirmDialog: ((String, (() -> Unit)) -> Unit)? = null,
    onClearConfirmation: ((String) -> Unit)? = null,
    onEntryChanged: (Int, DiabetesEntry) -> Unit,
    onDeleteEntry: (Int) -> Unit,
    fontColor: Color,
    backgroundColor: Color,
    gridColor: Color,
    insulinColumnColor: Color,
    focusedCell: Pair<Int, String>?,
    focusRequesters: MutableMap<Pair<Int, String>, FocusRequester>,
    onRequestFocus: (Pair<Int, String>) -> Unit,
    cellTextFieldValues: MutableMap<Pair<Int, String>, TextFieldValue>,
    foodPresets: List<FoodPreset>,
    setFoodPresets: (List<FoodPreset>) -> Unit,
    scale: Float = 1f,
    heightScale: Float = 1f,
    selectedLanguage: String = "English",
    customColumns: List<CustomColumn> = emptyList(),
    customMarkers: List<CustomMarkerType> = emptyList(),
    onCustomMarkersUpdate: ((List<CustomMarkerType>) -> Unit)? = null,
    foodWarningMessage: String = "",
    onFoodWarningMessageChange: (String) -> Unit = {},
    pendingFoodAction: (() -> Unit)? = null,
    onPendingFoodActionChange: ((() -> Unit)?) -> Unit = {},
    showFoodWarning: Boolean = false,
    onFoodWarningChange: (Boolean) -> Unit = {},
    onWarningFoodNameChange: (String) -> Unit = {},
    highlightedOccurrenceDate: LocalDate? = null,
    highlightedOccurrenceTimeOfDay: String? = null,
    occurrenceHighlightToken: Int = 0,
    context: Context,
    onMeasuredHeightPx: ((Int) -> Unit)? = null
) {
    val keyboardController = LocalSoftwareKeyboardController.current
    val focusManager = LocalFocusManager.current
    var showDeleteDialog by remember { mutableStateOf(false) }
    val normalizedEntryDate = remember(entry.date) {
        listOf("dd.MM.yyyy", "dd-MM-yyyy", "yyyy-MM-dd").firstNotNullOfOrNull { pattern ->
            runCatching { LocalDate.parse(entry.date, DateTimeFormatter.ofPattern(pattern)) }.getOrNull()
        }
    }
    val isHighlightedOccurrenceRow =
        highlightedOccurrenceDate != null && normalizedEntryDate == highlightedOccurrenceDate
    val shouldBlinkMorningFoodCounter =
        isHighlightedOccurrenceRow && highlightedOccurrenceTimeOfDay == "morning"
    val shouldBlinkAfternoonFoodCounter =
        isHighlightedOccurrenceRow && highlightedOccurrenceTimeOfDay == "afternoon"
    val shouldBlinkEveningFoodCounter =
        isHighlightedOccurrenceRow && highlightedOccurrenceTimeOfDay == "evening"
    val shouldBlinkNightFoodCounter =
        isHighlightedOccurrenceRow && highlightedOccurrenceTimeOfDay == "night"
    
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .onGloballyPositioned { coordinates ->
                onMeasuredHeightPx?.invoke(coordinates.size.height)
            }
            .padding(horizontal = 4.dp, vertical = 2.dp),
        shape = RoundedCornerShape(8.dp),
        colors = CardDefaults.cardColors(containerColor = backgroundColor),
        elevation = CardDefaults.cardElevation(defaultElevation = 1.dp),
        border = if (entry.isTestData) {
            BorderStroke(3.dp, Color(0xFF00BCD4)) // Cyan border for test data
        } else null
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(4.dp)
        ) {
            // Date Column with delete functionality
            Row(
                modifier = Modifier.weight(1f)
            ) {
                val cellKey = entryIndex to "date"
                val focusRequester = focusRequesters.getOrPut(cellKey) { FocusRequester() }
                val cellValue = cellTextFieldValues.getOrPut(cellKey) { TextFieldValue(entry.date) }
                EditableTableCell(
                    value = cellValue,
                    onValueChange = { 
                        cellTextFieldValues[cellKey] = it
                        // Auto-save when text changes
                        if (it.text != entry.date) {
                            onEntryChanged(entryIndex, entry.copy(date = it.text))
                        }
                    },
                    modifier = Modifier.weight(1f),
                    isDateCell = true,
                    fontColor = fontColor,
                    gridColor = gridColor,
                    onDelete = { onDeleteEntry(entryIndex) },
                    isFocused = focusedCell == cellKey,
                    focusRequester = focusRequester,
                    onRequestFocus = { onRequestFocus(cellKey) },
                    onDateClick = { },
                    foodPresets = foodPresets,
                    setFoodPresets = setFoodPresets,
                    currentCellFoodItems = emptyList(),
                    onCurrentCellFoodItemsChange = { },
                    scale = scale,
                    heightScale = heightScale,
                    selectedLanguage = selectedLanguage,
                    currentEntry = entry,
                    onEntryUpdate = { updatedEntry ->
                        onEntryChanged(entryIndex, updatedEntry)
                    },
                    customMarkers = customMarkers,
                    onCustomMarkersUpdate = onCustomMarkersUpdate,
                    markerCellId = "date", // Unique identifier for date cell markers
                    foodWarningMessage = foodWarningMessage,
                    pendingFoodAction = pendingFoodAction,
                    showFoodWarning = showFoodWarning,
                    onFoodWarningChange = onFoodWarningChange,
                    onFoodWarningMessageChange = onFoodWarningMessageChange,
                    onPendingFoodActionChange = onPendingFoodActionChange,
                    onWarningFoodNameChange = onWarningFoodNameChange,
                    context = context
                )
            }
            
            // Blood Sugar Values
            Row(
                modifier = Modifier
                    .weight(3f)
                    .padding(horizontal = 4.dp),
                horizontalArrangement = Arrangement.SpaceEvenly
            ) {
                val cellKey = entryIndex to "morningBloodSugarLevel"
                val focusRequester = focusRequesters.getOrPut(cellKey) { FocusRequester() }
                val cellValue = cellTextFieldValues.getOrPut(cellKey) { TextFieldValue(entry.morningBloodSugarLevel) }
                EditableTableCell(
                    value = cellValue,
                    onValueChange = { 
                        cellTextFieldValues[cellKey] = it
                        onEntryChanged(entryIndex, entry.copy(morningBloodSugarLevel = it.text))
                        // Clear confirmation for this cell when value changes
                        onClearConfirmation?.invoke("${entryIndex}_morningBloodSugar")
                    },
                    modifier = Modifier.weight(1f),
                    hint = "0",
                    isDateCell = false,
                    isFoodCell = true,
                    isSecured = isSecured,
                    cellKey = "${entryIndex}_morningBloodSugar",
                    confirmedEditingSessions = confirmedEditingSessions,
                    onShowEditConfirmDialog = onShowEditConfirmDialog,
                    fontColor = fontColor,
                    gridColor = gridColor,
                    isFocused = (focusedCell == cellKey),
                    focusRequester = focusRequester,
                    onRequestFocus = { onRequestFocus(cellKey) },
                    foodPresets = foodPresets,
                    setFoodPresets = setFoodPresets,
                    currentCellFoodItems = entry.foodEntriesByColumn["morningBloodSugarLevel"] ?: emptyList(),
                    onCurrentCellFoodItemsChange = { updatedItems ->
                        val updatedEntry = entry.copy(
                            foodEntriesByColumn = entry.foodEntriesByColumn.toMutableMap().apply {
                                this["morningBloodSugarLevel"] = updatedItems
                            }
                        )
                        onEntryChanged(entryIndex, updatedEntry)
                    },
                    scale = scale,
                    heightScale = heightScale,
                    selectedLanguage = selectedLanguage,
                    currentEntry = entry,
                    onEntryUpdate = { updatedEntry -> onEntryChanged(entryIndex, updatedEntry) },
                    timeOfDay = "morning",
                    shouldBlinkFoodCounter = shouldBlinkMorningFoodCounter,
                    foodBlinkTriggerToken = occurrenceHighlightToken,
                    customMarkers = customMarkers,
                    onCustomMarkersUpdate = onCustomMarkersUpdate,
                    foodWarningMessage = foodWarningMessage,
                    pendingFoodAction = pendingFoodAction,
                    showFoodWarning = showFoodWarning,
                    onFoodWarningChange = onFoodWarningChange,
                    onFoodWarningMessageChange = onFoodWarningMessageChange,
                    onPendingFoodActionChange = onPendingFoodActionChange,
                    onWarningFoodNameChange = onWarningFoodNameChange,
                    context = context
                )
                val cellKey2 = entryIndex to "afternoonBloodSugarLevel"
                val focusRequester2 = focusRequesters.getOrPut(cellKey2) { FocusRequester() }
                val cellValue2 = cellTextFieldValues.getOrPut(cellKey2) { TextFieldValue(entry.afternoonBloodSugarLevel) }
                EditableTableCell(
                    value = cellValue2,
                    onValueChange = { 
                        cellTextFieldValues[cellKey2] = it
                        onEntryChanged(entryIndex, entry.copy(afternoonBloodSugarLevel = it.text))
                        // Clear confirmation for this cell when value changes
                        onClearConfirmation?.invoke("${entryIndex}_afternoonBloodSugar")
                    },
                    modifier = Modifier.weight(1f),
                    hint = "0",
                    isDateCell = false,
                    isFoodCell = true,
                    isSecured = isSecured,
                    cellKey = "${entryIndex}_afternoonBloodSugar",
                    confirmedEditingSessions = confirmedEditingSessions,
                    onShowEditConfirmDialog = onShowEditConfirmDialog,
                    fontColor = fontColor,
                    gridColor = gridColor,
                    isFocused = (focusedCell == cellKey2),
                    focusRequester = focusRequester2,
                    onRequestFocus = { onRequestFocus(cellKey2) },
                    foodPresets = foodPresets,
                    setFoodPresets = setFoodPresets,
                    currentCellFoodItems = entry.foodEntriesByColumn["afternoonBloodSugarLevel"] ?: emptyList(),
                    onCurrentCellFoodItemsChange = { newFoodItemsForCell -> 
                        val updatedFoodMap = entry.foodEntriesByColumn + ("afternoonBloodSugarLevel" to newFoodItemsForCell)
                        onEntryChanged(entryIndex, entry.copy(foodEntriesByColumn = updatedFoodMap))
                    },
                    scale = scale,
                    heightScale = heightScale,
                    selectedLanguage = selectedLanguage,
                    currentEntry = entry,
                    onEntryUpdate = { updatedEntry -> onEntryChanged(entryIndex, updatedEntry) },
                    timeOfDay = "afternoon",
                    shouldBlinkFoodCounter = shouldBlinkAfternoonFoodCounter,
                    foodBlinkTriggerToken = occurrenceHighlightToken,
                    customMarkers = customMarkers,
                    onCustomMarkersUpdate = onCustomMarkersUpdate,
                    foodWarningMessage = foodWarningMessage,
                    pendingFoodAction = pendingFoodAction,
                    showFoodWarning = showFoodWarning,
                    onFoodWarningChange = onFoodWarningChange,
                    onFoodWarningMessageChange = onFoodWarningMessageChange,
                    onPendingFoodActionChange = onPendingFoodActionChange,
                    onWarningFoodNameChange = onWarningFoodNameChange,
                    context = context
                )
                val cellKey3 = entryIndex to "eveningBloodSugarLevel"
                val focusRequester3 = focusRequesters.getOrPut(cellKey3) { FocusRequester() }
                val cellValue3 = cellTextFieldValues.getOrPut(cellKey3) { TextFieldValue(entry.eveningBloodSugarLevel) }
                EditableTableCell(
                    value = cellValue3,
                    onValueChange = { 
                        cellTextFieldValues[cellKey3] = it
                        onEntryChanged(entryIndex, entry.copy(eveningBloodSugarLevel = it.text))
                        // Clear confirmation for this cell when value changes
                        onClearConfirmation?.invoke("${entryIndex}_eveningBloodSugar")
                    },
                    modifier = Modifier.weight(1f),
                    hint = "0",
                    isDateCell = false,
                    isFoodCell = true,
                    isSecured = isSecured,
                    cellKey = "${entryIndex}_eveningBloodSugar",
                    confirmedEditingSessions = confirmedEditingSessions,
                    onShowEditConfirmDialog = onShowEditConfirmDialog,
                    fontColor = fontColor,
                    gridColor = gridColor,
                    isFocused = (focusedCell == cellKey3),
                    focusRequester = focusRequester3,
                    onRequestFocus = { onRequestFocus(cellKey3) },
                    foodPresets = foodPresets,
                    setFoodPresets = setFoodPresets,
                    currentCellFoodItems = entry.foodEntriesByColumn["eveningBloodSugarLevel"] ?: emptyList(),
                    onCurrentCellFoodItemsChange = { newFoodItemsForCell -> 
                        val updatedFoodMap = entry.foodEntriesByColumn + ("eveningBloodSugarLevel" to newFoodItemsForCell)
                        onEntryChanged(entryIndex, entry.copy(foodEntriesByColumn = updatedFoodMap))
                    },
                    scale = scale,
                    heightScale = heightScale,
                    selectedLanguage = selectedLanguage,
                    currentEntry = entry,
                    onEntryUpdate = { updatedEntry -> onEntryChanged(entryIndex, updatedEntry) },
                    timeOfDay = "evening",
                    shouldBlinkFoodCounter = shouldBlinkEveningFoodCounter,
                    foodBlinkTriggerToken = occurrenceHighlightToken,
                    customMarkers = customMarkers,
                    onCustomMarkersUpdate = onCustomMarkersUpdate,
                    foodWarningMessage = foodWarningMessage,
                    pendingFoodAction = pendingFoodAction,
                    showFoodWarning = showFoodWarning,
                    onFoodWarningChange = onFoodWarningChange,
                    onFoodWarningMessageChange = onFoodWarningMessageChange,
                    onPendingFoodActionChange = onPendingFoodActionChange,
                    onWarningFoodNameChange = onWarningFoodNameChange,
                    context = context
                )
                val cellKey4 = entryIndex to "nightBloodSugarLevel"
                val focusRequester4 = focusRequesters.getOrPut(cellKey4) { FocusRequester() }
                val cellValue4 = cellTextFieldValues.getOrPut(cellKey4) { TextFieldValue(entry.nightBloodSugarLevel) }
                EditableTableCell(
