                    onFoodWarningMessageChange = onFoodWarningMessageChange,
                    onPendingFoodActionChange = onPendingFoodActionChange,
                    onWarningFoodNameChange = onWarningFoodNameChange,
                    context = context
                )
            }
            
            // Insulin Values
            Row(
                modifier = Modifier
                    .weight(2.2f)
                    .padding(horizontal = 4.dp)
                    .background(
                        color = insulinColumnColor,
                        shape = RoundedCornerShape(8.dp)
                    ),
                horizontalArrangement = Arrangement.SpaceEvenly
            ) {
                val cellKey = entryIndex to "morningInsulin"
                val focusRequester = focusRequesters.getOrPut(cellKey) { FocusRequester() }
                val cellValue = cellTextFieldValues.getOrPut(cellKey) { TextFieldValue(entry.morningInsulin) }
                EditableTableCell(
                    value = cellValue,
                    onValueChange = { 
                        cellTextFieldValues[cellKey] = it
                        onEntryChanged(entryIndex, entry.copy(morningInsulin = it.text))
                        // Clear confirmation for this cell when value changes
                        onClearConfirmation?.invoke("${entryIndex}_morningInsulin")
                    },
                    modifier = Modifier.weight(1f),
                    hint = "0",
                    isDateCell = false,
                    isFoodCell = true,
                    isInsulinCell = true,
                    isSecured = isSecured,
                    cellKey = "${entryIndex}_morningInsulin",
                    confirmedEditingSessions = confirmedEditingSessions,
                    onShowEditConfirmDialog = onShowEditConfirmDialog,
                    fontColor = fontColor,
                    gridColor = gridColor,
                    isFocused = (focusedCell == cellKey),
                    focusRequester = focusRequester,
                    onRequestFocus = { onRequestFocus(cellKey) },
                    foodPresets = foodPresets,
                    setFoodPresets = setFoodPresets,
                    currentCellFoodItems = entry.foodEntriesByColumn["morningInsulin"] ?: emptyList(),
                    onCurrentCellFoodItemsChange = { newFoodItemsForCell -> 
                        val updatedFoodMap = entry.foodEntriesByColumn + ("morningInsulin" to newFoodItemsForCell)
                        onEntryChanged(entryIndex, entry.copy(foodEntriesByColumn = updatedFoodMap))
                    },
                    scale = scale,
                    heightScale = heightScale,
                    selectedLanguage = selectedLanguage,
                    currentEntry = entry,
                    onEntryUpdate = { updatedEntry -> onEntryChanged(entryIndex, updatedEntry) },
                    timeOfDay = "morning",
                    shouldBlinkFoodCounter = shouldBlinkMorningFoodCounter,
                    foodBlinkTriggerToken = occurrenceHighlightToken,
                    customMarkers = customMarkers,
                    onCustomMarkersUpdate = onCustomMarkersUpdate,
                    foodWarningMessage = foodWarningMessage,
                    pendingFoodAction = pendingFoodAction,
                    showFoodWarning = showFoodWarning,
                    onFoodWarningChange = onFoodWarningChange,
                    onFoodWarningMessageChange = onFoodWarningMessageChange,
                    onPendingFoodActionChange = onPendingFoodActionChange,
                    onWarningFoodNameChange = onWarningFoodNameChange,
                    context = context
                )
                val cellKey2 = entryIndex to "afternoonInsulin"
                val focusRequester2 = focusRequesters.getOrPut(cellKey2) { FocusRequester() }
                val cellValue2 = cellTextFieldValues.getOrPut(cellKey2) { TextFieldValue(entry.afternoonInsulin) }
                EditableTableCell(
                    value = cellValue2,
                    onValueChange = { 
                        cellTextFieldValues[cellKey2] = it
                        onEntryChanged(entryIndex, entry.copy(afternoonInsulin = it.text))
                        // Clear confirmation for this cell when value changes
                        onClearConfirmation?.invoke("${entryIndex}_afternoonInsulin")
                    },
                    modifier = Modifier.weight(1f),
                    hint = "0",
                    isDateCell = false,
                    isFoodCell = true,
                    isInsulinCell = true,
                    isSecured = isSecured,
                    cellKey = "${entryIndex}_afternoonInsulin",
                    confirmedEditingSessions = confirmedEditingSessions,
                    onShowEditConfirmDialog = onShowEditConfirmDialog,
                    fontColor = fontColor,
                    gridColor = gridColor,
                    isFocused = (focusedCell == cellKey2),
                    focusRequester = focusRequester2,
                    onRequestFocus = { onRequestFocus(cellKey2) },
                    foodPresets = foodPresets,
                    setFoodPresets = setFoodPresets,
                    currentCellFoodItems = entry.foodEntriesByColumn["afternoonInsulin"] ?: emptyList(),
                    onCurrentCellFoodItemsChange = { newFoodItemsForCell -> 
                        val updatedFoodMap = entry.foodEntriesByColumn + ("afternoonInsulin" to newFoodItemsForCell)
                        onEntryChanged(entryIndex, entry.copy(foodEntriesByColumn = updatedFoodMap))
                    },
                    scale = scale,
                    heightScale = heightScale,
                    selectedLanguage = selectedLanguage,
                    currentEntry = entry,
                    onEntryUpdate = { updatedEntry -> onEntryChanged(entryIndex, updatedEntry) },
                    timeOfDay = "afternoon",
                    shouldBlinkFoodCounter = shouldBlinkAfternoonFoodCounter,
                    foodBlinkTriggerToken = occurrenceHighlightToken,
                    customMarkers = customMarkers,
                    onCustomMarkersUpdate = onCustomMarkersUpdate,
                    foodWarningMessage = foodWarningMessage,
                    pendingFoodAction = pendingFoodAction,
                    showFoodWarning = showFoodWarning,
                    onFoodWarningChange = onFoodWarningChange,
                    onFoodWarningMessageChange = onFoodWarningMessageChange,
                    onPendingFoodActionChange = onPendingFoodActionChange,
                    onWarningFoodNameChange = onWarningFoodNameChange,
                    context = context
                )
                val cellKey3 = entryIndex to "eveningInsulin"
                val focusRequester3 = focusRequesters.getOrPut(cellKey3) { FocusRequester() }
                val cellValue3 = cellTextFieldValues.getOrPut(cellKey3) { TextFieldValue(entry.eveningInsulin) }
                EditableTableCell(
                    value = cellValue3,
                    onValueChange = { 
                        cellTextFieldValues[cellKey3] = it
                        onEntryChanged(entryIndex, entry.copy(eveningInsulin = it.text))
                        // Clear confirmation for this cell when value changes
                        onClearConfirmation?.invoke("${entryIndex}_eveningInsulin")
                    },
                    modifier = Modifier.weight(1f),
                    hint = "0",
                    isDateCell = false,
                    isFoodCell = true,
                    isInsulinCell = true,
                    isSecured = isSecured,
                    cellKey = "${entryIndex}_eveningInsulin",
                    confirmedEditingSessions = confirmedEditingSessions,
                    onShowEditConfirmDialog = onShowEditConfirmDialog,
                    fontColor = fontColor,
                    gridColor = gridColor,
                    isFocused = (focusedCell == cellKey3),
                    focusRequester = focusRequester3,
                    onRequestFocus = { onRequestFocus(cellKey3) },
                    foodPresets = foodPresets,
                    setFoodPresets = setFoodPresets,
                    currentCellFoodItems = entry.foodEntriesByColumn["eveningInsulin"] ?: emptyList(),
                    onCurrentCellFoodItemsChange = { newFoodItemsForCell -> 
                        val updatedFoodMap = entry.foodEntriesByColumn + ("eveningInsulin" to newFoodItemsForCell)
                        onEntryChanged(entryIndex, entry.copy(foodEntriesByColumn = updatedFoodMap))
                    },
                    scale = scale,
                    heightScale = heightScale,
                    selectedLanguage = selectedLanguage,
                    currentEntry = entry,
                    onEntryUpdate = { updatedEntry -> onEntryChanged(entryIndex, updatedEntry) },
                    timeOfDay = "evening",
                    shouldBlinkFoodCounter = shouldBlinkEveningFoodCounter,
                    foodBlinkTriggerToken = occurrenceHighlightToken,
                    customMarkers = customMarkers,
                    onCustomMarkersUpdate = onCustomMarkersUpdate,
                    foodWarningMessage = foodWarningMessage,
                    pendingFoodAction = pendingFoodAction,
                    showFoodWarning = showFoodWarning,
                    onFoodWarningChange = onFoodWarningChange,
                    onFoodWarningMessageChange = onFoodWarningMessageChange,
                    onPendingFoodActionChange = onPendingFoodActionChange,
                    onWarningFoodNameChange = onWarningFoodNameChange,
                    context = context
                )
            }
            
            // Custom Columns (including Remarks which is now a built-in custom column)
            customColumns.forEach { column ->
                // Special handling for Remarks column - use entry.remarks for backward compatibility
                val isRemarksColumn = column.id == CustomColumnManager.REMARKS_COLUMN_ID
                val columnWeight = if (isRemarksColumn) 1.5f else 1f
                val customCellKey = entryIndex to column.id
                val customFocusRequester = focusRequesters.getOrPut(customCellKey) { FocusRequester() }
                
                // For Remarks column, use entry.remarks; for others, use customColumnData
                val cellValue = if (isRemarksColumn) entry.remarks else (entry.customColumnData[column.id] ?: "")
                val customTextFieldValue = cellTextFieldValues.getOrPut(customCellKey) { 
                    TextFieldValue(cellValue) 
                }
                
                var showExpandedDialog by remember { mutableStateOf(false) }
                var expandedText by remember { mutableStateOf(customTextFieldValue) }
                
                // Show expanded dialog when cell gains focus for text-type fields
                LaunchedEffect(focusedCell) {
                    if (column.showExpandedTextArea && column.keyboardType == "text" && focusedCell == customCellKey) {
                        showExpandedDialog = true
                        expandedText = customTextFieldValue
                    }
                }
                
                EditableTableCell(
                    value = customTextFieldValue,
                    onValueChange = { newValue ->
                        cellTextFieldValues[customCellKey] = newValue
                        // For Remarks column, update entry.remarks; for others, update customColumnData
                        if (isRemarksColumn) {
                            onEntryChanged(entryIndex, entry.copy(remarks = newValue.text))
                        } else {
                            val updatedCustomData = entry.customColumnData + (column.id to newValue.text)
                            onEntryChanged(entryIndex, entry.copy(customColumnData = updatedCustomData))
                        }
                        // Clear confirmation for this cell when value changes
                        onClearConfirmation?.invoke("${entryIndex}_${column.id}")
                    },
                    modifier = Modifier.weight(columnWeight),
                    hint = "",
                    isDateCell = false,
                    isFoodCell = false,
                    isInsulinCell = false,
                    isSecured = isSecured,
                    cellKey = "${entryIndex}_${column.id}",
                    confirmedEditingSessions = confirmedEditingSessions,
                    onShowEditConfirmDialog = onShowEditConfirmDialog,
                    fontColor = fontColor,
                    gridColor = gridColor,
                    isFocused = focusedCell == customCellKey,
                    focusRequester = customFocusRequester,
                    onRequestFocus = { onRequestFocus(customCellKey) },
                    scale = scale,
                    heightScale = heightScale,
                    foodPresets = foodPresets,
                    setFoodPresets = setFoodPresets,
                    currentCellFoodItems = emptyList(), // Custom columns don't have food items
                    onCurrentCellFoodItemsChange = { },
                    selectedLanguage = selectedLanguage,
                    customKeyboardType = column.keyboardType,
                    customMarkers = customMarkers,
                    onCustomMarkersUpdate = onCustomMarkersUpdate,
                    currentEntry = entry,
                    onEntryUpdate = { updatedEntry ->
                        onEntryChanged(entryIndex, updatedEntry)
                    },
                    markerCellId = column.id, // Use column ID as unique identifier for markers
                    foodWarningMessage = foodWarningMessage,
                    pendingFoodAction = pendingFoodAction,
                    showFoodWarning = showFoodWarning,
                    onFoodWarningChange = onFoodWarningChange,
                    onFoodWarningMessageChange = onFoodWarningMessageChange,
                    onPendingFoodActionChange = onPendingFoodActionChange,
                    onWarningFoodNameChange = onWarningFoodNameChange,
                    context = context
                )
                
                // Expanded Text Area Dialog
                if (showExpandedDialog) {
                    Dialog(
                        onDismissRequest = {
                            // Save changes when closing
                            cellTextFieldValues[customCellKey] = expandedText
                            // For Remarks column, update entry.remarks; for others, update customColumnData
                            if (isRemarksColumn) {
                                onEntryChanged(entryIndex, entry.copy(remarks = expandedText.text))
                            } else {
                                val updatedCustomData = entry.customColumnData + (column.id to expandedText.text)
                                onEntryChanged(entryIndex, entry.copy(customColumnData = updatedCustomData))
                            }
                            keyboardController?.hide()
                            focusManager.clearFocus(force = true)
                            showExpandedDialog = false
                        },
                        properties = DialogProperties(
                            usePlatformDefaultWidth = false
                        )
                    ) {
                        Card(
                            modifier = Modifier
                                .fillMaxWidth(0.9f)
                                .wrapContentHeight()
                                .padding(16.dp),
                            shape = RoundedCornerShape(20.dp),
                            colors = CardDefaults.cardColors(
                                containerColor = MaterialTheme.colorScheme.surfaceVariant
                            ),
                            elevation = CardDefaults.cardElevation(defaultElevation = 8.dp)
                        ) {
                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(24.dp)
                            ) {
                                // Title
                                Text(
                                    text = column.name + if (column.unit.isNotEmpty()) " (${column.unit})" else "",
                                    style = MaterialTheme.typography.titleLarge,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                                
                                Spacer(modifier = Modifier.height(16.dp))
                                
                                // Text Field with distinct background
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(12.dp),
                                    colors = CardDefaults.cardColors(
                                        containerColor = MaterialTheme.colorScheme.surface
                                    ),
                                    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
                                ) {
                                    OutlinedTextField(
                                        value = expandedText,
                                        onValueChange = { expandedText = it },
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .heightIn(min = 120.dp, max = 300.dp)
                                            .padding(8.dp),
                                        textStyle = TextStyle(
                                            color = MaterialTheme.colorScheme.onSurface,
                                            fontSize = 16.sp
                                        ),
                                        colors = OutlinedTextFieldDefaults.colors(
                                            focusedBorderColor = MaterialTheme.colorScheme.primary,
                                            unfocusedBorderColor = MaterialTheme.colorScheme.outline.copy(alpha = 0.5f),
                                            cursorColor = MaterialTheme.colorScheme.primary,
                                            focusedContainerColor = MaterialTheme.colorScheme.surface,
                                            unfocusedContainerColor = MaterialTheme.colorScheme.surface
                                        ),
                                        maxLines = 10,
                                        keyboardOptions = KeyboardOptions(
                                            keyboardType = if (column.keyboardType == "number") KeyboardType.Decimal else KeyboardType.Text,
                                            imeAction = ImeAction.Done
                                        )
                                    )
                                }
                                
                                Spacer(modifier = Modifier.height(16.dp))
                                
                                // Close Button
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.End
                                ) {
                                    TextButton(
                                        onClick = {
                                            // Save changes
                                            cellTextFieldValues[customCellKey] = expandedText
                                            if (isRemarksColumn) {
                                                onEntryChanged(entryIndex, entry.copy(remarks = expandedText.text))
                                            } else {
                                                val updatedCustomData = entry.customColumnData + (column.id to expandedText.text)
                                                onEntryChanged(entryIndex, entry.copy(customColumnData = updatedCustomData))
                                            }
                                            keyboardController?.hide()
                                            focusManager.clearFocus(force = true)
                                            showExpandedDialog = false
                                        }
                                    ) {
                                        Text(
                                            text = when (selectedLanguage) {
                                                "German" -> "Fertig"
                                                "Spanish" -> "Listo"
                                                else -> "Done"
                                            }
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    if (showDeleteDialog) {
        AlertDialog(
            onDismissRequest = { showDeleteDialog = false },
            title = { Text(stringResource(R.string.delete_entry)) },
            text = { Text(stringResource(R.string.delete_entry_confirmation)) },
            confirmButton = {
                TextButton(
                    onClick = {
                        onDeleteEntry(entryIndex)
                        showDeleteDialog = false
                    }
                ) {
                    Text(stringResource(R.string.delete), color = MaterialTheme.colorScheme.error)
                }
            },
            dismissButton = {
                TextButton(onClick = { showDeleteDialog = false }) {
                    Text(stringResource(R.string.cancel))
                }
            }
        )
    }
}

// Helper function to create localized context
fun createLocalizedContext(context: Context, language: String): Context {
    val locale = when (language) {
        "German" -> java.util.Locale("de")
        "Spanish" -> java.util.Locale("es")
        else -> java.util.Locale("en")
    }
    val config = Configuration(context.resources.configuration)
    config.setLocale(locale)
    return context.createConfigurationContext(config)
}

// Helper function to calculate dynamic column widths based on text length
fun calculateColumnWidths(headers: List<String>, availableWidth: Float, paint: Paint): Pair<FloatArray, FloatArray> {
    // Measure text width for each header
    val headerWidths = headers.mapIndexed { index, header ->
        val baseWidth = paint.measureText(header) + 30f // Add padding
        // Give Date column (index 0) extra width for better spacing
        if (index == 0) baseWidth * 1.5f else baseWidth
    }
    
    val totalTextWidth = headerWidths.sum()
    
    // Calculate proportional widths
    val widths = FloatArray(headers.size) { index ->
        val proportion = headerWidths[index] / totalTextWidth
        (proportion * availableWidth).coerceAtLeast(40f) // Minimum width of 40f
    }
    
    // Adjust if total exceeds available width
    val totalCalculatedWidth = widths.sum()
    if (totalCalculatedWidth > availableWidth) {
        val scaleFactor = availableWidth / totalCalculatedWidth
        for (i in widths.indices) {
            widths[i] *= scaleFactor
        }
    }
    
    // Calculate positions
    val positions = FloatArray(headers.size)
    var currentPos = 30f // Left margin
    for (i in headers.indices) {
        positions[i] = currentPos
        currentPos += widths[i]
    }
    
    return Pair(widths, positions)
}

// Helper function to create PDF document
fun createPDFDocument(validEntries: List<DiabetesEntry>, language: String, context: Context): PdfDocument {
    val pdfDocument = PdfDocument()
    // Use landscape orientation for better column fit
    val pageWidth = 842 // A4 height in points (landscape)
    val pageHeight = 595 // A4 width in points (landscape)
    
    // Get labels based on language (using shorter headers for better fit)
    val labels = when (language) {
        "German" -> mapOf(
            "title" to "Diabetes Tracker - Datenexport",
            "date" to "Datum",
            "morning" to "Morgen",
            "afternoon" to "Mittag",
            "evening" to "Abend",
            "night" to "Nacht",
            "morningInsulin" to "Ins. Morgen",
            "afternoonInsulin" to "Ins. Mittag",
            "eveningInsulin" to "Ins. Abend",
            "remarks" to "Bemerkungen"
        )
        "Spanish" -> mapOf(
            "title" to "Diabetes Tracker - Exportación de Datos",
            "date" to "Fecha",
            "morning" to "Mañana",
            "afternoon" to "Mediodía",
            "evening" to "Tarde",
            "night" to "Noche",
            "morningInsulin" to "Ins. Mañana",
            "afternoonInsulin" to "Ins. Mediodía",
            "eveningInsulin" to "Ins. Tarde",
            "remarks" to "Notas"
        )
        else -> mapOf(
            "title" to "Diabetes Tracker - Data Export",
            "date" to "Date",
            "morning" to "Morning",
            "afternoon" to "Afternoon",
            "evening" to "Evening",
            "night" to "Night",
            "morningInsulin" to "Morn. Ins.",
            "afternoonInsulin" to "Aftn. Ins.",
            "eveningInsulin" to "Even. Ins.",
            "remarks" to "Remarks"
        )
    }
    
    // Calculate pages needed (entries per page)
    val entriesPerPage = 25
    val totalPages = (validEntries.size + entriesPerPage - 1) / entriesPerPage
    
    for (pageNum in 0 until totalPages) {
        val pageInfo = PdfDocument.PageInfo.Builder(pageWidth, pageHeight, pageNum + 1).create()
        val page = pdfDocument.startPage(pageInfo)
        val canvas = page.canvas
        
        // Paint objects
        val titlePaint = Paint().apply {
            textSize = 18f
            typeface = Typeface.create(Typeface.DEFAULT, Typeface.BOLD)
            color = android.graphics.Color.BLACK
        }
        
        val dataPaint = Paint().apply {
            textSize = 9f
            typeface = Typeface.create(Typeface.DEFAULT, Typeface.NORMAL)
            color = android.graphics.Color.BLACK
        }
        
        val linePaint = Paint().apply {
            color = android.graphics.Color.BLACK
            strokeWidth = 1f
        }
        
        // Draw title
        canvas.drawText(labels["title"] ?: "Diabetes Tracker", 50f, 50f, titlePaint)
        
        // Get custom columns
        val customColumns = CustomColumnManager.getCustomColumns(context)
        
        // Create dynamic headers list
        val basicHeaders = listOf(
            labels["date"] ?: "Date",
            labels["morning"] ?: "Morning",
            labels["afternoon"] ?: "Afternoon", 
            labels["evening"] ?: "Evening",
            labels["night"] ?: "Night",
            labels["morningInsulin"] ?: "M.Ins",
            labels["afternoonInsulin"] ?: "A.Ins",
            labels["eveningInsulin"] ?: "E.Ins",
            labels["remarks"] ?: "Remarks"
        )
        
        val customHeaders = customColumns.map { column ->
            if (column.unit.isNotEmpty()) {
                "${column.name.take(8)} (${column.unit})" // Truncate for PDF space
            } else {
                column.name.take(10) // Truncate for PDF space
            }
        }
        
        val allHeaders = basicHeaders + customHeaders
        
        // Calculate dynamic column positions based on header text length
        val leftMargin = 30f
        val rightMargin = 30f
        val availableWidth = pageWidth - leftMargin - rightMargin
        
        // Create header paint for text measurement
        val headerPaint = Paint().apply {
            color = android.graphics.Color.BLACK
            textSize = 10f
            typeface = android.graphics.Typeface.DEFAULT_BOLD
        }
        
        val (columnWidths, colPositions) = calculateColumnWidths(allHeaders, availableWidth, headerPaint)
        
        // Draw table headers
        val startY = 100f
        val rowHeight = 25f
        
        // Draw header row
        allHeaders.forEachIndexed { index, header ->
            canvas.drawText(header, colPositions[index], startY, headerPaint)
        }
        
        // Draw horizontal line under header
        canvas.drawLine(leftMargin, startY + 10f, pageWidth - rightMargin, startY + 10f, linePaint)
        
        // Draw data rows
        val startIndex = pageNum * entriesPerPage
        val endIndex = minOf(startIndex + entriesPerPage, validEntries.size)
        
        for (i in startIndex until endIndex) {
            val entry = validEntries[i]
            val rowY = startY + ((i - startIndex + 1) * rowHeight) + 15f
            
            // Format date
            val formattedDate = if (entry.date.isNotBlank()) {
                try {
                    val date = LocalDate.parse(entry.date)
                    date.format(java.time.format.DateTimeFormatter.ofPattern("dd.MM.yy"))
                } catch (e: Exception) {
                    entry.date
                }
            } else ""
            
            // Create data row with basic data + custom column data
            val basicData = listOf(
                formattedDate,
                entry.morningBloodSugarLevel,
                entry.afternoonBloodSugarLevel,
                entry.eveningBloodSugarLevel,
                entry.nightBloodSugarLevel,
                entry.morningInsulin,
                entry.afternoonInsulin,
                entry.eveningInsulin,
                if (entry.remarks.length > 15) entry.remarks.take(12) + "..." else entry.remarks
            )
            
            val customData = customColumns.map { column ->
                val value = entry.customColumnData[column.id] ?: ""
                if (value.length > 10) value.take(8) + "..." else value // Truncate for PDF space
            }
            
            val allData = basicData + customData
            
            // Draw all data columns
            allData.forEachIndexed { index, data ->
                canvas.drawText(data, colPositions[index], rowY, dataPaint)
            }
        }
        
        // Draw page number
        canvas.drawText("Page ${pageNum + 1} of $totalPages", pageWidth - 150f, pageHeight - 30f, dataPaint)
        
        pdfDocument.finishPage(page)
    }
    
    return pdfDocument
}

// Helper function to create chart-only PDF document
fun createChartPDFDocument(validEntries: List<DiabetesEntry>, language: String, context: Context, chartType: String): PdfDocument {
    val pdfDocument = PdfDocument()
    val pageWidth = 842 // A4 landscape
    val pageHeight = 595
    
    val pageInfo = PdfDocument.PageInfo.Builder(pageWidth, pageHeight, 1).create()
    val page = pdfDocument.startPage(pageInfo)
    val canvas = page.canvas
    
    // Paint objects
    val titlePaint = Paint().apply {
        color = android.graphics.Color.BLACK
        textSize = 18f
        typeface = android.graphics.Typeface.DEFAULT_BOLD
    }
    
    val textPaint = Paint().apply {
        color = android.graphics.Color.BLACK
        textSize = 12f
    }
    
    val axisPaint = Paint().apply {
        color = android.graphics.Color.BLACK
        strokeWidth = 2f
    }
    
    val linePaint = Paint().apply {
        color = android.graphics.Color.BLUE
        strokeWidth = 3f
        style = Paint.Style.STROKE
    }
    
    val gridPaint = Paint().apply {
        color = android.graphics.Color.LTGRAY
        strokeWidth = 1f
    }
    
    // Get chart data and labels
    val (chartData, chartLabel, yAxisLabel) = getChartData(validEntries, chartType, context)
    
    if (chartData.isEmpty()) {
        // No data to chart
        canvas.drawText("Diabetes Tracker - Chart Export", 50f, 50f, titlePaint)
        canvas.drawText("Chart Type: $chartLabel", 50f, 100f, textPaint)
        canvas.drawText("No data available for this chart type", 50f, 150f, textPaint)
        pdfDocument.finishPage(page)
        return pdfDocument
    }
    
    // Draw title
    canvas.drawText("Diabetes Tracker - $chartLabel", 50f, 50f, titlePaint)
    
    // Chart dimensions
    val chartLeft = 80f
    val chartTop = 100f
    val chartWidth = 650f
    val chartHeight = 350f
    val chartRight = chartLeft + chartWidth
    val chartBottom = chartTop + chartHeight
    
    // Draw chart axes
    canvas.drawLine(chartLeft, chartBottom, chartRight, chartBottom, axisPaint) // X-axis
    canvas.drawLine(chartLeft, chartTop, chartLeft, chartBottom, axisPaint) // Y-axis
    
    // Calculate data ranges
    val maxValue = chartData.maxOfOrNull { it.second } ?: 0f
    val minValue = chartData.minOfOrNull { it.second } ?: 0f
    val valueRange = maxValue - minValue
    val safeRange = if (valueRange == 0f) 1f else valueRange
    
    // Draw grid lines and labels
    val gridLines = 5
    for (i in 0..gridLines) {
        val y = chartBottom - (i * chartHeight / gridLines)
        val value = minValue + (i * safeRange / gridLines)
        
        // Grid line
        canvas.drawLine(chartLeft, y, chartRight, y, gridPaint)
        
        // Y-axis label
        canvas.drawText(String.format("%.1f", value), chartLeft - 40f, y + 5f, textPaint)
    }
    
    // Draw Y-axis label
    canvas.save()
    canvas.rotate(-90f, 30f, chartTop + chartHeight / 2)
    canvas.drawText(yAxisLabel, 30f, chartTop + chartHeight / 2, textPaint)
    canvas.restore()
    
    // Draw data points and lines
    if (chartData.size > 1) {
        val path = android.graphics.Path()
        var isFirstPoint = true
        
        chartData.forEachIndexed { index: Int, point: Pair<String, Float> ->
            val (date, value) = point
            val x = chartLeft + (index * chartWidth / (chartData.size - 1))
            val y = chartBottom - ((value - minValue) / safeRange * chartHeight)
            
            if (isFirstPoint) {
                path.moveTo(x, y)
                isFirstPoint = false
            } else {
                path.lineTo(x, y)
            }
            
            // Draw data point
            canvas.drawCircle(x, y, 4f, linePaint)
        }
        
        // Draw line connecting points
        canvas.drawPath(path, linePaint)
    }
    
    // Draw X-axis labels (dates)
    val maxLabels = 10 // Limit number of date labels to avoid crowding
    val labelStep = maxOf(1, chartData.size / maxLabels)
    
    chartData.forEachIndexed { index: Int, point: Pair<String, Float> ->
        val date = point.first
        if (index % labelStep == 0) {
            val x = chartLeft + (index * chartWidth / (chartData.size - 1))
            
            // Format date for display
            val displayDate = try {
                val parsedDate = java.time.LocalDate.parse(date)
                parsedDate.format(java.time.format.DateTimeFormatter.ofPattern("MM/dd"))
            } catch (e: Exception) {
                date.take(5) // Fallback to first 5 characters
            }
            
            // Draw horizontal date label
            canvas.drawText(displayDate, x, chartBottom + 20f, textPaint)
        }
    }
    
    // Draw X-axis label
    canvas.drawText("Date", chartLeft + chartWidth / 2, chartBottom + 80f, textPaint)
    
    pdfDocument.finishPage(page)
    return pdfDocument
}

// Helper function to extract chart data based on chart type
fun getChartData(entries: List<DiabetesEntry>, chartType: String, context: Context): Triple<List<Pair<String, Float>>, String, String> {
    val sortedEntries = entries.sortedBy { it.date }
    
    return when {
        chartType == "morning" -> {
            val data = sortedEntries.mapNotNull { entry ->
                val value = entry.morningBloodSugarLevel.toFloatOrNull()
                if (value != null) entry.date to value else null
            }
            Triple(data, "Morning Blood Sugar Chart", "Blood Sugar (mg/dL)")
        }
        
        chartType == "afternoon" -> {
            val data = sortedEntries.mapNotNull { entry ->
                val value = entry.afternoonBloodSugarLevel.toFloatOrNull()
                if (value != null) entry.date to value else null
            }
            Triple(data, "Afternoon Blood Sugar Chart", "Blood Sugar (mg/dL)")
        }
        
        chartType == "evening" -> {
            val data = sortedEntries.mapNotNull { entry ->
                val value = entry.eveningBloodSugarLevel.toFloatOrNull()
                if (value != null) entry.date to value else null
            }
            Triple(data, "Evening Blood Sugar Chart", "Blood Sugar (mg/dL)")
        }
        
        chartType == "night" -> {
            val data = sortedEntries.mapNotNull { entry ->
                val value = entry.nightBloodSugarLevel.toFloatOrNull()
                if (value != null) entry.date to value else null
            }
            Triple(data, "Night Blood Sugar Chart", "Blood Sugar (mg/dL)")
        }
        
        chartType == "average" -> {
            val data = sortedEntries.mapNotNull { entry ->
                val values = listOfNotNull(
                    entry.morningBloodSugarLevel.toFloatOrNull(),
                    entry.afternoonBloodSugarLevel.toFloatOrNull(),
                    entry.eveningBloodSugarLevel.toFloatOrNull(),
                    entry.nightBloodSugarLevel.toFloatOrNull()
                )
                if (values.isNotEmpty()) {
                    entry.date to values.average().toFloat()
                } else null
            }
            Triple(data, "Average Blood Sugar Chart", "Average Blood Sugar (mg/dL)")
        }
        
        chartType == "insulin_morning" -> {
            val data = sortedEntries.mapNotNull { entry ->
                val value = entry.morningInsulin.toFloatOrNull()
                if (value != null) entry.date to value else null
            }
            Triple(data, "Morning Insulin Chart", "Insulin Units")
        }
        
        chartType == "insulin_afternoon" -> {
            val data = sortedEntries.mapNotNull { entry ->
                val value = entry.afternoonInsulin.toFloatOrNull()
                if (value != null) entry.date to value else null
            }
            Triple(data, "Afternoon Insulin Chart", "Insulin Units")
        }
        
        chartType == "insulin_evening" -> {
            val data = sortedEntries.mapNotNull { entry ->
                val value = entry.eveningInsulin.toFloatOrNull()
                if (value != null) entry.date to value else null
            }
            Triple(data, "Evening Insulin Chart", "Insulin Units")
        }
        
        chartType.startsWith("custom_") -> {
            val columnId = chartType.removePrefix("custom_").trim()
            val customColumns = CustomColumnManager.getCustomColumns(context)
            val column = customColumns.find { it.id == columnId }
            
            if (column != null) {
                // Extract data specifically for this column ID
                val data = sortedEntries.mapNotNull { entry ->
                    // Ensure we're getting data for the correct column ID
                    val customData = entry.customColumnData[columnId]
                    if (customData != null && customData.isNotBlank()) {
                        // Handle comma-separated decimals (e.g., "1,5" → "1.5")
                        val normalizedData = customData.trim().replace(",", ".")
                        val value = normalizedData.toFloatOrNull()
                        if (value != null && !value.isNaN() && value.isFinite() && entry.date.isNotBlank()) {
                            entry.date to value
                        } else null
                    } else null
                }
                
                val yAxisLabel = if (column.unit.isNotEmpty()) {
                    "${column.name} (${column.unit})"
                } else {
                    column.name
                }
                
                // Use column name in chart title to make it clear which column is being shown
                if (data.isEmpty()) {
                    // Debug: Show why no data was found
                    val entriesWithData = sortedEntries.count { it.customColumnData.containsKey(columnId) }
                    val nonEmptyData = sortedEntries.count { 
                        val customData = it.customColumnData[columnId]
                        customData != null && customData.isNotBlank()
                    }
                    Triple(emptyList(), "${column.name} Chart (No Data: $entriesWithData entries have key, $nonEmptyData non-empty)", yAxisLabel)
                } else {
                    Triple(data, "${column.name} Chart", yAxisLabel)
                }
            } else {
                // Column not found - this helps debug ID mismatches
                val availableIds = customColumns.map { "${it.name}:${it.id}" }.joinToString(", ")
                Triple(emptyList(), "Column Not Found (Requested: $columnId, Available: $availableIds)", "Value")
            }
        }
        
        else -> Triple(emptyList(), "Unknown Chart", "Value")
    }
}

// Helper function to create combined table and chart PDF document
fun createCombinedPDFDocument(validEntries: List<DiabetesEntry>, language: String, context: Context, chartType: String): PdfDocument {
    val pdfDocument = PdfDocument()
    val pageWidth = 842 // A4 landscape
    val pageHeight = 595
    
    // Page 1: Chart
    val pageInfo1 = PdfDocument.PageInfo.Builder(pageWidth, pageHeight, 1).create()
    val page1 = pdfDocument.startPage(pageInfo1)
    val canvas1 = page1.canvas
    
    // Draw chart title
    val titlePaint = Paint().apply {
        color = android.graphics.Color.BLACK
        textSize = 18f
        typeface = android.graphics.Typeface.DEFAULT_BOLD
    }
    
    val (chartData, chartLabel, yAxisLabel) = getChartData(validEntries, chartType, context)
    
    if (chartData.isEmpty()) {
        canvas1.drawText("Diabetes Tracker - Chart Export", 50f, 50f, titlePaint)
        canvas1.drawText("Chart Type: $chartLabel", 50f, 100f, Paint().apply {
            color = android.graphics.Color.BLACK
            textSize = 12f
        })
        canvas1.drawText("No data available for this chart type", 50f, 150f, Paint().apply {
            color = android.graphics.Color.BLACK
            textSize = 12f
        })
    } else {
        canvas1.drawText("Diabetes Tracker - $chartLabel", 50f, 50f, titlePaint)
        drawChart(canvas1, chartData, chartLabel, yAxisLabel)
    }
    
    pdfDocument.finishPage(page1)
    
    // Pages 2+: Table data (using the same logic as createPDFDocument but with different page numbering)
    val customColumns = CustomColumnManager.getCustomColumns(context)
    
    // Get labels based on language
    val labels = when (language) {
        "German" -> mapOf(
            "title" to "Diabetes Tracker - Datenexport",
            "date" to "Datum",
            "morning" to "Morgen",
            "afternoon" to "Mittag",
            "evening" to "Abend",
            "night" to "Nacht",
            "morn_ins" to "Morg. Ins",
            "aft_ins" to "Mitt. Ins",
            "eve_ins" to "Abend Ins",
            "remarks" to "Bemerkungen"
        )
        "Spanish" -> mapOf(
            "title" to "Diabetes Tracker - Exportación de Datos",
            "date" to "Fecha",
            "morning" to "Mañana",
            "afternoon" to "Tarde",
            "evening" to "Noche",
            "night" to "Madrugada",
            "morn_ins" to "Ins. Mañ",
            "aft_ins" to "Ins. Tarde",
            "eve_ins" to "Ins. Noche",
            "remarks" to "Observaciones"
        )
        else -> mapOf(
            "title" to "Diabetes Tracker - Data Export",
            "date" to "Date",
            "morning" to "Morning",
            "afternoon" to "Afternoon",
            "evening" to "Evening",
            "night" to "Night",
            "morn_ins" to "Morn. Ins",
            "aft_ins" to "Aft. Ins",
            "eve_ins" to "Eve. Ins",
            "remarks" to "Remarks"
        )
    }
    
    // Create table headers
    val basicHeaders = listOf(
        labels["date"] ?: "Date",
        labels["morning"] ?: "Morning",
        labels["afternoon"] ?: "Afternoon",
        labels["evening"] ?: "Evening",
        labels["night"] ?: "Night",
        labels["morn_ins"] ?: "Morn. Ins",
        labels["aft_ins"] ?: "Aft. Ins",
        labels["eve_ins"] ?: "Eve. Ins",
        labels["remarks"] ?: "Remarks"
    )
    
    val customHeaders = customColumns.map { column ->
        if (column.unit.isNotEmpty()) {
            "${column.name.take(8)} (${column.unit})"
        } else {
            column.name.take(10)
        }
    }
    
    val allHeaders = basicHeaders + customHeaders
    
    // Calculate dynamic column positions based on header text length
    val leftMargin = 30f
    val rightMargin = 30f
    val availableWidth = pageWidth - leftMargin - rightMargin
    
    // Create header paint for text measurement
    val headerPaint = Paint().apply {
        color = android.graphics.Color.BLACK
        textSize = 10f
        typeface = android.graphics.Typeface.DEFAULT_BOLD
    }
    
    val (columnWidths, colPositions) = calculateColumnWidths(allHeaders, availableWidth, headerPaint)
    
    val dataPaint = Paint().apply {
        color = android.graphics.Color.BLACK
        textSize = 9f
    }
    
    val linePaint = Paint().apply {
        color = android.graphics.Color.BLACK
        strokeWidth = 1f
    }
    
    // Pagination
    val entriesPerPage = 20
    val totalPages = (validEntries.size + entriesPerPage - 1) / entriesPerPage
    
    for (pageNum in 0 until totalPages) {
        val pageInfo = PdfDocument.PageInfo.Builder(pageWidth, pageHeight, pageNum + 2).create()
        val page = pdfDocument.startPage(pageInfo)
        val canvas = page.canvas
        
        // Draw title
        canvas.drawText(labels["title"] ?: "Diabetes Tracker - Data Export", 50f, 50f, titlePaint)
        
        // Draw table headers
        val startY = 100f
        val rowHeight = 25f
        
        allHeaders.forEachIndexed { index, header ->
            canvas.drawText(header, colPositions[index], startY, headerPaint)
        }
        
        // Draw horizontal line under header
        canvas.drawLine(leftMargin, startY + 10f, pageWidth - rightMargin, startY + 10f, linePaint)
        
        // Draw data rows
        val startIndex = pageNum * entriesPerPage
        val endIndex = minOf(startIndex + entriesPerPage, validEntries.size)
        
        for (i in startIndex until endIndex) {
            val entry = validEntries[i]
            val rowY = startY + ((i - startIndex + 1) * rowHeight) + 15f
            
            // Format date
            val formattedDate = try {
                val parsedDate = java.time.LocalDate.parse(entry.date)
                parsedDate.format(java.time.format.DateTimeFormatter.ofPattern("MM/dd/yyyy"))
            } catch (e: Exception) {
                entry.date
            }
            
            // Create data row with basic data + custom column data
            val basicData = listOf(
                formattedDate,
                entry.morningBloodSugarLevel,
                entry.afternoonBloodSugarLevel,
                entry.eveningBloodSugarLevel,
                entry.nightBloodSugarLevel,
                entry.morningInsulin,
                entry.afternoonInsulin,
                entry.eveningInsulin,
                if (entry.remarks.length > 15) entry.remarks.take(12) + "..." else entry.remarks
            )
            
            val customData = customColumns.map { column ->
                val value = entry.customColumnData[column.id] ?: ""
                if (value.length > 10) value.take(8) + "..." else value
            }
            
            val allData = basicData + customData
            
            // Draw all data columns
            allData.forEachIndexed { index, data ->
                canvas.drawText(data, colPositions[index], rowY, dataPaint)
            }
        }
        
        // Draw page number
        canvas.drawText("Page ${pageNum + 2} of ${totalPages + 1}", pageWidth - 150f, pageHeight - 30f, dataPaint)
        
        pdfDocument.finishPage(page)
    }
    
    return pdfDocument
}

// Helper function to draw chart on canvas (extracted for reuse)
fun drawChart(canvas: Canvas, chartData: List<Pair<String, Float>>, chartLabel: String, yAxisLabel: String) {
    if (chartData.isEmpty()) return
    
    val textPaint = Paint().apply {
        color = android.graphics.Color.BLACK
        textSize = 12f
    }
    
    val axisPaint = Paint().apply {
        color = android.graphics.Color.BLACK
        strokeWidth = 2f
    }
    
    val linePaint = Paint().apply {
        color = android.graphics.Color.BLUE
        strokeWidth = 3f
        style = Paint.Style.STROKE
    }
    
    val gridPaint = Paint().apply {
        color = android.graphics.Color.LTGRAY
        strokeWidth = 1f
    }
    
    // Chart dimensions
    val chartLeft = 80f
    val chartTop = 100f
    val chartWidth = 650f
    val chartHeight = 350f
    val chartRight = chartLeft + chartWidth
    val chartBottom = chartTop + chartHeight
    
    // Draw chart axes
    canvas.drawLine(chartLeft, chartBottom, chartRight, chartBottom, axisPaint) // X-axis
    canvas.drawLine(chartLeft, chartTop, chartLeft, chartBottom, axisPaint) // Y-axis
    
    // Calculate data ranges
    val maxValue = chartData.maxOfOrNull { it.second } ?: 0f
    val minValue = chartData.minOfOrNull { it.second } ?: 0f
    val valueRange = maxValue - minValue
    val safeRange = if (valueRange == 0f) 1f else valueRange
    
    // Draw grid lines and labels
    val gridLines = 5
    for (i in 0..gridLines) {
        val y = chartBottom - (i * chartHeight / gridLines)
        val value = minValue + (i * safeRange / gridLines)
        
        // Grid line
        canvas.drawLine(chartLeft, y, chartRight, y, gridPaint)
        
        // Y-axis label
        canvas.drawText(String.format("%.1f", value), chartLeft - 40f, y + 5f, textPaint)
    }
    
    // Draw Y-axis label
    canvas.save()
    canvas.rotate(-90f, 30f, chartTop + chartHeight / 2)
    canvas.drawText(yAxisLabel, 30f, chartTop + chartHeight / 2, textPaint)
    canvas.restore()
    
    // Draw data points and lines
    if (chartData.size > 1) {
        val path = android.graphics.Path()
        var isFirstPoint = true
        
        chartData.forEachIndexed { index, (date, value) ->
            val x = chartLeft + (index * chartWidth / (chartData.size - 1))
            val y = chartBottom - ((value - minValue) / safeRange * chartHeight)
            
            if (isFirstPoint) {
                path.moveTo(x, y)
                isFirstPoint = false
            } else {
                path.lineTo(x, y)
            }
            
            // Draw data point
            canvas.drawCircle(x, y, 4f, linePaint)
        }
        
        // Draw line connecting points
        canvas.drawPath(path, linePaint)
    }
    
    // Draw X-axis labels (dates)
    val maxLabels = 10
    val labelStep = maxOf(1, chartData.size / maxLabels)
    
    chartData.forEachIndexed { index, (date, _) ->
        if (index % labelStep == 0) {
            val x = chartLeft + (index * chartWidth / (chartData.size - 1))
            
            val displayDate = try {
                val parsedDate = java.time.LocalDate.parse(date)
                parsedDate.format(java.time.format.DateTimeFormatter.ofPattern("MM/dd"))
            } catch (e: Exception) {
                date.take(5)
            }
            
            // Draw horizontal date label
            canvas.drawText(displayDate, x, chartBottom + 20f, textPaint)
        }
    }
    
    // Draw X-axis label
    canvas.drawText("Date", chartLeft + chartWidth / 2, chartBottom + 80f, textPaint)
}

// PDF Generation Function for user-selected file (more reliable)
fun generatePDFToFile(context: Context, entries: List<DiabetesEntry>, language: String, fileUri: Uri, includeTable: Boolean = true, includeChart: Boolean = false, chartTypes: List<String> = listOf("morning"), useCustomDateRange: Boolean = false, startDate: String = "", endDate: String = "") {
    try {
        // Filter entries with valid dates and data
        var validEntries = entries.filter { entry ->
            entry.date.isNotBlank() && (
                entry.morningBloodSugarLevel.isNotBlank() ||
                entry.afternoonBloodSugarLevel.isNotBlank() ||
                entry.eveningBloodSugarLevel.isNotBlank() ||
                entry.nightBloodSugarLevel.isNotBlank() ||
                entry.morningInsulin.isNotBlank() ||
                entry.afternoonInsulin.isNotBlank() ||
                entry.eveningInsulin.isNotBlank() ||
                entry.remarks.isNotBlank()
            )
        }
        
        // Apply date range filter if custom range is selected
        if (useCustomDateRange && startDate.isNotBlank() && endDate.isNotBlank()) {
            try {
                val startLocalDate = java.time.LocalDate.parse(startDate)
                val endLocalDate = java.time.LocalDate.parse(endDate)
                
                validEntries = validEntries.filter { entry ->
                    try {
                        val convertedEntryDate = convertEntryDateForComparison(entry.date)
                        val entryDate = java.time.LocalDate.parse(convertedEntryDate)
                        !entryDate.isBefore(startLocalDate) && !entryDate.isAfter(endLocalDate)
                    } catch (e: Exception) {
                        false // Exclude entries with invalid date format
                    }
                }
            } catch (e: Exception) {
                Toast.makeText(context, "Invalid date format. Please use YYYY-MM-DD", Toast.LENGTH_SHORT).show()
                return
            }
        }
        
        if (validEntries.isEmpty()) {
            Toast.makeText(context, "No data to export", Toast.LENGTH_SHORT).show()
            return
        }
        
        // Create and write PDF directly to the selected file
        context.contentResolver.openOutputStream(fileUri)?.use { outputStream ->
            val pdfDocument = if (includeTable && !includeChart) {
                // Table only
                createPDFDocument(validEntries, language, context)
            } else if (!includeTable && includeChart) {
                // Charts only (single or multiple)
                if (chartTypes.size == 1) {
                    createChartPDFDocument(validEntries, language, context, chartTypes.first())
                } else {
                    createMultiChartPDFDocument(validEntries, language, context, chartTypes)
                }
            } else if (includeTable && includeChart) {
                // Both table and charts
                if (chartTypes.size == 1) {
                    createCombinedPDFDocument(validEntries, language, context, chartTypes.first())
                } else {
                    createMultiChartWithTablePDFDocument(validEntries, language, context, chartTypes)
                }
            } else {
                // Default to table if nothing selected
                createPDFDocument(validEntries, language, context)
            }
            pdfDocument.writeTo(outputStream)
            pdfDocument.close()
        }
        
        Toast.makeText(context, "PDF exported successfully", Toast.LENGTH_LONG).show()
        
    } catch (e: Exception) {
        e.printStackTrace()
        Toast.makeText(context, "Failed to export PDF: ${e.message}", Toast.LENGTH_SHORT).show()
    }
}

